export const COURSE: SeoLevel[] = [{"id":"beginner","slug":"beginner","title":"Beginner","cefr":"Noldan","text":"Ingliz tilini umuman bilmayman yoki juda kam bilaman. Harflar va tovushlardan boshlaymiz.","units":[{"id":"u1","n":1,"title":"Letters & Sounds","titleUz":"Alifbo va tovushlar: o'qish va talaffuz","description":"Alifbo, ingliz tovushlari, salomlashish, sonlar va birinchi so'zlar.","canDo":["Inglizcha alifboni aytaman","Ismimni harflab ayta olaman","Salomlashib, xayrlashaman","0 dan 20 gacha sanayman"],"lessons":[{"id":"u1-l1","slug":"the-alphabet-a-m","title":"The alphabet: A–M","titleUz":"Alifbo: A–M","goal":"Ingliz alifbosining birinchi 13 ta harfini nomi bilan to'g'ri aytasiz, ularni quloq bilan ajratasiz va shu harflar bilan boshlanadigan 10 ta so'zni bilib olasiz.","words":[{"en":"apple","uz":"olma","ipa":"ˈæp.əl"},{"en":"bag","uz":"sumka","ipa":"bæɡ"},{"en":"cat","uz":"mushuk","ipa":"kæt"},{"en":"dog","uz":"it","ipa":"dɒɡ"},{"en":"egg","uz":"tuxum","ipa":"eɡ"},{"en":"fish","uz":"baliq","ipa":"fɪʃ"},{"en":"girl","uz":"qiz bola","ipa":"ɡɜːl"},{"en":"hand","uz":"qo'l (kaft)","ipa":"hænd"},{"en":"key","uz":"kalit","ipa":"kiː"},{"en":"man","uz":"erkak","ipa":"mæn"}],"summary":["Ingliz alifbosida 26 ta harf bor; bugun A–M ni o'rgandik.","Eng muhim tuzoqlar: E = \"i:\", I = \"ay\", G = \"dji:\", J = \"djey\".","Guruhlar: ey (A, H, J, K) · i: (B, C, D, E, G) · e (F, L, M).","I (men), ismlar va gap boshi — doim katta harf bilan.","Yangi so'zlar: apple, bag, cat, dog, egg, fish, girl, hand, key, man."]},{"id":"u1-l2","slug":"the-alphabet-n-z","title":"The alphabet: N–Z","titleUz":"Alifbo: N–Z","goal":"Alifboning qolgan 13 ta harfini (N–Z) nomi bilan to'g'ri aytasiz, butun alifboni boshidan oxirigacha ayta olasiz va shu harflar bilan boshlanadigan 10 ta yangi so'zni bilib olasiz.","words":[{"en":"nose","uz":"burun","ipa":"nəʊz"},{"en":"orange","uz":"apelsin","ipa":"ˈɒr.ɪndʒ"},{"en":"pen","uz":"ruchka","ipa":"pen"},{"en":"queen","uz":"qirolicha","ipa":"kwiːn"},{"en":"sun","uz":"quyosh","ipa":"sʌn"},{"en":"table","uz":"stol","ipa":"ˈteɪ.bəl"},{"en":"umbrella","uz":"soyabon","ipa":"ʌmˈbrel.ə"},{"en":"van","uz":"furgon (yuk mashinasi)","ipa":"væn"},{"en":"water","uz":"suv","ipa":"ˈwɔː.tə"},{"en":"zoo","uz":"hayvonot bog'i","ipa":"zuː"}],"summary":["Endi butun alifboni bilasiz: A–M va N–Z, jami 26 ta harf.","Tuzoqlar: R = \"a:\", O = \"ou\", U = \"yu:\", W = \"dabl yu:\", Y = \"uay\", Z = \"zed\".","Unli harflar: A, E, I, O, U. Unli bilan boshlansa — an: an orange, an umbrella.","W — lablar dumaloq, \"v\" emas: water (\"uo:ta\").","Yangi so'zlar: nose, orange, pen, queen, sun, table, umbrella, van, water, zoo."]},{"id":"u1-l3","slug":"vowel-sounds-short-long","title":"Vowel sounds: short & long","titleUz":"Unli tovushlar: qisqa va cho'ziq","goal":"Har bir unli harfning qisqa va uzun o'qilishini ajratasiz, \"sehrli e\" qoidasi bilan hat va hate kabi so'zlarni to'g'ri o'qiysiz hamda 10 ta yangi so'zni bilib olasiz.","words":[{"en":"hat","uz":"shlyapa","ipa":"hæt"},{"en":"hate","uz":"yomon ko'rmoq","ipa":"heɪt"},{"en":"bed","uz":"karavot","ipa":"bed"},{"en":"sit","uz":"o'tirmoq","ipa":"sɪt"},{"en":"kite","uz":"varrak","ipa":"kaɪt"},{"en":"hot","uz":"issiq","ipa":"hɒt"},{"en":"home","uz":"uy","ipa":"həʊm"},{"en":"cut","uz":"kesmoq","ipa":"kʌt"},{"en":"cute","uz":"yoqimtoy, shirin","ipa":"kjuːt"},{"en":"tree","uz":"daraxt","ipa":"triː"}],"summary":["Har bir unli ikki xil o'qiladi: qisqa (hat, bed, sit, hot, cut) va uzun — harf nomi (hate, tree, kite, home, cute).","Sehrli e: unli + undosh + e → unli o'z nomini aytadi, e esa eshitilmaydi: kit → kite.","Qisqa u — \"a\"ga o'xshaydi: cut = \"kat\", bus = \"bas\".","ee — uzun \"i:\": tree.","Yangi so'zlar: hat, hate, bed, sit, kite, hot, home, cut, cute, tree."]},{"id":"u1-l4","slug":"letter-teams-sh-ch-th","title":"Letter teams: sh, ch, th…","titleUz":"Harf birikmalari: sh, ch, th…","goal":"sh, ch, th, ph, wh, ck, ng, ee, oo harf birikmalarini ko'rganda to'g'ri o'qiysiz, ayniqsa o'zbek tilida yo'q th tovushini talaffuz qila olasiz va 10 ta yangi so'zni bilib olasiz.","words":[{"en":"ship","uz":"kema","ipa":"ʃɪp"},{"en":"chicken","uz":"tovuq","ipa":"ˈtʃɪk.ɪn"},{"en":"think","uz":"o'ylamoq","ipa":"θɪŋk"},{"en":"photo","uz":"surat, foto","ipa":"ˈfəʊ.təʊ"},{"en":"whale","uz":"kit","ipa":"weɪl"},{"en":"duck","uz":"o'rdak","ipa":"dʌk"},{"en":"sing","uz":"kuylamoq","ipa":"sɪŋ"},{"en":"sheep","uz":"qo'y","ipa":"ʃiːp"},{"en":"book","uz":"kitob","ipa":"bʊk"},{"en":"food","uz":"ovqat","ipa":"fuːd"}],"summary":["Harf birikmasi = bitta tovush: sh (ship), ch (chicken), ng (sing), ph = \"f\" (photo), ck = \"k\" (duck).","th — til uchi tishlar orasida: jarangsiz (think, three) va jarangli (this, the).","wh / w — lablar dumaloq, \"v\" emas: whale, water. Istisno: who = \"hu:\".","ee = uzun \"i:\" (sheep); oo = uzun \"u:\" (food) yoki qisqa \"u\" (book).","Yangi so'zlar: ship, chicken, think, photo, whale, duck, sing, sheep, book, food."]},{"id":"u1-l5","slug":"hello-greetings","title":"Hello! Greetings","titleUz":"Salomlashish va xayrlashish","goal":"Kunning vaqtiga mos salomlashasiz, o'zingizni tanishtirasiz (Hello, I'm… / My name is…), hol-ahvol so'raysiz va xayrlashasiz. please, thank you, sorry kabi odob so'zlarini to'g'ri ishlatasiz.","words":[{"en":"hello","uz":"salom","ipa":"həˈləʊ"},{"en":"hi","uz":"salom (do'stona)","ipa":"haɪ"},{"en":"good morning","uz":"xayrli tong","ipa":"ɡʊd ˈmɔː.nɪŋ"},{"en":"good afternoon","uz":"xayrli kun (tushdan keyin)","ipa":"ɡʊd ˌɑːf.təˈnuːn"},{"en":"good evening","uz":"xayrli kech","ipa":"ɡʊd ˈiːv.nɪŋ"},{"en":"good night","uz":"xayrli tun","ipa":"ɡʊd ˈnaɪt"},{"en":"goodbye","uz":"xayr","ipa":"ɡʊdˈbaɪ"},{"en":"please","uz":"iltimos","ipa":"pliːz"},{"en":"thank you","uz":"rahmat","ipa":"ˈθæŋk juː"},{"en":"sorry","uz":"kechirasiz, uzr","ipa":"ˈsɒr.i"}],"summary":["Salom: Hello (hamma uchun), Hi (do'stona). Vaqtga qarab: Good morning / afternoon / evening.","Good night — faqat xayrlashganda! Xayr: Goodbye, Bye.","Tanishish: I'm Ali. / My name is Ali. — Nice to meet you. — Nice to meet you, too.","How are you? — I'm fine, thanks. And you? (\"am\" ni tushirmang: I'm).","Odob so'zlari: please, thank you (th!), sorry."]},{"id":"u1-l11","slug":"real-life-meeting-someone-new","title":"Real life: meeting someone new","titleUz":"Real hayot: yangi odam bilan tanishish","goal":"Yangi odam bilan salomlashasiz, ismingizni aytasiz, «Qalaysiz?» ga javob berasiz va xayrlashasiz. Faqat 1–5-darslarda o'rganganlaringiz kerak bo'ladi.","words":[],"summary":["Good morning — ertalab, Good night — tunda; vaqtga mos salom tanlang.","My name is Ali. yoki I'm Ali. — o'zingizni tanishtirish.","How are you? → I'm fine, thank you. (I'm = I am: «I fine» demaymiz).","Nice to meet you. — «Tanishganimdan xursandman.»"]},{"id":"u1-l6","slug":"numbers-0-20","title":"Numbers 0–20","titleUz":"Sonlar 0–20","goal":"0 dan 20 gacha sonlarni to'g'ri aytasiz, yozasiz va quloq bilan ajratasiz; -teen sonlarining urg'usini bilasiz va yoshingizni, telefon raqamini inglizcha ayta olasiz.","words":[{"en":"zero","uz":"nol","ipa":"ˈzɪə.rəʊ"},{"en":"three","uz":"uch","ipa":"θriː"},{"en":"five","uz":"besh","ipa":"faɪv"},{"en":"eight","uz":"sakkiz","ipa":"eɪt"},{"en":"eleven","uz":"o'n bir","ipa":"ɪˈlev.ən"},{"en":"twelve","uz":"o'n ikki","ipa":"twelv"},{"en":"thirteen","uz":"o'n uch","ipa":"ˌθɜːˈtiːn"},{"en":"fifteen","uz":"o'n besh","ipa":"ˌfɪfˈtiːn"},{"en":"eighteen","uz":"o'n sakkiz","ipa":"ˌeɪˈtiːn"},{"en":"twenty","uz":"yigirma","ipa":"ˈtwen.ti"}],"summary":["0–10: zero, one, two, three, four, five, six, seven, eight, nine, ten. Tuzoqlar: one = \"uan\", two = \"tu:\", eight = \"eyt\".","11, 12 — alohida so'zlar: eleven, twelve. 13–19 = son + -teen.","Imlo tuzoqlari: thirteen, fifteen, eighteen (bitta t).","Urg'u: thirTEEN (13) ↔ THIRty (30).","Yosh: I'm twelve. (\"I have twelve\" emas). Telefon: raqamma-raqam, 0 = oh, 55 = double five."]},{"id":"u1-l7","slug":"how-do-you-spell-it","title":"How do you spell it?","titleUz":"Harflab aytish va sinf iboralari","goal":"Ismingizni va so'zlarni harfma-harf aytasiz (How do you spell…?), o'qituvchining topshiriqlarini (Open your books, Listen and repeat) tushunasiz va darsda kerakli iboralarni (Sorry, I don't understand. Can you repeat that, please?) ishlatasiz.","words":[{"en":"name","uz":"ism","ipa":"neɪm"},{"en":"spell","uz":"harflab aytmoq","ipa":"spel"},{"en":"letter","uz":"harf","ipa":"ˈlet.ə"},{"en":"word","uz":"so'z","ipa":"wɜːd"},{"en":"repeat","uz":"takrorlamoq","ipa":"rɪˈpiːt"},{"en":"listen","uz":"tinglamoq","ipa":"ˈlɪs.ən"},{"en":"read","uz":"o'qimoq","ipa":"riːd"},{"en":"write","uz":"yozmoq","ipa":"raɪt"},{"en":"open","uz":"ochmoq","ipa":"ˈəʊ.pən"},{"en":"close","uz":"yopmoq","ipa":"kləʊz"}],"summary":["Savol: How do you spell your name? — javob harflar nomi bilan: A-Z-I-Z.","Ikki bir xil harf — double: Anna = A, double N, A. Tutuq belgisi — apostrophe.","Topshiriqlar: Open / Close your books. Listen and repeat. Read. Write.","Kerakli iboralar: Sorry, I don't understand. Can you repeat that, please?","Talaffuz: write (w yo'q), listen (t yo'q), read = \"ri:d\", close = \"klouz\"."]},{"id":"u1-l8","slug":"colours-things","title":"Colours & things","titleUz":"Ranglar va narsalar","goal":"Asosiy ranglarni va big, small, new sifatlarini to'g'ri aytasiz, ularni ot oldiga qo'yib narsalarni tasvirlaysiz (a red bag, an orange, a big dog) va What colour is it? — It's blue. savol-javobini ishlatasiz.","words":[{"en":"red","uz":"qizil","ipa":"red"},{"en":"blue","uz":"ko'k, havorang","ipa":"bluː"},{"en":"green","uz":"yashil","ipa":"ɡriːn"},{"en":"yellow","uz":"sariq","ipa":"ˈjel.əʊ"},{"en":"black","uz":"qora","ipa":"blæk"},{"en":"white","uz":"oq","ipa":"waɪt"},{"en":"brown","uz":"jigarrang","ipa":"braʊn"},{"en":"big","uz":"katta","ipa":"bɪɡ"},{"en":"small","uz":"kichik","ipa":"smɔːl"},{"en":"new","uz":"yangi","ipa":"njuː"}],"summary":["Ranglar: red, blue, green, yellow, black, white, brown (+ orange, pink, grey).","Sifat otdan oldin keladi, o'zbekchadagidek: a red bag, a big dog. Sifat o'zgarmaydi.","a / an birinchi so'zga qarab: an apple → a red apple; a bag → an orange bag.","Ikki sifat: avval o'lcham, keyin rang — a big black dog.","What colour is it? — It's blue. Rang aytganda is shart: The bag is blue."]},{"id":"u1-l9","slug":"meeting-someone-name-spelling-numbers","title":"Meeting someone: name, spelling, numbers","titleUz":"Yangi tanish: ism, harflash, raqam","goal":"Yangi odam bilan tanishasiz, ismingizni harflab aytasiz va telefon raqamingizni raqam-raqam diktant qilasiz. Hammasi 1–8-darslarda o'rganganlaringiz asosida.","words":[{"en":"surname","uz":"familiya","ipa":"ˈsɜː.neɪm"},{"en":"phone","uz":"telefon","ipa":"fəʊn"},{"en":"number","uz":"raqam, son","ipa":"ˈnʌm.bə"},{"en":"again","uz":"yana, qayta","ipa":"əˈɡen"}],"summary":["Tanishuv: Good morning. I'm… — Nice to meet you, too.","Ism so'rash: What's your name? How do you spell it? Harflar nomi bilan aytiladi.","Telefon raqami raqam-raqam aytiladi: nine, zero, one…","Tushunmasangiz: Can you repeat that, please?"]},{"id":"u1-l12","slug":"real-life-at-the-registration-desk","title":"Real life: at the registration desk","titleUz":"Real hayot: ro'yxatdan o'tish stolida","goal":"Til maktabida ro'yxatdan o'tasiz: ismingizni aytasiz, familiyangizni harflab berasiz, telefon raqamingizni raqam-raqam aytasiz, tushunmasangiz muloyim takrorlashni so'raysiz va xayrlashasiz.","words":[],"summary":["My name is Ali Karimov. — ism va familiyani aytish.","Familiya harflab aytiladi: K-A-R-I-M-O-V (harflar nomi bilan).","Telefon raqami raqam-raqam aytiladi: nine, zero, five… Nol — zero.","Tushunmasangiz: Sorry, can you repeat that, please? (Repeat! qo'pol eshitiladi).","Minnatdorchilik: Thank you. — Nice to meet you, too."]},{"id":"u1-l10","slug":"letters-sounds-final-review","title":"Letters & sounds: final review","titleUz":"Alifbo va tovushlar: yakuniy takror","goal":"1-bo'limdagi hamma narsani takrorlaysiz: alifbo, unlilar, harf juftliklari, salomlashish, 0–20 raqamlar, harflab aytish va ranglar. Bo'lim oxirida o'zingizni sinab ko'rasiz.","words":[{"en":"alphabet","uz":"alifbo","ipa":"ˈæl.fə.bet"},{"en":"vowel","uz":"unli harf","ipa":"ˈvaʊ.əl"},{"en":"sound","uz":"tovush","ipa":"saʊnd"},{"en":"colour","uz":"rang","ipa":"ˈkʌl.ə"}],"summary":["Alifbo — 26 harf; unlilar a, e, i, o, u; sehrli e unlini uzun qiladi (hat → hate).","Harf juftliklari: sh, ch, th, ph, ng, oo — bitta tovush beradi.","Salom va tanishuv: Hello, I'm… / Nice to meet you. / I'm fine, thanks.","Raqamlar 0–20, ranglar va a / an — gaplarda ishlating.","Harflash: How do you spell it? — harflar nomi bilan, double bilan."]}]},{"id":"u2","n":2,"title":"To be: Who am I?","titleUz":"Men kimman? Olmoshlar va to be (am / is / are)","description":"Olmoshlar, am / is / are, inkor va savol, a / an, ko'plik, this / that, egalik.","canDo":["O'zim va boshqalar haqida am / is / are bilan gapiraman","Kasb va millatni ayta olaman","a / an va ko'plikni to'g'ri ishlataman","this / that, my / your bilan narsalarni ko'rsataman"],"lessons":[{"id":"u2-l1","slug":"personal-pronouns","title":"Personal pronouns","titleUz":"Kishilik olmoshlari","goal":"Ingliz tilidagi 7 ta kishilik olmoshini (I, you, he, she, it, we, they) to'g'ri aytasiz va ishlatasiz: odam va narsalar o'rniga mos olmoshni tanlaysiz, ayniqsa o'zbekcha \"u\" ni he / she / it ga to'g'ri ajratasiz.","words":[{"en":"friend","uz":"do'st","ipa":"frend"},{"en":"teacher","uz":"o'qituvchi","ipa":"ˈtiː.tʃə"},{"en":"student","uz":"talaba, o'quvchi","ipa":"ˈstjuː.dənt"},{"en":"boy","uz":"o'g'il bola","ipa":"bɔɪ"},{"en":"woman","uz":"ayol","ipa":"ˈwʊm.ən"},{"en":"neighbour","uz":"qo'shni","ipa":"ˈneɪ.bə"},{"en":"classmate","uz":"sinfdosh","ipa":"ˈklɑːs.meɪt"},{"en":"guest","uz":"mehmon","ipa":"ɡest"},{"en":"colleague","uz":"hamkasb","ipa":"ˈkɒl.iːɡ"},{"en":"team","uz":"jamoa","ipa":"tiːm"}],"summary":["7 ta olmosh: I (men), you (sen/siz/sizlar), he, she, it (u), we (biz), they (ular).","O'zbekcha \"u\" = he (erkak), she (ayol), it (narsa, hayvon).","you — sen ham, siz ham, sizlar ham; they — odamlar ham, narsalar ham.","Ingliz gapida ega doim aytiladi: I'm a student, \"Am a student\" emas. I doim katta harf.","Yangi so'zlar: friend, teacher, student, boy, woman, neighbour, classmate, guest, colleague, team."]},{"id":"u2-l2","slug":"to-be-am-is-are","title":"To be: am / is / are","titleUz":"To be: am / is / are","goal":"am / is / are ni har bir olmosh va ism bilan to'g'ri tanlaysiz, qisqa shakllarni (I'm, he's, they're…) aytasiz va o'zingiz hamda boshqalar haqida I'm tired, She's a teacher kabi gaplar tuzasiz.","words":[{"en":"happy","uz":"xursand, baxtli","ipa":"ˈhæp.i"},{"en":"sad","uz":"xafa, g'amgin","ipa":"sæd"},{"en":"tired","uz":"charchagan","ipa":"ˈtaɪəd"},{"en":"hungry","uz":"och (qorni och)","ipa":"ˈhʌŋ.ɡri"},{"en":"thirsty","uz":"chanqagan","ipa":"ˈθɜː.sti"},{"en":"busy","uz":"band","ipa":"ˈbɪz.i"},{"en":"ready","uz":"tayyor","ipa":"ˈred.i"},{"en":"late","uz":"kechikkan, kech","ipa":"leɪt"},{"en":"angry","uz":"jahli chiqqan, g'azablangan","ipa":"ˈæŋ.ɡri"},{"en":"fine","uz":"yaxshi (sog')","ipa":"faɪn"}],"summary":["Ingliz tilida \"kim/qanday\" gaplarida to be shart: I am a student, \"I student\" emas.","I → am, he / she / it → is, you / we / they → are.","Qisqa shakllar: I'm, you're, he's, she's, it's, we're, they're.","Holatlar to be bilan: I'm hungry, I'm tired, I'm late, I'm 18.","Yangi so'zlar: happy, sad, tired, hungry, thirsty, busy, ready, late, angry, fine."]},{"id":"u2-l3","slug":"to-be-negatives","title":"To be: negatives","titleUz":"To be: inkor gaplar","goal":"am / is / are dan keyin not qo'yib inkor gap tuzasiz (I'm not tired, She isn't old), ikkala qisqa shaklni ham bilasiz va odamlar hamda narsalarni qarama-qarshi sifatlar bilan tasvirlaysiz.","words":[{"en":"tall","uz":"baland bo'yli, baland","ipa":"tɔːl"},{"en":"short","uz":"past bo'yli, qisqa","ipa":"ʃɔːt"},{"en":"young","uz":"yosh","ipa":"jʌŋ"},{"en":"old","uz":"qari, keksa; eski","ipa":"əʊld"},{"en":"beautiful","uz":"go'zal, chiroyli","ipa":"ˈbjuː.tɪ.fəl"},{"en":"rich","uz":"boy","ipa":"rɪtʃ"},{"en":"poor","uz":"kambag'al","ipa":"pɔː"},{"en":"cheap","uz":"arzon","ipa":"tʃiːp"},{"en":"expensive","uz":"qimmat","ipa":"ɪkˈspen.sɪv"},{"en":"clean","uz":"toza","ipa":"kliːn"}],"summary":["Inkor: am / is / are + not: I am not, he is not, they are not.","Qisqa shakllar: I'm not; isn't / 's not; aren't / 're not. \"I amn't\" — yo'q!","Xato qilmang: \"I not tired\", \"He not is\", \"I don't tired\" — noto'g'ri.","Juft sifatlar: tall–short, young–old, rich–poor, cheap–expensive, clean–dirty.","Yangi so'zlar: tall, short, young, old, beautiful, rich, poor, cheap, expensive, clean."]},{"id":"u2-l4","slug":"to-be-questions","title":"To be: questions","titleUz":"To be: savollar va qisqa javoblar","goal":"Are you…? Is she…? kabi savollar berasiz, ularga Yes, I am / No, I'm not shaklida to'g'ri qisqa javob qaytarasiz va odamlar qayerdaligini (at home, at work, at school) so'raysiz.","words":[{"en":"home","uz":"uy (o'z uyi)","ipa":"həʊm"},{"en":"school","uz":"maktab","ipa":"skuːl"},{"en":"work","uz":"ish","ipa":"wɜːk"},{"en":"office","uz":"ofis, idora","ipa":"ˈɒf.ɪs"},{"en":"shop","uz":"do'kon","ipa":"ʃɒp"},{"en":"park","uz":"bog', park","ipa":"pɑːk"},{"en":"hospital","uz":"kasalxona","ipa":"ˈhɒs.pɪ.təl"},{"en":"bank","uz":"bank","ipa":"bæŋk"},{"en":"library","uz":"kutubxona","ipa":"ˈlaɪ.brər.i"},{"en":"market","uz":"bozor","ipa":"ˈmɑː.kɪt"}],"summary":["Savolda am / is / are boshiga chiqadi: You are → Are you…?","Qisqa javob: Yes, I am. / No, I'm not. · Yes, she is. / No, she isn't.","\"Yes, I'm\", \"Yes, he's\" — xato: ha javobida qisqartirilmaydi.","Javobda ism emas, olmosh: Is Ali at work? — Yes, he is.","Joylar: at home, at work, at school; at the office / shop / bank / library / market / hospital; in the park."]},{"id":"u2-l5","slug":"a-an-plurals","title":"a / an & plurals","titleUz":"a / an va ko'plik","goal":"a va an ni so'zning tovushiga qarab tanlaysiz (an hour, a university), otlarni ko'plikka to'g'ri o'tkazasiz (-s, -es, -ies, -ves va child → children kabi noto'g'ri shakllar) va -s oxirini /s/, /z/, /ɪz/ deb to'g'ri talaffuz qilasiz.","words":[{"en":"box","uz":"quti","ipa":"bɒks"},{"en":"bus","uz":"avtobus","ipa":"bʌs"},{"en":"watch","uz":"qo'l soati","ipa":"wɒtʃ"},{"en":"baby","uz":"chaqaloq, go'dak","ipa":"ˈbeɪ.bi"},{"en":"city","uz":"shahar","ipa":"ˈsɪt.i"},{"en":"knife","uz":"pichoq","ipa":"naɪf"},{"en":"child","uz":"bola","ipa":"tʃaɪld"},{"en":"person","uz":"odam, kishi","ipa":"ˈpɜː.sən"},{"en":"foot","uz":"oyoq (panja)","ipa":"fʊt"},{"en":"tooth","uz":"tish","ipa":"tuːθ"}],"summary":["Bitta sanaladigan narsa/odam oldidan a / an: I'm a student. It's a box. Ko'plikda — yo'q.","a / an tovushga qarab: an hour, an umbrella, lekin a university, a house.","Ko'plik: -s (cats), -es (buses, boxes, watches), -ies (babies, cities), -ves (knives).","Yod oling: children, people, men, women, feet, teeth. Sondan keyin doim ko'plik: two cats.","-s talaffuzi: /s/ cats · /z/ dogs · /ɪz/ buses."]},{"id":"u2-l12","slug":"a-an-sound-not-letter","title":"a / an: sound, not letter","titleUz":"a / an: harf emas, tovush hal qiladi","goal":"a yoki an ni so'zning birinchi harfiga emas, birinchi tovushiga qarab tanlaysiz: an hour, an honest man, a university, a European city. Tanlovni 3 soniyada qila olasiz.","words":[{"en":"hour","uz":"soat (60 daqiqa)","ipa":"aʊ.ər"},{"en":"honest","uz":"halol, rostgo'y","ipa":"ˈɒn.ɪst"},{"en":"university","uz":"universitet","ipa":"ˌjuː.nɪˈvɜː.sɪ.ti"},{"en":"uniform","uz":"forma (kiyim)","ipa":"ˈjuː.nɪ.fɔːm"},{"en":"European","uz":"yevropalik; Yevropa","ipa":"ˌjʊə.rəˈpiː.ən"},{"en":"onion","uz":"piyoz","ipa":"ˈʌn.jən"}],"summary":["a / an ni tovush hal qiladi: unli tovush → an, undosh tovush → a.","Harf unli, tovush undosh: a university, a uniform, a European city, a one-way street.","Harf undosh, tovush unli: an hour, an honest man (h jim), an MP3, an X-ray.","Shubha bo'lsa so'zni ovoz chiqarib ayting va birinchi tovushni eshiting."]},{"id":"u2-l13","slug":"plurals-spelling-rules","title":"Plurals: spelling rules","titleUz":"Ko'plik: -s, -es, -ies imlosi","goal":"Otning oxirgi harfiga qarab ko'plikni to'g'ri yozasiz (dish → dishes, party → parties, day → days, shelf → shelves) va ko'plik oxirini /s/, /z/, /ɪz/ deb to'g'ri o'qiysiz.","words":[{"en":"toy","uz":"o'yinchoq","ipa":"tɔɪ"},{"en":"class","uz":"sinf; dars","ipa":"klɑːs"},{"en":"story","uz":"hikoya","ipa":"ˈstɔː.ri"},{"en":"party","uz":"ziyofat, bazm","ipa":"ˈpɑː.ti"},{"en":"shelf","uz":"tokcha, javon","ipa":"ʃelf"},{"en":"tomato","uz":"pomidor","ipa":"təˈmɑː.təʊ"}],"summary":["Ko'pchilik otlar: -s (dogs, days, photos).","s, ss, x, sh, ch bilan tugasa: -es (dishes, classes); tomato, potato → tomatoes, potatoes.","Undosh + y → -ies (parties, stories); unli + y → -s (days, toys).","-f / -fe → -ves (shelves, lives, wives), lekin roofs.","Oxiri: /s/ cats · /z/ days · /ɪz/ dishes."]},{"id":"u2-l14","slug":"irregular-plurals","title":"Irregular plurals","titleUz":"Noto'g'ri ko'plik: child → children","goal":"Eng ko'p ishlatiladigan noto'g'ri ko'pliklarni guruhlab eslab qolasiz (man → men, foot → feet, child → children, sheep → sheep) va ular bilan are ishlatasiz: The children are happy.","words":[{"en":"mouse","uz":"sichqon","ipa":"maʊs"},{"en":"sheep","uz":"qo'y","ipa":"ʃiːp"},{"en":"deer","uz":"kiyik","ipa":"dɪər"},{"en":"goose","uz":"g'oz","ipa":"guːs"},{"en":"policeman","uz":"politsiyachi","ipa":"pəˈliːs.mən"},{"en":"businessman","uz":"tadbirkor","ipa":"ˈbɪz.nɪs.mæn"}],"summary":["Unli almashadi: man → men, woman → women, foot → feet, tooth → teeth, goose → geese, mouse → mice.","Alohida shakllar: child → children, person → people.","O'zgarmaydiganlar: sheep, fish, deer (ten sheep).","childs, peoples, mans, foots — mavjud emas. Ko'plikdagi gapda are: The children are happy."]},{"id":"u2-l6","slug":"this-that-these-those","title":"this / that / these / those","titleUz":"this / that / these / those","goal":"Yaqin va uzoqdagi narsalarni this / that / these / those bilan ko'rsatasiz, ularni is / are va birlik/ko'plik bilan to'g'ri moslaysiz, this va these ni talaffuzda ajratasiz hamda kiyim va buyumlar haqida gapirasiz.","words":[{"en":"phone","uz":"telefon","ipa":"fəʊn"},{"en":"window","uz":"deraza","ipa":"ˈwɪn.dəʊ"},{"en":"shoe","uz":"tufli, oyoq kiyim","ipa":"ʃuː"},{"en":"shirt","uz":"ko'ylak (erkaklar)","ipa":"ʃɜːt"},{"en":"dress","uz":"ko'ylak (ayollar)","ipa":"dres"},{"en":"cup","uz":"piyola, chashka","ipa":"kʌp"},{"en":"glass","uz":"stakan; shisha (material)","ipa":"ɡlɑːs"},{"en":"bottle","uz":"shisha, butilka","ipa":"ˈbɒt.əl"},{"en":"chair","uz":"stul","ipa":"tʃeə"},{"en":"jacket","uz":"kurtka, jaket","ipa":"ˈdʒæk.ɪt"}],"summary":["Yaqin: this (bitta) · these (ko'p). Uzoq: that (bitta) · those (ko'p).","this / that + is, these / those + are — va ot ham mos: these shoes.","Talaffuz: this — qisqa \"i\" + s; these — cho'ziq \"i:\" + z; th — til tishlar orasida.","Savolda: Is this…? / Are these…? — javobda it / they: Yes, it is. / No, they aren't.","Yangi so'zlar: phone, window, shoe, shirt, dress, cup, glass, bottle, chair, jacket."]},{"id":"u2-l7","slug":"my-your-his-and-s","title":"my, your, his… and 's","titleUz":"Egalik: my, your, his… va 's","goal":"Egalikni my, your, his, her, its, our, their va 's (Ali's car) bilan ifodalaysiz, his / her ni egasiga qarab tanlaysiz, it's va its ni ajratasiz hamda o'zingiz haqidagi shaxsiy ma'lumotni (familiya, manzil, telefon raqami, email) aytasiz.","words":[{"en":"surname","uz":"familiya","ipa":"ˈsɜː.neɪm"},{"en":"address","uz":"manzil","ipa":"əˈdres"},{"en":"phone number","uz":"telefon raqami","ipa":"ˈfəʊn ˌnʌm.bə"},{"en":"email","uz":"elektron pochta, email","ipa":"ˈiː.meɪl"},{"en":"birthday","uz":"tug'ilgan kun","ipa":"ˈbɜːθ.deɪ"},{"en":"car","uz":"mashina, avtomobil","ipa":"kɑː"},{"en":"house","uz":"uy (bino)","ipa":"haʊs"},{"en":"room","uz":"xona","ipa":"ruːm"},{"en":"wife","uz":"xotin, rafiqa","ipa":"waɪf"},{"en":"husband","uz":"er, turmush o'rtoq","ipa":"ˈhʌz.bənd"}],"summary":["Egalik so'zlari otdan oldin: my, your, his, her, its, our, their + ot.","his — egasi erkak, her — egasi ayol: Aziz and his wife, Malika and her husband.","Ismlar bilan 's: Ali's car, my friend's house (\"car of Ali\" emas).","it's = it is; its = uning (narsa). your / you're, their / they're — bir xil eshitiladi.","Yangi so'zlar: surname, address, phone number, email, birthday, car, house, room, wife, husband."]},{"id":"u2-l8","slug":"countries-nationalities-jobs","title":"Countries, nationalities & jobs","titleUz":"Davlatlar, millatlar va kasblar","goal":"Qayerdan ekaningizni (I'm from Uzbekistan), millatingizni (I'm Uzbek) va kasbingizni (I'm a doctor) to'g'ri aytasiz: davlat va millat nomlarini katta harf bilan yozasiz, kasb oldidan a / an qo'yasiz va bu bo'limda o'rganganlaringiz bilan o'zingizni to'liq tanishtirasiz.","words":[{"en":"country","uz":"davlat, mamlakat","ipa":"ˈkʌn.tri"},{"en":"Uzbekistan","uz":"O'zbekiston","ipa":"ʊzˌbek.ɪˈstɑːn"},{"en":"Uzbek","uz":"o'zbek; o'zbek tili","ipa":"ˈʊz.bek"},{"en":"England","uz":"Angliya","ipa":"ˈɪŋ.ɡlənd"},{"en":"English","uz":"ingliz; ingliz tili","ipa":"ˈɪŋ.ɡlɪʃ"},{"en":"doctor","uz":"shifokor","ipa":"ˈdɒk.tə"},{"en":"engineer","uz":"muhandis","ipa":"ˌen.dʒɪˈnɪə"},{"en":"driver","uz":"haydovchi","ipa":"ˈdraɪ.və"},{"en":"nurse","uz":"hamshira","ipa":"nɜːs"},{"en":"lawyer","uz":"huquqshunos, advokat","ipa":"ˈlɔɪ.ə"}],"summary":["Davlat: I'm from Uzbekistan. Millat: I'm Uzbek. (\"I'm from Uzbek\" — xato).","Davlat, millat va til nomlari doim katta harf bilan: Uzbek, English, Chinese.","Kasb oldidan a / an: She's a doctor. He's an engineer. Ko'plikda: They're doctors.","Urg'u: UzbekiSTAN, UZbek, JapaNESE, engiNEER, DOCtor.","Yangi so'zlar: country, Uzbekistan, Uzbek, England, English, doctor, engineer, driver, nurse, lawyer."]},{"id":"u2-l15","slug":"real-life-where-are-you-from","title":"Real life: where are you from?","titleUz":"Real hayot: qayerdansiz? kasbingiz nima?","goal":"Yangi sinfdosh bilan gaplashasiz: qayerdansiz, kasbingiz, millatingiz haqida aytasiz, qisqa javob berasiz (Yes, I am. / No, I'm not.) va unga qaytib savol berasiz.","words":[],"summary":["I'm from Uzbekistan. — I bilan har doim am (I from… demaymiz).","Kasb oldidan a / an: a student, an engineer (unli tovush oldida an).","Qisqa javob: Yes, I am. / No, I'm not. (Yes, I'm emas).","Davlat va millat: Uzbekistan (davlat) — Uzbek (millat): I'm Uzbek.","Qaytib so'rash: And where are you from?"]},{"id":"u2-l9","slug":"introducing-myself-and-my-family","title":"Introducing myself and my family","titleUz":"O'zim va oilam haqida tanishtirish","goal":"Yangi tanishingizga o'zingizni va oilangizni tanishtirasiz: I'm Aziz. This is my mother. She's a doctor. — to be, my / his / her va a / an bilan.","words":[{"en":"family","uz":"oila","ipa":"ˈfæm.əl.i"},{"en":"mother","uz":"ona","ipa":"ˈmʌð.ə"},{"en":"father","uz":"ota","ipa":"ˈfɑː.ðə"},{"en":"sister","uz":"opa, singil","ipa":"ˈsɪs.tə"}],"summary":["Tanishtirish: This is my mother. She's a teacher. — his / her ni to'g'ri tanlang.","Kasb oldidan a / an, ko'plikda esa yo'q: They're doctors.","Yangi so'zlar: family, mother, father, sister — o'z oilangiz haqida gapiring."]},{"id":"u2-l16","slug":"real-life-my-family-photo","title":"Real life: my family photo","titleUz":"Real hayot: oilaviy surat","goal":"Do'stingizga oilaviy suratni ko'rsatasiz: kim ekanini, ismini va yoshini aytasiz. my / his / her / their ni to'g'ri tanlaysiz va have bilan yosh aytmaysiz.","words":[],"summary":["This is my sister. — my = mening; They are my parents.","Her name is Madina. — qiz/ayol uchun her, o'g'il/erkak uchun his (He name emas).","How old is she? → She is sixteen. (yoshni be bilan aytamiz, have bilan emas).","Is this your father? → No, he isn't. He's my friend.","'s egalik: your sister's name, my father's name."]},{"id":"u2-l10","slug":"at-the-language-school-a-registration-form","title":"At the language school: a registration form","titleUz":"Til maktabida: ro'yxatdan o'tish anketasi","goal":"Til maktabida anketani to'ldirasiz va administrator savollariga javob berasiz: What's your name? Where are you from? What's your job? Davlat, kasb va a / an ni ishlatasiz.","words":[{"en":"form","uz":"anketa, blank","ipa":"fɔːm"},{"en":"first name","uz":"ism","ipa":"ˈfɜːst neɪm"},{"en":"nationality","uz":"millat, fuqarolik","ipa":"ˌnæʃ.ənˈæl.ə.ti"},{"en":"job","uz":"kasb, ish","ipa":"dʒɒb"}],"summary":["Anketa savollari: What's your…? Where are you from? How old are you?","Davlat: I'm from Uzbekistan. Millat: I'm Uzbek. Kasb: I'm a nurse / an engineer.","Yangi so'zlar: form, first name, nationality, job."]},{"id":"u2-l11","slug":"to-be-final-review","title":"To be: final review","titleUz":"To be: yakuniy takror","goal":"To be bo'limini yakunlaysiz: olmoshlar, am / is / are (darak, inkor, savol), a / an, ko'plik, this / that, my / his / her, davlat va kasblar — hammasi bitta joyda.","words":[{"en":"also","uz":"ham, shuningdek","ipa":"ˈɔːl.səʊ"},{"en":"only","uz":"faqat, atigi","ipa":"ˈəʊn.li"},{"en":"married","uz":"turmush qurgan, uylangan","ipa":"ˈmær.id"}],"summary":["I am, he / she / it is, you / we / they are. Inkor: isn't / aren't / am not. Savol: Is she…? Are you…?","Kasb oldidan a / an, ko'plikda yo'q. Davlat — from, millat — from siz.","This / that — bitta, these / those — bir nechta. Egalik: my, your, his, her."]}]},{"id":"u3","n":3,"title":"Everyday Life","titleUz":"Kundalik hayot: Present Simple","description":"Katta sonlar, Present Simple, vaqt, kun tartibi, in / on / at, always / never.","canDo":["Kun tartibimni aytib bera olaman","Soatni va sanani ayta olaman","Odatlarim haqida (always, never…) gapiraman","Do / Does bilan savol beraman"],"lessons":[{"id":"u3-l1","slug":"numbers-20-100-age-prices","title":"Numbers 20–100, age & prices","titleUz":"Sonlar 20–100, yosh va narx","goal":"20 dan 100 gacha sonlarni aytasiz va yozasiz, thirteen / thirty kabi juftliklarni quloq bilan ajratasiz, yoshingizni (I'm 25), narxni (How much is it?) va telefon raqamingizni inglizcha to'g'ri aytasiz.","words":[{"en":"thirty","uz":"o'ttiz (30)","ipa":"ˈθɜː.ti"},{"en":"forty","uz":"qirq (40)","ipa":"ˈfɔː.ti"},{"en":"fifty","uz":"ellik (50)","ipa":"ˈfɪf.ti"},{"en":"sixty","uz":"oltmish (60)","ipa":"ˈsɪk.sti"},{"en":"hundred","uz":"yuz (100)","ipa":"ˈhʌn.drəd"},{"en":"price","uz":"narx","ipa":"praɪs"},{"en":"money","uz":"pul","ipa":"ˈmʌn.i"},{"en":"dollar","uz":"dollar","ipa":"ˈdɒl.ə"},{"en":"sum","uz":"so'm (O'zbekiston puli)","ipa":"sʌm"},{"en":"how much","uz":"qancha (narx)","ipa":"haʊ ˈmʌtʃ"}],"summary":["O'nliklar -ty bilan tugaydi: twenty, thirty, forty (u'siz!), fifty, sixty, seventy, eighty, ninety, a hundred.","Murakkab son — chiziqcha bilan: twenty-one, fifty-eight.","-teen (13–19) urg'u oxirida, -ty (30–90) urg'u boshida: thirTEEN / THIRty.","Yosh: I'm 25 yoki I'm 25 years old — hech qachon \"I have 25\".","Narx: How much is it? — It's 30 dollars. Telefon raqam — raqamma-raqam, 0 = oh, 55 = double five."]},{"id":"u3-l2","slug":"present-simple-i-you-we-they","title":"Present Simple: I / you / we / they","titleUz":"Present Simple: I / you / we / they","goal":"O'zingiz va boshqalar haqida odatlar va doimiy faktlarni aytasiz: I live in Tashkent. We study English. Inglizcha so'z tartibini (ega + fe'l + to'ldiruvchi) to'g'ri qo'llaysiz.","words":[{"en":"live","uz":"yashamoq","ipa":"lɪv"},{"en":"work","uz":"ishlamoq","ipa":"wɜːk"},{"en":"study","uz":"o'qimoq, o'rganmoq","ipa":"ˈstʌd.i"},{"en":"like","uz":"yoqtirmoq","ipa":"laɪk"},{"en":"play","uz":"o'ynamoq","ipa":"pleɪ"},{"en":"speak","uz":"gapirmoq","ipa":"spiːk"},{"en":"drink","uz":"ichmoq","ipa":"drɪŋk"},{"en":"watch","uz":"tomosha qilmoq, ko'rmoq","ipa":"wɒtʃ"},{"en":"learn","uz":"o'rganmoq, bilib olmoq","ipa":"lɜːn"},{"en":"need","uz":"kerak bo'lmoq, muhtoj bo'lmoq","ipa":"niːd"}],"summary":["Present Simple — odatlar va doimiy faktlar: I live in Tashkent.","I / you / we / they + fe'lning lug'at shakli: I work, we work, they work.","So'z tartibi: ega + fe'l + to'ldiruvchi — I learn English, \"I English learn\" emas.","Fe'l bor joyda am / are qo'shilmaydi: I work, \"I am work\" emas.","Yangi fe'llar: live, work, study, like, play, speak, drink, watch, learn, need."]},{"id":"u3-l3","slug":"present-simple-he-she-it","title":"Present Simple: he / she / it","titleUz":"Present Simple: he / she / it","goal":"Boshqa odamlar haqida gapirasiz: She works in a bank. He teaches English. he / she / it bilan fe'lga -s / -es / -ies qo'shishni, uni /s/, /z/, /ɪz/ deb to'g'ri talaffuz qilishni va has, does, goes shakllarini o'rganasiz.","words":[{"en":"go – goes","uz":"bormoq","ipa":"ɡəʊ – ɡəʊz"},{"en":"do – does","uz":"qilmoq","ipa":"duː – dʌz"},{"en":"have – has","uz":"ega bo'lmoq, bor bo'lmoq","ipa":"hæv – hæz"},{"en":"teach – teaches","uz":"o'qitmoq, dars bermoq","ipa":"tiːtʃ – ˈtiː.tʃɪz"},{"en":"wash – washes","uz":"yuvmoq","ipa":"wɒʃ – ˈwɒʃ.ɪz"},{"en":"finish – finishes","uz":"tugatmoq, tugamoq","ipa":"ˈfɪn.ɪʃ – ˈfɪn.ɪ.ʃɪz"},{"en":"fly – flies","uz":"uchmoq","ipa":"flaɪ – flaɪz"},{"en":"try – tries","uz":"harakat qilmoq, urinib ko'rmoq","ipa":"traɪ – traɪz"},{"en":"fix – fixes","uz":"tuzatmoq, ta'mirlamoq","ipa":"fɪks – ˈfɪk.sɪz"},{"en":"catch – catches","uz":"tutmoq, ushlamoq","ipa":"kætʃ – ˈkætʃ.ɪz"}],"summary":["he / she / it (va bitta odam/narsa) bilan fe'l + -s: She works. Ali lives in Fergana.","Imlo: -s, -sh, -ch, -x, -o → -es (washes, teaches, fixes, goes); undosh + y → -ies (studies, flies); unli + y → -s (plays).","Talaffuz: /s/ works · /z/ lives, plays · /ɪz/ watches, washes.","Maxsus: have → has, do → does (\"daz\"), go → goes.","Ko'plikda -s yo'q: My friends live here."]},{"id":"u3-l13","slug":"s-es-spelling","title":"-s / -es: spelling","titleUz":"he / she / it: -s, -es, -ies imlosi","goal":"he / she / it bilan fe'lni imlo xatosiz yozasiz va to'g'ri o'qiysiz: works, watches, studies, goes, has. Oxiri qaysi harfda tugasa, qaysi qo'shimcha (-s, -es, -ies) kerakligini darrov ajratasiz.","words":[{"en":"brush","uz":"tozalamoq, cho'tkalamoq","ipa":"brʌʃ"},{"en":"carry","uz":"ko'tarib yurmoq, olib yurmoq","ipa":"ˈkær.i"},{"en":"worry","uz":"xavotir olmoq","ipa":"ˈwʌr.i"},{"en":"enjoy","uz":"zavqlanmoq, yoqtirmoq","ipa":"ɪnˈdʒɔɪ"},{"en":"relax","uz":"dam olmoq","ipa":"rɪˈlæks"},{"en":"miss","uz":"sog'inmoq; o'tkazib yubormoq","ipa":"mɪs"}],"summary":["Ko'pchilik fe'llar: + s (works, lives). -s, -sh, -ch, -x, -o: + es (watches, brushes, goes).","Undosh + y → -ies (studies, carries). Unli + y → -s (plays, enjoys).","O'qilishi: /s/ works · /z/ carries, enjoys · /ɪz/ watches, relaxes.","Maxsus: have → has, do → does, go → goes."]},{"id":"u3-l4","slug":"dont-doesnt","title":"don't / doesn't","titleUz":"Inkor: don't / doesn't","goal":"Present Simple'da inkor gap tuzasiz: I don't drink coffee. She doesn't eat meat. doesn't dan keyin fe'l -s siz kelishini mustahkamlaysiz va ovqat-ichimliklar haqida gapira olasiz.","words":[{"en":"tea","uz":"choy","ipa":"tiː"},{"en":"coffee","uz":"qahva","ipa":"ˈkɒf.i"},{"en":"juice","uz":"sharbat","ipa":"dʒuːs"},{"en":"bread","uz":"non","ipa":"bred"},{"en":"rice","uz":"guruch","ipa":"raɪs"},{"en":"meat","uz":"go'sht","ipa":"miːt"},{"en":"soup","uz":"sho'rva","ipa":"suːp"},{"en":"sugar","uz":"shakar","ipa":"ˈʃʊɡ.ə"},{"en":"vegetables","uz":"sabzavotlar","ipa":"ˈvedʒ.tə.bəlz"},{"en":"fruit","uz":"meva","ipa":"fruːt"}],"summary":["Inkor: I / you / we / they + don't + fe'l; he / she / it + doesn't + fe'l.","doesn't dan keyin fe'l -s siz: She doesn't like coffee, He doesn't have a car.","Fe'l bor joyda \"I not…\" yoki \"I'm not like…\" emas — I don't like…. Holat uchun esa I'm not hungry.","tea, coffee, bread, rice, meat, sugar, soup, juice, fruit — a/an siz: I eat bread."]},{"id":"u3-l5","slug":"do-does-questions","title":"Do / Does questions","titleUz":"Savollar: Do / Does","goal":"Do / Does bilan savol berasiz (Do you like music? Does she play chess?) va qisqa javob qaytarasiz (Yes, I do. / No, she doesn't.). Sevimli mashg'ulotlar haqida suhbatlasha olasiz.","words":[{"en":"hobby","uz":"sevimli mashg'ulot, xobbi","ipa":"ˈhɒb.i"},{"en":"sport","uz":"sport","ipa":"spɔːt"},{"en":"football","uz":"futbol","ipa":"ˈfʊt.bɔːl"},{"en":"chess","uz":"shaxmat","ipa":"tʃes"},{"en":"music","uz":"musiqa","ipa":"ˈmjuː.zɪk"},{"en":"guitar","uz":"gitara","ipa":"ɡɪˈtɑː"},{"en":"game","uz":"o'yin","ipa":"ɡeɪm"},{"en":"film","uz":"film, kino","ipa":"fɪlm"},{"en":"cinema","uz":"kinoteatr","ipa":"ˈsɪn.ə.mə"},{"en":"party","uz":"bazm, ziyofat","ipa":"ˈpɑː.ti"}],"summary":["Savol: Do + I / you / we / they + fe'l? · Does + he / she / it + fe'l?","Does dan keyin fe'l -s siz: Does she like music?","Qisqa javob: Yes, I do. / No, I don't. · Yes, she does. / No, she doesn't. — \"Yes, I like\" emas.","Fe'l bilan Are you…? emas, Do you…?: Do you play chess?","Iboralar: play football / chess / the guitar · listen to music · go to the cinema · do sport."]},{"id":"u3-l14","slug":"wh-questions-with-do-does","title":"Wh- questions with do / does","titleUz":"Wh-savollar: What do you…? Where does she…?","goal":"What, Where, When, Why, How so'zlari bilan savol berasiz: Where does she live? When do you have lunch? Why do they study English? va ularga qisqa javob qaytarasiz.","words":[{"en":"where","uz":"qayerda, qayerga","ipa":"weə"},{"en":"when","uz":"qachon","ipa":"wen"},{"en":"why","uz":"nega, nima uchun","ipa":"waɪ"},{"en":"because","uz":"chunki","ipa":"bɪˈkɒz"},{"en":"how","uz":"qanday, qanaqa usulda","ipa":"haʊ"},{"en":"by bus","uz":"avtobusda","ipa":"baɪ bʌs"}],"summary":["Wh-savol: so'roq so'zi + do/does + ega + fe'l: Where does she live?","do — I/you/we/they bilan, does — he/she/it bilan; does dan keyin fe'lda -s yo'q.","What — nima, Where — qayerda, When — qachon, Why — nega (Because…), How — qanday (by bus)."]},{"id":"u3-l9","slug":"at-the-cafe-present-simple-in-real-life","title":"At the café: Present Simple in real life","titleUz":"Kafeda: Present Simple hayotda","goal":"Kafeda buyurtma berasiz va savollarga javob qaytarasiz: Do you want sugar? — Yes, please. / No, thanks. Present Simple'ni (do / does / don't / doesn't) real vaziyatda ishlatasiz.","words":[{"en":"order","uz":"buyurtma bermoq","ipa":"ˈɔː.dər"},{"en":"menu","uz":"menyu","ipa":"ˈmen.juː"},{"en":"bill","uz":"hisob (to'lov cheki)","ipa":"bɪl"},{"en":"pay","uz":"to'lamoq","ipa":"peɪ"},{"en":"cup","uz":"piyola, finjon","ipa":"kʌp"}],"summary":["Kafeda savol Do you want…?, javob Yes, please. / No, thanks.","He / she / it bilan: Does… ? va doesn't, fe'l oddiy shaklda: Does it have sugar?","Yangi so'zlar: order, menu, bill, pay — gaplarda ishlating."]},{"id":"u3-l16","slug":"real-life-ordering-at-a-cafe","title":"Real life: ordering at a café","titleUz":"Real hayot: kafeda buyurtma berish","goal":"Kafeda muloyim buyurtma berasiz: I'd like a tea, please. Narxni so'raysiz, «Yana nimadir?» ga javob berasiz va rahmat aytasiz.","words":[],"summary":["What would you like? — «Nima olasiz?»; javob: I'd like a tea, please.","I like coffee — umuman yoqtirishingiz; buyurtma uchun I'd like deymiz.","a / an sanaladigan narsa oldida, some sanalmaydigan narsa oldida: some sugar.","How much is it? — narxni so'rash; Anything else? → No, thank you."]},{"id":"u3-l10","slug":"university-and-work-my-week","title":"University and work: my week","titleUz":"Universitet va ish: mening haftam","goal":"Universitet yoki ish kuningiz haqida Present Simple bilan gapirasiz: I study at university. My lesson starts at nine. Do you like your job?","words":[{"en":"lecture","uz":"ma'ruza","ipa":"ˈlek.tʃər"},{"en":"colleague","uz":"hamkasb","ipa":"ˈkɒl.iːɡ"},{"en":"meeting","uz":"uchrashuv, yig'ilish","ipa":"ˈmiː.tɪŋ"},{"en":"office","uz":"ofis","ipa":"ˈɒf.ɪs"},{"en":"start","uz":"boshlanmoq, boshlamoq","ipa":"stɑːt"},{"en":"finish","uz":"tugamoq, tugatmoq","ipa":"ˈfɪn.ɪʃ"}],"summary":["Doimiy ish / o'qish haqida Present Simple: I study, she works.","Savol: When / Where + do / does + ega + fe'l: When does it start?","Yangi so'zlar: lecture, colleague, meeting, finish."]},{"id":"u3-l11","slug":"present-simple-final-review","title":"Present Simple: final review","titleUz":"Present Simple: yakuniy takror","goal":"Present Simple mavzusini yakunlaysiz: darak, -s, inkor va savol — hammasi bitta joyda. Kafe va ish vaziyatlarida erkin foydalanasiz.","words":[{"en":"near","uz":"yaqin, yaqinida","ipa":"nɪə"},{"en":"busy","uz":"band","ipa":"ˈbɪz.i"},{"en":"early","uz":"erta","ipa":"ˈɜː.li"},{"en":"quiet","uz":"tinch, jim","ipa":"ˈkwaɪ.ət"},{"en":"tired","uz":"charchagan","ipa":"ˈtaɪəd"}],"summary":["Darak: -s faqat he / she / it bilan. Inkor: don't / doesn't. Savol: Do / Does.","Does / doesn't dan keyin fe'l har doim oddiy shaklda.","Kafe va ish vaziyatlarida shu qoliplar ishlaydi: Do you want…? / When does it start?"]},{"id":"u3-l6","slug":"time-daily-routine","title":"Time & daily routine","titleUz":"Vaqt va kun tartibi","goal":"Soatni inglizcha aytasiz (seven o'clock, half past seven, quarter to eight), vaqtni so'raysiz va kun tartibingizni Present Simple bilan tasvirlaysiz: I get up at seven. She has lunch at one.","words":[{"en":"wake up","uz":"uyg'onmoq","ipa":"weɪk ʌp"},{"en":"get up","uz":"o'rnidan turmoq","ipa":"ɡet ʌp"},{"en":"have breakfast","uz":"nonushta qilmoq","ipa":"hæv ˈbrek.fəst"},{"en":"have lunch","uz":"tushlik qilmoq","ipa":"hæv lʌntʃ"},{"en":"have dinner","uz":"kechki ovqat qilmoq","ipa":"hæv ˈdɪn.ə"},{"en":"go to bed","uz":"uxlashga yotmoq","ipa":"ɡəʊ tə bed"},{"en":"o'clock","uz":"soat (butun soat)","ipa":"əˈklɒk"},{"en":"half past","uz":"… yarim (30 daqiqa o'tdi)","ipa":"hɑːf pɑːst"},{"en":"quarter","uz":"chorak (15 daqiqa)","ipa":"ˈkwɔː.tə"},{"en":"minute","uz":"daqiqa","ipa":"ˈmɪn.ɪt"}],"summary":["What time is it? — It's seven o'clock. (o'clock faqat butun soatda)","past — o'tdi (1–30 daqiqa), to — qoldi (31–59): quarter past seven = 7:15, half past seven = 7:30, quarter to eight = 7:45.","Soat oldidan at: I get up at seven. a.m. — tushgacha, p.m. — tushdan keyin.","have breakfast / lunch / dinner (a siz), go to bed (the siz). he/she bilan: gets up, has lunch, goes to bed."]},{"id":"u3-l17","slug":"real-life-at-the-bus-station","title":"Real life: at the bus station","titleUz":"Real hayot: avtobus bekatida","goal":"Avtobus bekatida savol berasiz (Does this bus go...? What time does it leave?), vaqtni tushunasiz, narxni so'raysiz va chipta olasiz.","words":[],"summary":["Does this bus go to the airport? — Does dan keyin fe'l oddiy shaklda: go (goes emas).","What time does the bus leave? — savolda does + leave; -s faqat darak gapda: It leaves at nine.","Vaqt: at half past nine, at nine o'clock, at quarter past ten.","How much is the ticket? — It's twelve dollars.; One ticket to the airport, please."]},{"id":"u3-l7","slug":"days-months-in-on-at","title":"Days, months: in / on / at","titleUz":"Kunlar, oylar: in / on / at","goal":"Hafta kunlari va oylarni to'g'ri aytasiz va katta harf bilan yozasiz. Vaqt predloglarini ajratasiz: at seven, on Monday, in July — o'zbekchadagi bitta \"-da\" o'rniga uchta so'z.","words":[{"en":"Monday","uz":"dushanba","ipa":"ˈmʌn.deɪ"},{"en":"Wednesday","uz":"chorshanba","ipa":"ˈwenz.deɪ"},{"en":"Friday","uz":"juma","ipa":"ˈfraɪ.deɪ"},{"en":"Sunday","uz":"yakshanba","ipa":"ˈsʌn.deɪ"},{"en":"weekend","uz":"dam olish kunlari (shanba–yakshanba)","ipa":"ˌwiːkˈend"},{"en":"week","uz":"hafta","ipa":"wiːk"},{"en":"month","uz":"oy (kalendar oyi)","ipa":"mʌnθ"},{"en":"year","uz":"yil","ipa":"jɪə"},{"en":"January","uz":"yanvar","ipa":"ˈdʒæn.ju.ə.ri"},{"en":"July","uz":"iyul","ipa":"dʒuˈlaɪ"}],"summary":["Hafta kunlari va oylar — doim katta harf bilan: Monday, July.","Talaffuz tuzoqlari: Wednesday \"WENZ-dey\", Tuesday / Thursday, July urg'u oxirida, month oxirida th.","in — oy, yil, kun qismi (in July, in the morning); on — kun (on Monday); at — soat (at seven, at night, at the weekend).","every, today, this oldidan predlog yo'q: every Friday, \"on every Friday\" emas."]},{"id":"u3-l18","slug":"real-life-arranging-to-meet","title":"Real life: arranging to meet","titleUz":"Real hayot: uchrashuv vaqtini kelishish","goal":"Do'stingiz bilan uchrashuv kelishasiz: kun va vaqtni to'g'ri in / on / at bilan aytasiz, rozi bo'lasiz yoki muloyim rad etasiz.","words":[],"summary":["Let's meet on Saturday. — «Shanba kuni uchrashaylik.»","on + kun (on Saturday), at + soat (at six), in + kun qismi (in the evening).","Do you work on Saturday? — No, I don't. — qisqa javob do / don't bilan.","Rad etish: Sorry, I work on Sunday.; xayrlashish: See you on Saturday at six!"]},{"id":"u3-l8","slug":"always-usually-never","title":"always, usually, never…","titleUz":"Qanchalik tez-tez: always, usually, never…","goal":"Ishni qanchalik tez-tez qilishingizni aytasiz: I always get up at seven. She is never late. Chastota ravishlarining gapdagi o'rnini bilasiz, How often…? deb so'raysiz va once a week, every day bilan javob berasiz.","words":[{"en":"always","uz":"doim, har doim","ipa":"ˈɔːl.weɪz"},{"en":"usually","uz":"odatda","ipa":"ˈjuː.ʒu.ə.li"},{"en":"often","uz":"ko'pincha, tez-tez","ipa":"ˈɒf.ən"},{"en":"sometimes","uz":"ba'zan","ipa":"ˈsʌm.taɪmz"},{"en":"rarely","uz":"kamdan-kam","ipa":"ˈreə.li"},{"en":"never","uz":"hech qachon","ipa":"ˈnev.ə"},{"en":"every day","uz":"har kuni","ipa":"ˈev.ri deɪ"},{"en":"once","uz":"bir marta","ipa":"wʌns"},{"en":"twice","uz":"ikki marta","ipa":"twaɪs"},{"en":"how often","uz":"qanchalik tez-tez","ipa":"haʊ ˈɒf.ən"}],"summary":["Chastota: always (100%) → usually → often → sometimes → rarely → never (0%).","Oddiy fe'l bilan ravish fe'ldan oldin: I always get up at seven.","to be bilan ravish am / is / are dan keyin: She is never late.","never — o'zi inkor: I never eat meat, \"I don't never\" emas.","How often…? — every day, once a week, twice a month, three times a year (gap oxirida)."]},{"id":"u3-l15","slug":"my-daily-routine-listening-and-writing","title":"My daily routine: listening and writing","titleUz":"Mening kunim: tinglash va yozish","goal":"Kun tartibi haqidagi suhbatni tinglab vaqt va tafsilotlarni tushunasiz, so'ng o'zingizning kuningiz haqida qisqa abzats yozasiz: I usually get up at half past six. I go to work by bus.","words":[{"en":"routine","uz":"kun tartibi, odat","ipa":"ruːˈtiːn"},{"en":"have a shower","uz":"dush qabul qilmoq","ipa":"hæv ə ˈʃaʊ.ə"},{"en":"leave home","uz":"uydan chiqmoq","ipa":"liːv həʊm"},{"en":"get home","uz":"uyga qaytmoq","ipa":"ɡet həʊm"},{"en":"before","uz":"…dan oldin","ipa":"bɪˈfɔː"},{"en":"after","uz":"…dan keyin","ipa":"ˈɑːf.tə"}],"summary":["Tinglaganda kalit so'zlarni ushlang: vaqt, ish, tez-tez ravishi, kim (I / he / she).","Abzats ketma-ketlikda yoziladi, har bir ishda vaqt: I get up at seven. I go to work by bus.","Foydali so'zlar: before, after, then; ravishlar fe'ldan oldin: I always have lunch.","Yozgandan keyin tekshiring: at, he/she + -s, doesn't + s'siz fe'l."]},{"id":"u3-l19","slug":"real-life-my-day-a-chat-with-a-friend","title":"Real life: my day, a chat with a friend","titleUz":"Real hayot: do'st bilan kun tartibi","goal":"Do'stingiz bilan kun tartibingiz haqida gaplashasiz: nechada turasiz, nima qilasiz, ishga qanday borasiz. always / usually / never ni to'g'ri joyga qo'yasiz va o'zingiz ham savol berasiz.","words":[],"summary":["What time do you get up? → I get up at seven. (soat oldidan at).","Do you…? savoliga: Yes, I do. / No, I don't. Uchinchi shaxs: Does she…? → Yes, she does.","Takrorlanish so'zi fe'ldan oldin turadi: I never drink coffee. (I drink never coffee emas).","he / she bilan fe'lga -s: She gets up at six. (She get up emas).","Savol berish: What time do you finish work? (do + fe'lning oddiy shakli)."]},{"id":"u3-l12","slug":"everyday-life-final-review","title":"Everyday life: final review","titleUz":"Kundalik hayot: yakuniy takror","goal":"Butun bo'limni takrorlaysiz: sonlar, yosh, narx, Present Simple, vaqt, in / on / at, always / never va How often. Haftangiz haqida bemalol gapirasiz.","words":[{"en":"holiday","uz":"ta'til, dam olish","ipa":"ˈhɒl.ə.deɪ"},{"en":"ticket","uz":"chipta","ipa":"ˈtɪk.ɪt"},{"en":"lazy","uz":"dangasa","ipa":"ˈleɪ.zi"},{"en":"late","uz":"kech, kechikkan","ipa":"leɪt"},{"en":"expensive","uz":"qimmat","ipa":"ɪkˈspen.sɪv"},{"en":"salary","uz":"maosh","ipa":"ˈsæl.ər.i"}],"summary":["Yosh va narx: I'm thirty. How much is it? Sonlar 20–100 gacha.","Present Simple: -s (he/she/it), don't / doesn't, Do / Does.","on — kun, in — oy, at — soat.","always, usually, often, never — oddiy fe'ldan oldin, to be dan keyin. How often — chastota haqida savol."]}]},{"id":"u4","n":4,"title":"Describing and Asking","titleUz":"Tasvirlash va so'rash: there is, can, have got","description":"Wh-savollar, there is / are, joy predloglari, much / many, can, buyruq, have got, Present Continuous.","canDo":["There is / There are bilan joyni tasvirlayman","Predloglar (in, on, under…) bilan narsa qayerdaligini aytaman","can / can't bilan qobiliyat va iltimosni bildiraman","Hozir nima qilayotganimni ayta olaman"],"lessons":[{"id":"u4-l1","slug":"wh-questions","title":"Wh- questions","titleUz":"Wh-savollar: what, where, who…","goal":"What, where, when, who, why, how kabi so'roq so'zlari bilan to'g'ri savol tuzasiz (so'roq so'zi + do/does/be + ega) va bunday savollarga qisqa javob bera olasiz.","words":[{"en":"what","uz":"nima","ipa":"wɒt"},{"en":"where","uz":"qayerda, qayerga","ipa":"weə"},{"en":"when","uz":"qachon","ipa":"wen"},{"en":"who","uz":"kim","ipa":"huː"},{"en":"why","uz":"nima uchun, nega","ipa":"waɪ"},{"en":"how","uz":"qanday","ipa":"haʊ"},{"en":"which","uz":"qaysi","ipa":"wɪtʃ"},{"en":"whose","uz":"kimning","ipa":"huːz"},{"en":"how many","uz":"nechta","ipa":"haʊ ˈmen.i"},{"en":"how old","uz":"necha yoshda","ipa":"haʊ ˈəʊld"}],"summary":["So'roq so'zi har doim gap boshida: Where do you live?","Fe'l bilan: so'roq so'zi + do/does + ega + fe'l (does bo'lsa -s yo'q): What does she like?","To be bilan: so'roq so'zi + am/is/are + ega: How old are you?","Who ega bo'lsa do kerak emas: Who lives here?","who / whose \"hu:\" deb o'qiladi; wh-savollarda ovoz oxirida pasayadi ↘."]},{"id":"u4-l2","slug":"there-is-there-are","title":"There is / there are","titleUz":"There is / there are, some / any","goal":"There is / there are yordamida biror joyda nima borligini aytasiz, Is there…? / Are there…? bilan so'raysiz va some / any ni to'g'ri ishlatib, uyingizni tasvirlab bera olasiz.","words":[{"en":"kitchen","uz":"oshxona","ipa":"ˈkɪtʃ.ɪn"},{"en":"bedroom","uz":"yotoqxona","ipa":"ˈbed.ruːm"},{"en":"bathroom","uz":"hammom, vannaxona","ipa":"ˈbɑːθ.ruːm"},{"en":"living room","uz":"mehmonxona (yashash xonasi)","ipa":"ˈlɪv.ɪŋ ruːm"},{"en":"sofa","uz":"divan","ipa":"ˈsəʊ.fə"},{"en":"bed","uz":"karavot","ipa":"bed"},{"en":"lamp","uz":"lampa, chiroq","ipa":"læmp"},{"en":"fridge","uz":"muzlatkich","ipa":"frɪdʒ"},{"en":"shelf","uz":"javon (ko'pl. shelves)","ipa":"ʃelf"},{"en":"carpet","uz":"gilam","ipa":"ˈkɑː.pɪt"}],"summary":["\"…da … bor\" = There is + birlik / There are + ko'plik + joy: There is a sofa in the room.","Inkor: There isn't a… / There aren't any…","Savol: Is there a…? / Are there any…? — Javob: Yes, there is. / No, there aren't.","some — ijobiy gapda, any — inkor va savolda.","Yangi so'zlar: kitchen, bedroom, bathroom, living room, sofa, bed, lamp, fridge, shelf, carpet."]},{"id":"u4-l3","slug":"prepositions-of-place","title":"Prepositions of place","titleUz":"Joy predloglari: in, on, under…","goal":"Narsalar va odamlar qayerda turganini 10 ta joy predlogi bilan (in, on, under, next to, between…) aniq aytasiz va Where is…? / Where are…? savollariga javob bera olasiz.","words":[{"en":"in","uz":"-da, ichida","ipa":"ɪn"},{"en":"on","uz":"ustida","ipa":"ɒn"},{"en":"under","uz":"ostida, tagida","ipa":"ˈʌn.də"},{"en":"next to","uz":"yonida","ipa":"ˈnekst tə"},{"en":"between","uz":"orasida","ipa":"bɪˈtwiːn"},{"en":"behind","uz":"orqasida","ipa":"bɪˈhaɪnd"},{"en":"in front of","uz":"oldida","ipa":"ɪn ˈfrʌnt əv"},{"en":"near","uz":"yaqinida","ipa":"nɪə"},{"en":"opposite","uz":"qarshisida, ro'parasida","ipa":"ˈɒp.ə.zɪt"},{"en":"above","uz":"tepasida, yuqorisida","ipa":"əˈbʌv"}],"summary":["Ingliz tilida predlog otdan oldin: karavot ostida → under the bed.","in (ichida) · on (ustida, tegib) · under (ostida) · above (tepasida, tegmay).","next to (yonida) · near (yaqinida) · between A and B (orasida).","behind (orqasida) · in front of (oldida, the siz) · opposite (ro'parasida, of siz).","Joy haqida gapda to be shart: Where are my keys? — They're in the bag."]},{"id":"u4-l9","slug":"my-room-and-my-town","title":"My room and my town","titleUz":"Xonam va shahrim: there is / there are","goal":"O'z xonangiz va shahringizni tasvirlaysiz: There is a bed next to the window. There are two parks in my town. There is / there are, some / any va joy predloglarini birga ishlatasiz.","words":[{"en":"garden","uz":"bog'","ipa":"ˈɡɑː.dən"},{"en":"street","uz":"ko'cha","ipa":"striːt"},{"en":"flat","uz":"kvartira","ipa":"flæt"},{"en":"wall","uz":"devor","ipa":"wɔːl"}],"summary":["Bitta narsa: There is; bir nechta: There are. Savol: Is there…? / Are there…?","some — darak gapda, any — savol va inkorda.","Joyni predloglar bilan ayting: in, on, next to, near, opposite.","Yangi so'zlar: garden, street, flat, wall."]},{"id":"u4-l4","slug":"countable-uncountable","title":"Countable & uncountable","titleUz":"Sanaladigan / sanalmaydigan, much / many","goal":"Sanaladigan va sanalmaydigan otlarni ajratasiz, much / many / a lot of va How much / How many ni to'g'ri ishlatasiz hamda do'konda a bottle of, a kilo of, a piece of, a packet of bilan miqdorni aytasiz.","words":[{"en":"banana","uz":"banan","ipa":"bəˈnɑː.nə"},{"en":"cheese","uz":"pishloq","ipa":"tʃiːz"},{"en":"butter","uz":"sariyog'","ipa":"ˈbʌt.ə"},{"en":"salt","uz":"tuz","ipa":"sɔːlt"},{"en":"oil","uz":"yog' (o'simlik yog'i)","ipa":"ɔɪl"},{"en":"flour","uz":"un","ipa":"ˈflaʊ.ə"},{"en":"a bottle of","uz":"bir shisha …","ipa":"ə ˈbɒt.əl əv"},{"en":"a kilo of","uz":"bir kilo …","ipa":"ə ˈkiː.ləʊ əv"},{"en":"a piece of","uz":"bir bo'lak …","ipa":"ə ˈpiːs əv"},{"en":"a packet of","uz":"bir paket …","ipa":"ə ˈpæk.ɪt əv"}],"summary":["Sanaladigan: a banana, two bananas. Sanalmaydigan (water, rice, salt, cheese, bread): a/an yo'q, -s yo'q, fe'l birlikda.","many + ko'plik, much + sanalmaydigan (asosan inkor/savolda); ijobiy gapda — a lot of.","How many bananas? · How much flour? · narx: How much is it?","Idishlar: a bottle of oil, a kilo of rice, a piece of cheese, a packet of salt; ko'plikda -s idishga: two bottles of water."]},{"id":"u4-l10","slug":"at-the-shop-much-many-can-i","title":"At the shop: much, many, can I…?","titleUz":"Do'konda: much, many, can","goal":"Do'konda kerakli narsani so'raysiz va to'laysiz: Can I have some bread, please? How much is it? Much / many, how much / how many va Can I…? ni ishlatasiz.","words":[{"en":"cash","uz":"naqd pul","ipa":"kæʃ"},{"en":"card","uz":"karta","ipa":"kɑːd"},{"en":"change","uz":"qaytim","ipa":"tʃeɪndʒ"},{"en":"fresh","uz":"yangi, toza","ipa":"freʃ"}],"summary":["How many + sanaladigan (eggs), How much + sanalmaydigan (rice). Narx: How much is it?","Iltimos: Can I have…? — Can I dan keyin tosiz fe'l.","some — darakda, any — savol va inkorda.","Yangi so'zlar: cash, card, change, fresh."]},{"id":"u4-l5","slug":"can-cant","title":"can / can't","titleUz":"can / can't: qobiliyat va iltimos","goal":"can / can't yordamida nima qila olishingizni va qila olmasligingizni aytasiz, ruxsat va iltimos so'raysiz (Can I…? Can you…?) hamda can va can't ni quloq bilan ajratasiz.","words":[{"en":"swim","uz":"suzmoq","ipa":"swɪm"},{"en":"run","uz":"yugurmoq","ipa":"rʌn"},{"en":"jump","uz":"sakramoq","ipa":"dʒʌmp"},{"en":"drive","uz":"(mashina) haydamoq","ipa":"draɪv"},{"en":"ride","uz":"(ot, velosiped) minmoq","ipa":"raɪd"},{"en":"climb","uz":"tirmashib chiqmoq","ipa":"klaɪm"},{"en":"cook","uz":"ovqat pishirmoq","ipa":"kʊk"},{"en":"dance","uz":"raqsga tushmoq","ipa":"dɑːns"},{"en":"draw","uz":"rasm chizmoq","ipa":"drɔː"},{"en":"ski","uz":"chang'ida uchmoq","ipa":"skiː"}],"summary":["can + fe'l — hamma shaxs uchun bir xil: He can swim. (-s yo'q, to yo'q).","Inkor: can't / cannot; savol: Can you…? — Yes, I can. / No, I can't.","Talaffuz: gapda qisqa \"kən\", can't — uzun \"ka:nt\".","Daraja gap oxirida: very well, well, a little, not … at all.","Ruxsat: Can I…? · Iltimos: Can you…, please?"]},{"id":"u4-l14","slug":"can-i-requests-and-permission","title":"Can I…? Requests and permission","titleUz":"Can I…? Iltimos va ruxsat so'rash","goal":"Can I…? bilan muloyim iltimos qilasiz (Can I have a glass of water?) va ruxsat so'raysiz (Can I open the window?), javobni ham tushunasiz va o'zingiz berasiz: Yes, of course. / Sorry, you can't.","words":[{"en":"borrow","uz":"vaqtincha olmoq","ipa":"ˈbɒr.əʊ"},{"en":"lend","uz":"vaqtincha bermoq","ipa":"lend"},{"en":"use","uz":"ishlatmoq, foydalanmoq","ipa":"juːz"},{"en":"close","uz":"yopmoq","ipa":"kləʊz"},{"en":"toilet","uz":"hojatxona","ipa":"ˈtɔɪ.lət"},{"en":"of course","uz":"albatta","ipa":"əv ˈkɔːs"}],"summary":["Can I + fe'l (to'siz)…? — iltimos (Can I have…?) va ruxsat (Can I open…?).","Ha: Yes, of course. / Sure. / Yes, you can. Yo'q: Sorry, you can't. + sabab.","Can I to…, Can I opens…, Do I can… — xato.","Yangi so'zlar: borrow, lend, use, close, toilet, of course."]},{"id":"u4-l20","slug":"real-life-how-much-is-it","title":"Real life: how much is it?","titleUz":"Real hayot: do'konda narx so'rash","goal":"Do'konda Can I have…, please? deb so'raysiz, Do you have any…? deb mahsulot borligini so'raysiz, How much is it? deb narxini so'raysiz va jami summani tushunasiz.","words":[],"summary":["Can I have some apples, please? — muloyim iltimos (I want apples emas).","Do you have any milk? — so'roq gapda any; javobda some: Yes, we have some milk.","How many + sanaladigan (apples), How much + sanalmaydigan (milk).","How much is it? — narxni so'rash; narxni eshitib jami summani topish.","Here you are. — «Marhamat.»"]},{"id":"u4-l6","slug":"imperatives-object-pronouns","title":"Imperatives & object pronouns","titleUz":"Buyruq gaplar va me, him, her…","goal":"Buyruq va ko'rsatma berasiz (Sit down. Don't wait. Let's go.), ularni please bilan muloyim qilasiz va me, him, her, us, them kabi kelishikdagi olmoshlarni to'g'ri ishlatasiz.","words":[{"en":"sit down","uz":"o'tirmoq","ipa":"sɪt ˈdaʊn"},{"en":"stand up","uz":"o'rnidan turmoq","ipa":"stænd ˈʌp"},{"en":"come in","uz":"kirmoq","ipa":"kʌm ˈɪn"},{"en":"give","uz":"bermoq","ipa":"ɡɪv"},{"en":"take","uz":"olmoq","ipa":"teɪk"},{"en":"help","uz":"yordam bermoq","ipa":"help"},{"en":"wait","uz":"kutmoq","ipa":"weɪt"},{"en":"look at","uz":"qaramoq","ipa":"ˈlʊk ət"},{"en":"stop","uz":"to'xtamoq, to'xtatmoq","ipa":"stɒp"},{"en":"turn on","uz":"yoqmoq","ipa":"tɜːn ˈɒn"}],"summary":["Buyruq gap = fe'lning asosiy shakli, ega yo'q: Sit down. Wait. Muloyim qilish uchun please.","Inkor: Don't + fe'l (Don't stop); sifat bilan be: Don't be late.","Taklif: Let's + fe'l — Let's go! (to yo'q).","Fe'l yoki predlogdan keyin: me, you, him, her, it, us, them — Help me. Look at them."]},{"id":"u4-l13","slug":"object-pronouns-me-you-him-her","title":"Object pronouns: me, you, him, her…","titleUz":"Olmoshning to'ldiruvchi shakli: me, him, her, us, them","goal":"Fe'ldan va predlogdan keyin me, you, him, her, it, us, them ni to'g'ri ishlatasiz: She knows him. Come with me. Send it to them. Odamlar va narsalarni qayta aytmasdan olmosh bilan almashtirasiz.","words":[{"en":"send","uz":"yubormoq","ipa":"send"},{"en":"show","uz":"ko'rsatmoq","ipa":"ʃəʊ"},{"en":"tell","uz":"aytmoq, aytib bermoq","ipa":"tel"},{"en":"invite","uz":"taklif qilmoq","ipa":"ɪnˈvaɪt"},{"en":"ask","uz":"so'ramoq","ipa":"ɑːsk"},{"en":"thank","uz":"rahmat aytmoq","ipa":"θæŋk"}],"summary":["Fe'ldan oldin — ega olmosh (I, he, she, we, they); fe'ldan va predlogdan keyin — me, him, her, us, them.","you va it ikkala o'rinda ham o'zgarmaydi.","Predlogdan keyin ham doim to'ldiruvchi shakl: with me, for him, about them.","send / show / tell + kimga + nimani: Send me a message."]},{"id":"u4-l19","slug":"real-life-asking-the-way","title":"Real life: asking the way","titleUz":"Real hayot: yo'l so'rash","goal":"Ko'chada yo'lni so'raysiz, javobni tushunasiz (Go straight, Turn left, on the right), «Bu yerda … bormi?» deb so'raysiz va minnatdorchilik bildirasiz.","words":[],"summary":["Excuse me, where is the bank? — yo'l so'rash (Where the bank is? emas).","It's next to the shop. / It's opposite the park. — joyni aytish (It's = It is).","Go straight. Turn left. Turn right. on the left / on the right — yo'l ko'rsatish.","Is there a pharmacy near here? — Is there a…? (Is there pharmacy emas, a kerak).","Thank you very much. — katta rahmat."]},{"id":"u4-l7","slug":"have-got-family","title":"have got & family","titleUz":"have got va oila","goal":"have got / has got bilan nimangiz va kimingiz borligini aytasiz, inkor va savol tuzasiz hamda oila a'zolarini inglizcha nomlab, oilangiz haqida gapira olasiz.","words":[{"en":"mother","uz":"ona","ipa":"ˈmʌð.ə"},{"en":"father","uz":"ota","ipa":"ˈfɑː.ðə"},{"en":"parents","uz":"ota-ona","ipa":"ˈpeə.rənts"},{"en":"brother","uz":"aka, uka","ipa":"ˈbrʌð.ə"},{"en":"sister","uz":"opa, singil","ipa":"ˈsɪs.tə"},{"en":"son","uz":"o'g'il","ipa":"sʌn"},{"en":"daughter","uz":"qiz (farzand)","ipa":"ˈdɔː.tə"},{"en":"grandmother","uz":"buvi","ipa":"ˈɡræn.mʌð.ə"},{"en":"grandfather","uz":"bobo","ipa":"ˈɡræn.fɑː.ðə"},{"en":"uncle","uz":"amaki, tog'a","ipa":"ˈʌŋ.kəl"}],"summary":["Egalik: I/you/we/they have got ('ve got), he/she/it has got ('s got).","Inkor: haven't got / hasn't got (ko'plikda + any); do kerak emas.","Savol: Have you got…? Has she got…? — Yes, I have. / No, she hasn't. (javobda got yo'q).","Oila: mother, father, parents, brother (aka/uka), sister (opa/singil), son, daughter, grandmother, grandfather, uncle.","th (mother, brother) — ovozli ð; daughter da gh o'qilmaydi."]},{"id":"u4-l21","slug":"real-life-checking-in-at-a-hotel","title":"Real life: checking in at a hotel","titleUz":"Real hayot: mehmonxonada ro'yxatdan o'tish","goal":"Mehmonxonada ro'yxatdan o'tasiz: bronni aytasiz, ismingizni harflab berasiz, «Wi-Fi bormi?» deb so'raysiz va kalit so'raysiz (Can I have...?).","words":[],"summary":["I have a reservation. — «Menda bron bor.» (a tushib qolmasin).","My name is Ali Karimov. — ism va familiyani aytish; harflab berish uchun spell.","Is there Wi-Fi in the room? → Yes, there is. / No, there isn't.","Can I have the key, please? — nimadir so'rashning xushmuomala yo'li."]},{"id":"u4-l8","slug":"present-continuous","title":"Present Continuous","titleUz":"Present Continuous: hozir nima qilyapman","goal":"am / is / are + -ing yordamida hozir, ayni paytda bo'layotgan ishlarni aytasiz, -ing qo'shishning imlo qoidalarini bilasiz va What are you doing? kabi savol hamda inkor gaplar tuza olasiz.","words":[{"en":"walk","uz":"piyoda yurmoq","ipa":"wɔːk"},{"en":"talk","uz":"gaplashmoq","ipa":"tɔːk"},{"en":"sleep","uz":"uxlamoq","ipa":"sliːp"},{"en":"wear","uz":"kiymoq, kiyib yurmoq","ipa":"weə"},{"en":"rain","uz":"yomg'ir yog'moq","ipa":"reɪn"},{"en":"make","uz":"qilmoq, tayyorlamoq","ipa":"meɪk"},{"en":"sit","uz":"o'tirmoq","ipa":"sɪt"},{"en":"carry","uz":"ko'tarib bormoq","ipa":"ˈkær.i"},{"en":"laugh","uz":"kulmoq","ipa":"lɑːf"},{"en":"write","uz":"yozmoq","ipa":"raɪt"}],"summary":["am / is / are + fe'l-ing — hozir bo'layotgan ish: I'm walking. She's sleeping. (ikkala qism ham shart!).","Imlo: make → making (e tushadi), sit → sitting (undosh ikkilanadi), carry → carrying.","Inkor: isn't / aren't / 'm not + -ing; savol: Are you…ing? — What are you doing? (do yo'q).","Signal so'zlar: now, at the moment, Look!, Listen!; odat uchun esa Present Simple.","-ing oxiri — burun tovushi ŋ, alohida g aytilmaydi."]},{"id":"u4-l17","slug":"ing-spelling","title":"-ing: spelling","titleUz":"-ing qo'shish imlosi: run → running","goal":"Fe'lga -ing qo'shganda imloni xatosiz yozasiz: work → working, make → making, run → running, lie → lying.","words":[{"en":"lie","uz":"yotmoq","ipa":"laɪ"},{"en":"eat","uz":"yemoq","ipa":"iːt"},{"en":"wash","uz":"yuvmoq","ipa":"wɒʃ"},{"en":"paint","uz":"bo'yamoq, rasm chizmoq","ipa":"peɪnt"},{"en":"chat","uz":"suhbatlashmoq, chat qilmoq","ipa":"tʃæt"},{"en":"plan","uz":"rejalashtirmoq","ipa":"plæn"}],"summary":["Odatda: work → working, eat → eating, wash → washing.","-e tushadi: make → making, write → writing, dance → dancing.","Qisqa unli + bitta undosh: undosh ikkilanadi: run → running, sit → sitting, chat → chatting.","lie → lying; -y o'zgarmaydi: play → playing."]},{"id":"u4-l15","slug":"present-continuous-negatives","title":"Present Continuous: negatives","titleUz":"Present Continuous: inkor gaplar","goal":"Hozir bo'lmayotgan ishni aytasiz: I'm not working. He isn't sleeping. They aren't playing. To'g'ri qisqartmalarni tanlaysiz va don't/doesn't bilan chalkashtirmaysiz.","words":[{"en":"listen to","uz":"tinglamoq","ipa":"ˈlɪs.ən tə"},{"en":"shout","uz":"baqirmoq","ipa":"ʃaʊt"},{"en":"cry","uz":"yig‘lamoq","ipa":"kraɪ"},{"en":"bark","uz":"akillamoq","ipa":"bɑːk"},{"en":"snow","uz":"qor yog‘moq","ipa":"snəʊ"},{"en":"stand","uz":"turmoq","ipa":"stænd"}],"summary":["Inkor: am/is/are + not + fe'l-ing: I'm not working. He isn't sleeping. They aren't playing.","I bilan faqat I'm not; isn't = 's not, aren't = 're not.","Hozir uchun isn't/aren't + -ing, odat uchun don't/doesn't + fe'l.","don't/doesn't bilan -ing, va besiz inkor — xato."]},{"id":"u4-l16","slug":"present-continuous-questions","title":"Present Continuous: questions","titleUz":"Present Continuous: savollar va qisqa javoblar","goal":"Hozir bo'layotgan ish haqida savol berasiz va qisqa javob qaytarasiz: Are you working? — Yes, I am. Is she sleeping? — No, she isn't. What are you doing?","words":[{"en":"free","uz":"bo'sh, band emas","ipa":"friː"},{"en":"bored","uz":"zerikkan","ipa":"bɔːd"},{"en":"outside","uz":"tashqarida","ipa":"ˌaʊtˈsaɪd"},{"en":"inside","uz":"ichkarida","ipa":"ˌɪnˈsaɪd"},{"en":"lunch","uz":"tushlik","ipa":"lʌntʃ"},{"en":"homework","uz":"uy vazifasi","ipa":"ˈhəʊm.wɜːk"}],"summary":["Savol: Am / Is / Are + ega + -ing? — Are you working? (do/does yo'q).","Qisqa javob: Yes, I am. / No, she isn't. — fe'l takrorlanmaydi; Yes, I'm ❌.","Wh-savol: What are you doing? Where is he going?","Yangi so'zlar: free, bored, outside, inside, lunch, homework."]},{"id":"u4-l11","slug":"on-the-phone-what-are-you-doing","title":"On the phone: what are you doing?","titleUz":"Telefonda: nima qilyapsiz?","goal":"Telefonda yoki chatda hozir nima qilayotganingizni aytasiz va so'raysiz: What are you doing? — I'm cooking. Where are you? Present Continuous va have got (oila) ni qayta ishlatasiz.","words":[{"en":"call","uz":"qo'ng'iroq qilmoq","ipa":"kɔːl"},{"en":"message","uz":"xabar","ipa":"ˈmes.ɪdʒ"},{"en":"hear","uz":"eshitmoq","ipa":"hɪər"},{"en":"online","uz":"onlayn, internetda","ipa":"ˈɒn.laɪn"}],"summary":["Hozirgi ish: am / is / are + -ing. Savol: What are you doing?","Qisqa javob: Yes, I am. / No, he isn't. Telefonda: I can't hear you. Can you call me later?","Oila haqida: have got / has got: Have you got a brother?","Yangi so'zlar: call, message, hear, online."]},{"id":"u4-l18","slug":"what-are-they-doing-listening-and-speaking","title":"What are they doing? Listening and speaking","titleUz":"Ular nima qilyapti? Tinglash va gapirish","goal":"Rasm yoki telefon suhbatida kim hozir nima qilayotganini tinglab tushunasiz va o'zingiz ham shunday gapirib bera olasiz: A boy is riding a bike. Two girls are sitting on a bench.","words":[{"en":"picture","uz":"rasm, surat","ipa":"ˈpɪk.tʃər"},{"en":"bench","uz":"skameyka","ipa":"bentʃ"},{"en":"ice cream","uz":"muzqaymoq","ipa":"ˈaɪs kriːm"},{"en":"bike","uz":"velosiped","ipa":"baɪk"},{"en":"ball","uz":"to'p","ipa":"bɔːl"},{"en":"ride","uz":"minmoq, haydamoq","ipa":"raɪd"}],"summary":["Tinglaganda kim + am/is/are + fe'l-ing ni toping: Sam is riding a bike.","Rasmni tasvirlash: avval joy (This is a park.), keyin kim nima qilyapti (A girl is eating ice cream.).","Savol-javob: Are your friends there? — Yes, they are.","Yangi so'zlar: picture, bench, ice cream, bike, ball, ride."]},{"id":"u4-l12","slug":"describing-and-asking-final-review","title":"Describing and asking: final review","titleUz":"Tasvirlash va so'rash: yakuniy takror","goal":"4-bo'limni yakunlaysiz: Wh- savollar, there is/are, predloglar, much/many, can/can't, buyruqlar, have got va Present Continuous — hammasi bitta joyda.","words":[{"en":"sure","uz":"albatta; ishonchli","ipa":"ʃɔːr"},{"en":"together","uz":"birga","ipa":"təˈɡeð.ər"},{"en":"quickly","uz":"tez, tezda","ipa":"ˈkwɪk.li"}],"summary":["Wh- savollar: what, where, who, why, which, whose, how many/much.","There is / are, some / any va predloglar bilan joyni tasvirlang.","can / can't, buyruqlar (Sit down. Don't run!), have got / has got.","Present Continuous: am/is/are + -ing — hozirgi ish."]}]},{"id":"u5","n":5,"title":"Past & Future","titleUz":"Kecha, ertaga, hozir: o'tgan va kelasi zamon","description":"Ikki hozirgi zamon farqi, was / were, Past Simple, noto'g'ri fe'llar, going to, will, qiyoslash.","canDo":["Kecha va o'tgan hafta nima bo'lganini aytaman","To'g'ri va noto'g'ri fe'llarni o'tgan zamonda ishlataman","Kelajak rejalarimni (going to, will) ayta olaman","Narsalarni solishtiraman (bigger, the biggest)"],"lessons":[{"id":"u5-l1","slug":"present-simple-vs-continuous","title":"Present Simple vs Continuous","titleUz":"Present Simple yoki Continuous?","goal":"Ikki hozirgi zamonni farqlaysiz: odat va doimiy holat uchun Present Simple (I work), ayni paytdagi ish uchun Present Continuous (I am working). Ob-havo va fasllar haqida gapira olasiz.","words":[{"en":"weather","uz":"ob-havo","ipa":"ˈweð.ə"},{"en":"sunny","uz":"quyoshli","ipa":"ˈsʌn.i"},{"en":"rainy","uz":"yomg'irli","ipa":"ˈreɪ.ni"},{"en":"windy","uz":"shamolli","ipa":"ˈwɪn.di"},{"en":"cloudy","uz":"bulutli","ipa":"ˈklaʊ.di"},{"en":"warm","uz":"iliq","ipa":"wɔːm"},{"en":"spring","uz":"bahor","ipa":"sprɪŋ"},{"en":"summer","uz":"yoz","ipa":"ˈsʌm.ə"},{"en":"autumn","uz":"kuz","ipa":"ˈɔː.təm"},{"en":"winter","uz":"qish","ipa":"ˈwɪn.tə"}],"summary":["Present Simple — odat va doimiy holat: I work in a bank. He usually goes by bus.","Present Continuous — ayni paytdagi ish: I'm working now. Look! It's raining.","Signal so'zlar: every day, usually, often → Simple; now, at the moment, Look! → Continuous.","like, love, want, need, know, understand, have (ega bo'lmoq) -ing olmaydi.","Ob-havo — doim It bilan: It's sunny / windy / cloudy. Fasllar: in spring, summer, autumn, winter."]},{"id":"u5-l2","slug":"was-were","title":"was / were","titleUz":"O'tgan zamon: was / were","goal":"to be fe'lini o'tgan zamonda ishlatasiz: I was at home. They weren't late. Where were you? Qachon va qayerda tug'ilganingizni ayta olasiz (I was born in…).","words":[{"en":"yesterday","uz":"kecha","ipa":"ˈjes.tə.deɪ"},{"en":"last night","uz":"kecha kechqurun","ipa":"ˌlɑːst ˈnaɪt"},{"en":"last week","uz":"o'tgan hafta","ipa":"ˌlɑːst ˈwiːk"},{"en":"ago","uz":"oldin","ipa":"əˈɡəʊ"},{"en":"born","uz":"tug'ilgan","ipa":"bɔːn"},{"en":"museum","uz":"muzey","ipa":"mjuˈziː.əm"},{"en":"beach","uz":"plyaj, sohil","ipa":"biːtʃ"},{"en":"village","uz":"qishloq","ipa":"ˈvɪl.ɪdʒ"},{"en":"at the weekend","uz":"dam olish kunlarida","ipa":"ət ðə ˌwiːkˈend"},{"en":"concert","uz":"konsert","ipa":"ˈkɒn.sət"}],"summary":["am / is → was, are → were: I was, he was, we were, they were.","Inkor: wasn't / weren't. Savol: Was he…? Were you…? — Yes, I was. / No, they weren't.","Tug'ilgan joy va yil: I was born in… (I born ❌).","Vaqt: yesterday, last night, last week, at the weekend, son + ago (two days ago)."]},{"id":"u5-l3","slug":"past-simple-regular-verbs","title":"Past Simple: regular verbs","titleUz":"Past Simple: to'g'ri fe'llar (-ed)","goal":"O'tmishda tugagan ishlar haqida gapirasiz: I visited my grandmother yesterday. -ed ni to'g'ri yozasiz (stopped, studied, played) va uch xil talaffuzini (/t/ /d/ /ɪd/) ajratasiz.","words":[{"en":"visit","uz":"borib ko'rmoq, ziyorat qilmoq","ipa":"ˈvɪz.ɪt"},{"en":"play","uz":"o'ynamoq","ipa":"pleɪ"},{"en":"cook","uz":"ovqat pishirmoq","ipa":"kʊk"},{"en":"clean","uz":"tozalamoq","ipa":"kliːn"},{"en":"start","uz":"boshlamoq, boshlanmoq","ipa":"stɑːt"},{"en":"finish","uz":"tugatmoq, tugamoq","ipa":"ˈfɪn.ɪʃ"},{"en":"open","uz":"ochmoq","ipa":"ˈəʊ.pən"},{"en":"want","uz":"xohlamoq","ipa":"wɒnt"},{"en":"arrive","uz":"yetib kelmoq","ipa":"əˈraɪv"},{"en":"stay","uz":"qolmoq","ipa":"steɪ"}],"summary":["Past Simple — o'tmishda tugagan ish. To'g'ri fe'llar: fe'l + ed, hamma shaxs uchun bir xil (she played).","Imlo: arrive → arrived, study → studied, play → played, stop → stopped.","Talaffuz: /t/ cooked, watched · /d/ played, cleaned · /ɪd/ wanted, visited (faqat t / d dan keyin).","Harakat uchun was kerak emas: I cleaned ✅, I was cleaned ❌."]},{"id":"u5-l13","slug":"ed-spelling","title":"-ed: spelling","titleUz":"-ed qo'shish imlosi: stop → stopped","goal":"Fe'lga -ed ni xatosiz qo'shasiz: play → played, like → liked, study → studied, stop → stopped. To'rt xil imlo qoidasini bilib olasiz.","words":[{"en":"carry","uz":"ko'tarib yurmoq","ipa":"ˈkær.i"},{"en":"plan","uz":"rejalashtirmoq","ipa":"plæn"},{"en":"drop","uz":"tushirib yubormoq","ipa":"drɒp"},{"en":"try","uz":"urinib ko'rmoq","ipa":"traɪ"},{"en":"hurry","uz":"shoshilmoq","ipa":"ˈhʌr.i"},{"en":"travel","uz":"sayohat qilmoq","ipa":"ˈtræv.əl"}],"summary":["Oddiy qoida: fe'l + -ed (worked, played, stayed).","-e bilan tugasa, faqat -d: like → liked, arrive → arrived.","Undosh + y → ied: study → studied, try → tried. Unli + y o'zgarmaydi: played.","Qisqa undosh-unli-undosh fe'l ikkilanadi: stop → stopped, plan → planned.","travel → travelled (Britaniya) yoki traveled (Amerika)."]},{"id":"u5-l14","slug":"ed-pronunciation","title":"-ed: pronunciation","titleUz":"-ed talaffuzi: /t/, /d/, /ɪd/","goal":"-ed ni to'g'ri talaffuz qilasiz: worked (/t/), played (/d/), wanted (/ɪd/). Eshitib qaysi tovush ekanini ajratasiz.","words":[{"en":"walk","uz":"yurmoq, piyoda bormoq","ipa":"wɔːk"},{"en":"jump","uz":"sakramoq","ipa":"dʒʌmp"},{"en":"answer","uz":"javob bermoq","ipa":"ˈɑːn.sər"},{"en":"invite","uz":"taklif qilmoq","ipa":"ɪnˈvaɪt"},{"en":"paint","uz":"bo'yamoq, rasm chizmoq","ipa":"peɪnt"},{"en":"wash","uz":"yuvmoq","ipa":"wɒʃ"}],"summary":["-ed uch xil o'qiladi: /t/, /d/, /ɪd/.","p, k, f, s, sh, ch dan keyin /t/: worked, washed, jumped.","Jarangli tovush va unlidan keyin /d/: played, cleaned, stayed.","t yoki d dan keyin /ɪd/ (qo'shimcha bo'g'in): wanted, needed, invited.","Faqat /ɪd/ da so'z bo'g'inga uzayadi. worked — \"work-id\" emas!"]},{"id":"u5-l4","slug":"irregular-verbs-1","title":"Irregular verbs 1","titleUz":"Noto'g'ri fe'llar 1","goal":"Eng ko'p ishlatiladigan 10 ta noto'g'ri fe'lning o'tgan zamon shaklini (went, came, got, had, did, made, took, saw, said, was/were) bilasiz va kuningiz haqida o'tgan zamonda gapirasiz.","words":[{"en":"be – was/were","uz":"bo'lmoq","ipa":"biː – wɒz/wɜː"},{"en":"have – had","uz":"ega bo'lmoq; yemoq","ipa":"hæv – hæd"},{"en":"do – did","uz":"qilmoq","ipa":"duː – dɪd"},{"en":"go – went","uz":"bormoq","ipa":"ɡəʊ – went"},{"en":"come – came","uz":"kelmoq","ipa":"kʌm – keɪm"},{"en":"get – got","uz":"olmoq; bo'lmoq","ipa":"ɡet – ɡɒt"},{"en":"make – made","uz":"yasamoq, tayyorlamoq","ipa":"meɪk – meɪd"},{"en":"take – took","uz":"olmoq, olib ketmoq","ipa":"teɪk – tʊk"},{"en":"see – saw","uz":"ko'rmoq","ipa":"siː – sɔː"},{"en":"say – said","uz":"aytmoq","ipa":"seɪ – sed"}],"summary":["Noto'g'ri fe'llar -ed olmaydi, V2 ni yodlash kerak; shakl hamma shaxs uchun bir xil.","be – was/were, have – had, do – did, go – went, come – came.","get – got, make – made, take – took, see – saw, say – said (\"sed\"!).","Iboralar: got up, had breakfast, went home, did my homework, made tea, took the bus."]},{"id":"u5-l5","slug":"irregular-verbs-2-didnt-did","title":"Irregular verbs 2: didn't, Did…?","titleUz":"Noto'g'ri fe'llar 2, didn't va Did…?","goal":"Yana 10 ta noto'g'ri fe'lni o'rganasiz va o'tgan zamonda inkor (I didn't go) hamda savol (Did you see…? What did you eat?) tuza olasiz.","words":[{"en":"give – gave","uz":"bermoq","ipa":"ɡɪv – ɡeɪv"},{"en":"know – knew","uz":"bilmoq","ipa":"nəʊ – njuː"},{"en":"think – thought","uz":"o'ylamoq","ipa":"θɪŋk – θɔːt"},{"en":"buy – bought","uz":"sotib olmoq","ipa":"baɪ – bɔːt"},{"en":"eat – ate","uz":"yemoq","ipa":"iːt – et"},{"en":"drink – drank","uz":"ichmoq","ipa":"drɪŋk – dræŋk"},{"en":"write – wrote","uz":"yozmoq","ipa":"raɪt – rəʊt"},{"en":"read – read","uz":"o'qimoq","ipa":"riːd – red"},{"en":"find – found","uz":"topmoq","ipa":"faɪnd – faʊnd"},{"en":"meet – met","uz":"uchrashmoq, tanishmoq","ipa":"miːt – met"}],"summary":["give – gave, know – knew, think – thought, buy – bought, eat – ate.","drink – drank, write – wrote, read – read (\"red\"), find – found, meet – met.","Inkor: didn't + V1 — I didn't go (❌ didn't went).","Savol: Did + ega + V1? — Did you see it? What did you buy? Javob: Yes, I did. / No, I didn't.","to be bilan did yo'q: Were you…? I wasn't…"]},{"id":"u5-l15","slug":"past-simple-short-answers-and-wh-questions","title":"Past Simple: short answers and Wh- questions","titleUz":"Past Simple: qisqa javoblar va Wh-savollar","goal":"Savolga qisqa javob berasiz (Did you go? — Yes, I did.) va so'roq so'zli savollar tuzasiz: What did you do? Where did she go? When did they arrive?","words":[{"en":"ask","uz":"so'ramoq","ipa":"ɑːsk"},{"en":"wait","uz":"kutmoq","ipa":"weɪt"},{"en":"call","uz":"qo'ng'iroq qilmoq","ipa":"kɔːl"},{"en":"reply","uz":"javob qaytarmoq","ipa":"rɪˈplaɪ"},{"en":"early","uz":"erta","ipa":"ˈɜː.li"},{"en":"late","uz":"kech","ipa":"leɪt"}],"summary":["Qisqa javob: Yes, I did. / No, I didn't. Asosiy fe'l takrorlanmaydi.","was / were savoli: Yes, it was. did emas.","Wh-savol tartibi: so'roq so'z + did + ega + V1 (Where did she go?).","did dan keyin fe'l oddiy shaklda: go, eat, do (went, ate, did emas).","To'liq javobda V2: I went to a café."]},{"id":"u5-l9","slug":"yesterday-telling-what-happened","title":"Yesterday: telling what happened","titleUz":"Kecha nima bo'ldi: Past Simple hayotda","goal":"Do'stingizga kecha nima bo'lganini aytib berasiz va savol berasiz: I went to a party. Did you go? — No, I didn't. was / were, Past Simple, didn't va Did…? ni real suhbatda ishlatasiz.","words":[{"en":"party","uz":"ziyofat, bazm","ipa":"ˈpɑː.ti"},{"en":"cinema","uz":"kinoteatr","ipa":"ˈsɪn.ə.mə"},{"en":"funny","uz":"kulgili","ipa":"ˈfʌn.i"},{"en":"boring","uz":"zerikarli","ipa":"ˈbɔː.rɪŋ"}],"summary":["Kecha haqida savol: What did you do yesterday? / Where were you?","was (I, he, she, it) va were (you, we, they); Past Simple: visited, went, saw.","did / didn't dan keyin fe'l oddiy shaklda: Did you go? — I didn't go."]},{"id":"u5-l18","slug":"real-life-how-was-your-weekend","title":"Real life: how was your weekend?","titleUz":"Real hayot: dam olish kuni qanday o'tdi?","goal":"Do'stingizga dam olish kuningiz haqida gapirib berasiz: nima qildingiz, nima qilmadingiz, va o'zingiz ham savol berasiz. Past Simple ni jonli suhbatda ishlatasiz.","words":[],"summary":["How was your weekend? → It was great. (it bilan was, were emas).","Tartibsiz fe'llar: go → went, see → saw, eat → ate (goed emas).","Did you play football? — Did dan keyin fe'lning oddiy shakli: Did you went emas.","No, I didn't. I watched a film. — didn't + oddiy shakl.","What did you do on Sunday? — o'tgan zamondagi savol."]},{"id":"u5-l16","slug":"reading-a-day-last-week","title":"Reading: a day last week","titleUz":"O'qish: o'tgan haftadagi bir kun","goal":"Past Simple'dagi qisqa inglizcha matnlarni o'qib, asosiy fikrni va tafsilotlarni tushunasiz, hamda noma'lum so'zning ma'nosini gapdan topasiz.","words":[{"en":"noisy","uz":"shovqinli","ipa":"ˈnɔɪ.zi"},{"en":"delicious","uz":"mazali","ipa":"dɪˈlɪʃ.əs"},{"en":"wait","uz":"kutmoq","ipa":"weɪt"},{"en":"lucky","uz":"omadli","ipa":"ˈlʌk.i"},{"en":"ill","uz":"kasal","ipa":"ɪl"},{"en":"rest","uz":"dam olmoq","ipa":"rest"}],"summary":["O'qishdan oldin savolga qarang, so'ng vaqt so'zlari (last Saturday, yesterday) va fe'llarni (-ed, went, saw, had) toping.","Noma'lum so'zda to'xtamang: gapning ma'nosidan taxmin qiling.","Past Simple: was / were, -ed, noto'g'ri fe'llar; inkorda didn't + V1 (didn't go).","Yangi so'zlar: noisy, delicious, wait, lucky, ill, rest."]},{"id":"u5-l6","slug":"future-be-going-to","title":"Future: be going to","titleUz":"Kelasi zamon: be going to","goal":"Rejalaringiz haqida gapirasiz (I'm going to visit Bukhara next week) va ko'z oldingizdagi dalilga qarab bashorat qilasiz (Look! It's going to rain). Sayohatga oid 10 ta so'zni bilib olasiz.","words":[{"en":"plan","uz":"reja; rejalashtirmoq","ipa":"plæn"},{"en":"trip","uz":"sayohat, safar","ipa":"trɪp"},{"en":"ticket","uz":"chipta","ipa":"ˈtɪk.ɪt"},{"en":"holiday","uz":"ta'til, dam olish","ipa":"ˈhɒl.ə.deɪ"},{"en":"airport","uz":"aeroport","ipa":"ˈeə.pɔːt"},{"en":"train","uz":"poyezd","ipa":"treɪn"},{"en":"hotel","uz":"mehmonxona","ipa":"həʊˈtel"},{"en":"suitcase","uz":"chamadon","ipa":"ˈsuːt.keɪs"},{"en":"passport","uz":"pasport","ipa":"ˈpɑːs.pɔːt"},{"en":"abroad","uz":"chet elga, chet elda","ipa":"əˈbrɔːd"}],"summary":["am / is / are + going to + V1 — oldindan qilingan reja: I'm going to visit Khiva.","Inkor: She isn't going to fly. Savol: Are you going to stay? — Yes, I am.","Dalilga asoslangan bashorat: Look at the clouds! It's going to rain.","Vaqt: tomorrow, tonight, next week, next summer (the next week ❌). go abroad (to yo'q)."]},{"id":"u5-l7","slug":"future-will","title":"Future: will","titleUz":"Kelasi zamon: will","goal":"will bilan shu zahoti qaror qilasiz, va'da va taklif berasiz, kelajak haqida fikr bildirasiz (I'll help you. I think it will rain.). will va going to ni farqlaysiz.","words":[{"en":"maybe","uz":"balki","ipa":"ˈmeɪ.bi"},{"en":"probably","uz":"ehtimol","ipa":"ˈprɒb.ə.bli"},{"en":"promise","uz":"va'da; va'da bermoq","ipa":"ˈprɒm.ɪs"},{"en":"decide","uz":"qaror qilmoq","ipa":"dɪˈsaɪd"},{"en":"future","uz":"kelajak","ipa":"ˈfjuː.tʃə"},{"en":"soon","uz":"tez orada, yaqinda","ipa":"suːn"},{"en":"later","uz":"keyinroq","ipa":"ˈleɪ.tə"},{"en":"next year","uz":"kelasi yil","ipa":"ˌnekst ˈjɪə"},{"en":"I think","uz":"menimcha, deb o'ylayman","ipa":"aɪ ˈθɪŋk"},{"en":"hope","uz":"umid qilmoq","ipa":"həʊp"}],"summary":["will + V1 (hamma shaxsga bir xil): I'll help. He won't come. Will you…?","will — shu zahoti qaror, va'da, taklif, fikr: I'll close the window. I promise I'll call.","Fikr bilan: I think / maybe / probably / I hope + will.","going to — oldindan reja yoki ko'z oldingizdagi dalil; will — hozirgi qaror yoki shunchaki fikr.","Talaffuz: won't \"wount\" ≠ want \"wont\"."]},{"id":"u5-l8","slug":"comparatives-superlatives","title":"Comparatives & superlatives","titleUz":"Qiyoslash: bigger, the biggest","goal":"Narsalar va odamlarni solishtirasiz: Tashkent is bigger than Samarkand. This is the most interesting book. -er / -est, more / most va good – better – best kabi istisnolarni to'g'ri ishlatasiz.","words":[{"en":"fast","uz":"tez","ipa":"fɑːst"},{"en":"slow","uz":"sekin","ipa":"sləʊ"},{"en":"strong","uz":"kuchli","ipa":"strɒŋ"},{"en":"easy","uz":"oson","ipa":"ˈiː.zi"},{"en":"difficult","uz":"qiyin","ipa":"ˈdɪf.ɪ.kəlt"},{"en":"important","uz":"muhim","ipa":"ɪmˈpɔː.tənt"},{"en":"interesting","uz":"qiziqarli","ipa":"ˈɪn.trə.stɪŋ"},{"en":"good – better – best","uz":"yaxshi – yaxshiroq – eng yaxshi","ipa":"ɡʊd – ˈbet.ə – best"},{"en":"bad – worse – worst","uz":"yomon – yomonroq – eng yomon","ipa":"bæd – wɜːs – wɜːst"},{"en":"far – further – furthest","uz":"uzoq – uzoqroq – eng uzoq","ipa":"fɑː – ˈfɜː.ðə – ˈfɜː.ðɪst"}],"summary":["Qisqa sifatlar: -er than / the -est — bigger than, the biggest; easier, the easiest.","Uzun sifatlar: more … than / the most … — more difficult, the most interesting.","Istisnolar: good – better – best, bad – worse – worst, far – further – furthest.","more va -er birga kelmaydi (more bigger ❌); orttirma darajada the shart.","🎉 Tabriklaymiz — Beginner kursini tugatdingiz! Endi siz o'tmish, hozir va kelajak haqida inglizcha gapira olasiz."]},{"id":"u5-l10","slug":"plans-for-the-weekend","title":"Plans for the weekend","titleUz":"Dam olish kuni rejalari: going to, will","goal":"Dam olish kuni rejalaringiz haqida gapirasiz va joyida qaror qabul qilasiz: I'm going to visit my cousin. — OK, I'll come with you! be going to (reja) va will (qaror, va'da) ni farqlaysiz.","words":[{"en":"picnic","uz":"piknik","ipa":"ˈpɪk.nɪk"},{"en":"relax","uz":"dam olmoq","ipa":"rɪˈlæks"},{"en":"swim","uz":"suzmoq","ipa":"swɪm"},{"en":"cousin","uz":"amakivachcha, xolavachcha","ipa":"ˈkʌz.ən"}],"summary":["be going to — oldindan reja: I'm going to visit my cousin.","will — joyida qaror, va'da, taxmin: I'll come. I promise I won't be late.","will dan keyin to yo'q; going to da am / is / are kerak."]},{"id":"u5-l19","slug":"real-life-plans-for-the-weekend","title":"Real life: plans for the weekend","titleUz":"Real hayot: dam olish kuni rejalari","goal":"Do'stingiz bilan dam olish kuni rejalarini gaplashasiz: rejangizni aytasiz (be going to), ob-havo haqida fikr bildirasiz va shu zahoti qaror qilsangiz will ishlatasiz.","words":[],"summary":["I'm going to visit my grandmother. — oldindan tuzilgan reja: am / is / are + going to + fe'l.","Are you going to play football? → No, I'm not.","I think it will be sunny. — taxmin: will + oddiy fe'l (will be).","I'll help you. — shu zahoti qilingan qaror: will; oldindan reja: going to."]},{"id":"u5-l11","slug":"choosing-in-a-shop-comparing","title":"Choosing in a shop: comparing","titleUz":"Do'konda tanlash: qiyoslash","goal":"Do'konda narsalarni solishtirasiz va tanlaysiz: This jacket is cheaper than that one. I'll take the cheapest. -er / -est, more / most, better / the best ni real vaziyatda ishlatasiz.","words":[{"en":"size","uz":"o'lcham","ipa":"saɪz"},{"en":"choose","uz":"tanlamoq","ipa":"tʃuːz"},{"en":"discount","uz":"chegirma","ipa":"ˈdɪs.kaʊnt"},{"en":"comfortable","uz":"qulay","ipa":"ˈkʌm.fə.tə.bəl"}],"summary":["Ikkita narsa: sifat + er + than (cheaper than), uzun sifat: more expensive than.","Hammasidan eng: the + -est / the most (the cheapest, the most comfortable).","Istisnolar: good – better – the best, bad – worse – the worst."]},{"id":"u5-l17","slug":"listening-and-speaking-my-last-weekend","title":"Listening and speaking: my last weekend","titleUz":"Tinglash va gapirish: o'tgan dam olish kunim","goal":"Dam olish kuningiz haqidagi suhbatni tinglab tushunasiz va o'zingiz o'tgan dam olish kuni haqida (I went… It was… I didn't…) hamda keyingi rejangiz haqida gapira olasiz.","words":[{"en":"lake","uz":"ko'l","ipa":"leɪk"},{"en":"mountain","uz":"tog'","ipa":"ˈmaʊn.tɪn"},{"en":"fishing","uz":"baliq ovlash","ipa":"ˈfɪʃ.ɪŋ"},{"en":"sunny","uz":"quyoshli","ipa":"ˈsʌn.i"},{"en":"rainy","uz":"yomg'irli","ipa":"ˈreɪ.ni"},{"en":"win","uz":"yutmoq","ipa":"wɪn"}],"summary":["Dam olish kunini so'rash: How was your weekend? Where did you go? What did you do? Javob: It was great. I went… I had… I didn't…","Faqat Yes / No demang: Yes, I did. + bitta qo'shimcha gap.","Rejani be going to bilan ayting: Next weekend I am going to visit my cousin.","Namuna matn: Last weekend I was at home. On Saturday we visited my grandmother. On Sunday it was sunny, so I went to the park. We played football, but we didn't win. It was a good weekend."]},{"id":"u5-l20","slug":"real-life-a-day-in-a-new-city","title":"Real life: a day in a new city","titleUz":"Real hayot: yakuniy missiya — yangi shaharda bir kun","goal":"Yangi shaharda bir kun o'tkazasiz: do'st bilan tanishasiz, yo'l so'raysiz, kafeda buyurtma berasiz, kecha nima qilganingizni va ertangi rejangizni aytasiz. Butun Beginner kursi bitta missiyada.","words":[],"summary":["Tanishuv: Nice to meet you. I'm from Uzbekistan. I'm a student. (to be).","Yo'l so'rash: Excuse me, where is the museum?","Kafeda: I'd like a tea, please. How much is it?","Kecha: I went / I met / I visited...; savol: Did you...?","Reja: I'm going to visit the museum tomorrow."]},{"id":"u5-l12","slug":"past-and-future-final-review","title":"Past and future: final review","titleUz":"O'tgan va kelasi zamon: yakuniy takror","goal":"5-bo'lim bo'yicha yakuniy takror: Present Simple va Continuous, was / were, Past Simple, be going to, will va qiyoslash darajalarini bitta suhbatda aralashtirib ishlatasiz.","words":[{"en":"grandmother","uz":"buvi","ipa":"ˈɡræn.mʌð.ər"},{"en":"kind","uz":"mehribon","ipa":"kaɪnd"},{"en":"drive","uz":"mashina haydamoq","ipa":"draɪv"},{"en":"dinner","uz":"kechki ovqat","ipa":"ˈdɪn.ər"}],"summary":["Vaqt belgisiga qarang: now → Continuous, usually → Simple, yesterday → Past, tomorrow → going to / will.","was / were, didn't / Did…? + oddiy fe'l; will + oddiy fe'l; going to oldidan am / is / are.","Qiyoslash: -er … than, the -est, more / the most; istisno: good – better – best."]}]}]},{"id":"a1","slug":"elementary","title":"Elementary","cefr":"A1","text":"Oddiy gaplarni tushunaman, o'zim haqimda biroz gapira olaman.","units":[{"id":"u6","n":6,"title":"People & Places","titleUz":"Odamlar va joylar: tasvirlash, egalik, yo'l so'rash","description":"Tanishuv, odamlarni tasvirlash, mine / yours, tartib sonlar va sanalar, uy, shahar va yo'l so'rash, a / the.","canDo":["O'zimni va boshqalarni tanishtiraman","Odamning tashqi ko'rinishi va xarakterini tasvirlayman","Sana va tartib sonlarni aytaman","Yo'l so'rayman va yo'l ko'rsataman"],"lessons":[{"id":"u6-l1","slug":"nice-to-meet-you","title":"Nice to meet you!","titleUz":"Tanishuv va qisqa suhbat","goal":"Yangi odam bilan tanishib, boshqalarni tanishtirasiz (This is my colleague, Kamola.), What do you do? / Where are you from exactly? kabi savollar bilan suhbatni davom ettirasiz va uni muloyim yakunlaysiz (It was nice to meet you.).","words":[{"en":"introduce","uz":"tanishtirmoq","ipa":"ˌɪn.trəˈdjuːs"},{"en":"journalist","uz":"jurnalist","ipa":"ˈdʒɜː.nə.lɪst"},{"en":"conference","uz":"konferensiya","ipa":"ˈkɒn.fər.əns"},{"en":"small talk","uz":"qisqa suhbat (kundalik gap-so'z)","ipa":"ˈsmɔːl tɔːk"},{"en":"exactly","uz":"aniq, aynan","ipa":"ɪɡˈzækt.li"},{"en":"first name","uz":"ism","ipa":"ˈfɜːst neɪm"},{"en":"hometown","uz":"tug'ilgan shahar, ona shahar","ipa":"ˈhəʊm.taʊn"},{"en":"actually","uz":"aslida, haqiqatda","ipa":"ˈæk.tʃu.ə.li"},{"en":"by the way","uz":"aytgancha","ipa":"baɪ ðə ˈweɪ"},{"en":"pleased","uz":"xursand","ipa":"pliːzd"}],"summary":["Tanishuv: Nice to meet you. — Nice to meet you too. Eski tanishga: Nice to see you!","Boshqani tanishtirish: This is my colleague, Kamola. / These are my parents. (❌ He is…)","What do you do? — kasb; What are you doing? — hozirgi harakat. Savolni qaytaring: And you? / What about you?","Reaksiya: Really? That's interesting!; actually = aslida, by the way = aytgancha.","Xayrlashuv: It was nice to meet you. / Have a nice day!"]},{"id":"u6-l2","slug":"what-does-she-look-like","title":"What does she look like?","titleUz":"Tashqi ko'rinishni tasvirlash","goal":"What does he/she look like? savoliga javob berib, odamning bo'yi, qaddi-qomati, sochi, ko'zlari va yoshini tasvirlaysiz: She's tall and slim. She has long curly black hair. Sifatlar tartibini va look like ning ikki ma'nosini bilasiz.","words":[{"en":"look like","uz":"…ga o'xshamoq","ipa":"ˈlʊk laɪk"},{"en":"slim","uz":"qaddi-qomati kelishgan, ozg'in","ipa":"slɪm"},{"en":"curly","uz":"jingalak","ipa":"ˈkɜː.li"},{"en":"straight","uz":"tekis, to'g'ri (soch)","ipa":"streɪt"},{"en":"fair","uz":"och rang, sariq (soch, teri)","ipa":"feə"},{"en":"beard","uz":"soqol","ipa":"bɪəd"},{"en":"moustache","uz":"mo'ylov","ipa":"məˈstɑːʃ"},{"en":"glasses","uz":"ko'zoynak","ipa":"ˈɡlɑː.sɪz"},{"en":"middle-aged","uz":"o'rta yoshli","ipa":"ˌmɪd.əlˈeɪdʒd"},{"en":"good-looking","uz":"chiroyli, kelishgan","ipa":"ˌɡʊdˈlʊk.ɪŋ"}],"summary":["Savol: What does he/she look like? — tashqi ko'rinish.","be — bo'y, qomat, yosh (She's tall / slim / in her twenties); have (got) — soch, ko'z, soqol; wear — ko'zoynak.","hair sanalmaydi: Her hair is long. Sifatlar tartibi: long curly black hair.","look + sifat (You look tired), look like + ot (She looks like her mum).","Muloyim so'zlar: slim, a bit overweight, elderly; odam — tall, ❌ high."]},{"id":"u6-l3","slug":"personality-very-quite-really","title":"Personality: very, quite, really","titleUz":"Xarakter va sifatlar: very, quite, really","goal":"What is he like? savoliga javob berib, odamning xarakterini tasvirlaysiz (kind, shy, hard-working, rude…) va fikringizni very, really, quite, a bit, not very bilan aniq va muloyim ifodalaysiz.","words":[{"en":"friendly","uz":"do'stona, xushmuomala","ipa":"ˈfrend.li"},{"en":"polite","uz":"odobli, xushmuomala","ipa":"pəˈlaɪt"},{"en":"rude","uz":"qo'pol, odobsiz","ipa":"ruːd"},{"en":"hard-working","uz":"mehnatkash","ipa":"ˌhɑːdˈwɜː.kɪŋ"},{"en":"lazy","uz":"dangasa","ipa":"ˈleɪ.zi"},{"en":"shy","uz":"uyatchan","ipa":"ʃaɪ"},{"en":"talkative","uz":"gapdon, ko'p gapiradigan","ipa":"ˈtɔː.kə.tɪv"},{"en":"patient","uz":"sabrli","ipa":"ˈpeɪ.ʃənt"},{"en":"generous","uz":"saxiy, qo'li ochiq","ipa":"ˈdʒen.ər.əs"},{"en":"funny","uz":"kuldiradigan, hazilkash","ipa":"ˈfʌn.i"}],"summary":["What is she like? — xarakter; What does she look like? — tashqi ko'rinish; What does she like? — nimani yoqtiradi.","Juftliklar: polite – rude, hard-working – lazy, generous – mean, patient – impatient, talkative – quiet/shy.","Kuch darajasi: really / very > quite > a bit > not very. a bit — salbiy sifat bilan.","a very kind man, lekin quite a kind man. Fe'l bilan: I really like… / I like… very much (❌ I very like).","Muloyim tanqid: He isn't very polite."]},{"id":"u6-l9","slug":"meeting-a-new-neighbour","title":"Meeting a new neighbour","titleUz":"Yangi qo'shni bilan tanishuv","goal":"Yangi qo'shni bilan tanishasiz, uning oilasi va ko'rinishi haqida so'raysiz va kichik suhbat qurasiz: Nice to meet you! I'm your new neighbour. Where are you from?","words":[{"en":"neighbour","uz":"qo'shni","ipa":"ˈneɪ.bər"},{"en":"move in","uz":"ko'chib kirmoq","ipa":"muːv ɪn"},{"en":"welcome","uz":"xush kelibsiz","ipa":"ˈwel.kəm"},{"en":"nearby","uz":"yaqin atrofda","ipa":"ˌnɪəˈbaɪ"},{"en":"building","uz":"bino","ipa":"ˈbɪl.dɪŋ"},{"en":"next door","uz":"yonma-yon eshikda","ipa":"ˌnekst ˈdɔː"}],"summary":["Tanishuv: I'm your new neighbour. Nice to meet you. Where are you from?","Ko'rinish: What does she look like? — She has long curly hair. Xarakter: She's friendly.","Yangi so'zlar: neighbour, move in, welcome, nearby, building, next door."]},{"id":"u6-l4","slug":"mine-yours-whose","title":"mine, yours… Whose?","titleUz":"Egalik olmoshlari: mine, yours… va Whose?","goal":"Narsa kimniki ekanini so'raysiz va aytasiz: Whose bag is this? — It's mine / It's Ali's. my – mine, your – yours, her – hers… farqini bilasiz va whose / who's ni adashtirmaysiz.","words":[{"en":"purse","uz":"hamyon","ipa":"pɜːs"},{"en":"wallet","uz":"hamyon","ipa":"ˈwɒl.ɪt"},{"en":"lend","uz":"qarz bermoq, vaqtincha bermoq","ipa":"lend"},{"en":"charger","uz":"quvvatlagich (zaryadlovchi)","ipa":"ˈtʃɑː.dʒə"},{"en":"earphones","uz":"quloqchinlar","ipa":"ˈɪə.fəʊnz"},{"en":"scarf","uz":"sharf, ro'mol","ipa":"skɑːf"},{"en":"belong to","uz":"…ga tegishli bo'lmoq","ipa":"bɪˈlɒŋ tə"},{"en":"borrow","uz":"qarzga (vaqtincha) olmoq","ipa":"ˈbɒr.əʊ"},{"en":"lose","uz":"yo'qotmoq","ipa":"luːz"},{"en":"a friend of mine","uz":"do'stlarimdan biri","ipa":"ə ˈfrend əv maɪn"}],"summary":["Ot bilan: my, your, his, her, our, their; otsiz: mine, yours, his, hers, ours, theirs.","Apostrof yo'q: yours, hers, ours, theirs (❌ your's). ❌ mine bag, ❌ It's my.","Whose bag is this? / Whose is this bag? — It's mine / It's Ali's. Ko'plikda: Whose keys are these? — They're…","whose (kimning) ≠ who's (= who is / who has) — talaffuzi bir xil \"hu:z\".","a friend of mine, belong to + kishi: It belongs to my dad."]},{"id":"u6-l5","slug":"ordinal-numbers-dates","title":"Ordinal numbers & dates","titleUz":"Tartib sonlar va sanalar","goal":"Tartib sonlarni (first, second, third… twenty-first, thirty-first) to'g'ri aytasiz va yozasiz (1st, 2nd, 3rd), sanani o'qiysiz (the fifth of May), yillarni aytasiz (nineteen ninety-eight, twenty twenty-five) va on / in bilan ishlatasiz.","words":[{"en":"date","uz":"sana","ipa":"deɪt"},{"en":"calendar","uz":"taqvim, kalendar","ipa":"ˈkæl.ən.də"},{"en":"floor","uz":"qavat","ipa":"flɔː"},{"en":"celebrate","uz":"nishonlamoq","ipa":"ˈsel.ə.breɪt"},{"en":"public holiday","uz":"davlat bayrami, dam olish kuni","ipa":"ˌpʌb.lɪk ˈhɒl.ə.deɪ"},{"en":"anniversary","uz":"yillik, yubiley","ipa":"ˌæn.ɪˈvɜː.sər.i"},{"en":"wedding","uz":"to'y (nikoh to'yi)","ipa":"ˈwed.ɪŋ"},{"en":"century","uz":"asr","ipa":"ˈsen.tʃər.i"},{"en":"appointment","uz":"uchrashuv (oldindan belgilangan), qabul","ipa":"əˈpɔɪnt.mənt"},{"en":"the day after tomorrow","uz":"indinga","ipa":"ðə ˌdeɪ ˌɑːf.tə təˈmɒr.əʊ"}],"summary":["first, second, third — maxsus; qolganlari + -th. Imlo: fifth, eighth, ninth, twelfth, twentieth.","Murakkab sonlarda faqat oxirgisi: twenty-first (21st), thirty-second (32nd); lekin 11th, 12th, 13th.","Sana: yoziladi 5 May, o'qiladi the fifth of May yoki May the fifth.","Yillar: nineteen ninety-one, two thousand and seven, twenty twenty-five.","on + aniq sana (on the 1st of September), in + oy/yil/asr (in May, in 1991)."]},{"id":"u6-l12","slug":"saying-and-writing-dates","title":"Saying and writing dates","titleUz":"Sanalarni aytish va yozish: the 5th of May","goal":"Sanani yozma (5 May, 5th May, May 5th) va og'zaki (the fifth of May) to'g'ri ifodalaysiz, yilni aytasiz va Britaniya hamda Amerika yozuvini adashtirmaysiz.","words":[{"en":"deadline","uz":"oxirgi muddat","ipa":"ˈded.laɪn"},{"en":"exam","uz":"imtihon","ipa":"ɪɡˈzæm"},{"en":"invitation","uz":"taklifnoma","ipa":"ˌɪn.vɪˈteɪ.ʃən"},{"en":"schedule","uz":"jadval, reja","ipa":"ˈʃed.juːl"},{"en":"leap year","uz":"kabisa yili","ipa":"ˈliːp jɪə"},{"en":"date of birth","uz":"tug'ilgan sana","ipa":"ˌdeɪt əv ˈbɜːθ"}],"summary":["Yozuv: 5 May / 5th May (Britaniya), May 5th (Amerika). Aytilishi: the fifth of May.","Sanada tartib son ishlating, aniq sana oldidan on, oy va yil oldidan in.","03/04 Britaniyada 3-aprel, Amerikada 4-mart. Oyni so'z bilan yozish xavfsizroq.","Yangi so'zlar: deadline, exam, invitation, schedule, leap year, date of birth."]},{"id":"u6-l6","slug":"my-home","title":"My home","titleUz":"Mening uyim: xonalar va jihozlar","goal":"Uyingiz yoki kvartirangizni tasvirlaysiz: xonalar, jihozlar, qavat (I live in a flat on the fourth floor. There's a big sofa in the living room.). there is / there are, in / on va sanalmaydigan furniture ni to'g'ri ishlatasiz.","words":[{"en":"flat","uz":"kvartira","ipa":"flæt"},{"en":"balcony","uz":"balkon","ipa":"ˈbæl.kə.ni"},{"en":"wardrobe","uz":"kiyim javoni, shkaf","ipa":"ˈwɔː.drəʊb"},{"en":"curtain","uz":"parda","ipa":"ˈkɜː.tən"},{"en":"armchair","uz":"kreslo","ipa":"ˈɑːm.tʃeə"},{"en":"kettle","uz":"choynak (elektr)","ipa":"ˈket.əl"},{"en":"cooker","uz":"plita","ipa":"ˈkʊk.ə"},{"en":"mirror","uz":"oyna, ko'zgu","ipa":"ˈmɪr.ə"},{"en":"upstairs","uz":"yuqori qavatda, yuqoriga","ipa":"ʌpˈsteəz"},{"en":"furniture","uz":"mebel","ipa":"ˈfɜː.nɪ.tʃə"}],"summary":["house — hovli-uy, flat — kvartira, home — o'z uyim: at home, go home.","Xonalar in bilan (in the kitchen), lekin on the balcony, on the fourth floor.","Jihozlar: sofa, armchair, carpet, wardrobe, shelf (shelves), mirror, fridge, cooker, curtains.","furniture sanalmaydi: a lot of furniture, ❌ furnitures. cooker — plita, cook — oshpaz.","Tasvir: There is/are + nima + qayerda; upstairs / downstairs — predlogsiz."]},{"id":"u6-l7","slug":"in-town-asking-the-way","title":"In town: asking the way","titleUz":"Shaharda: yo'l so'rash va ko'rsatish","goal":"Shaharda muloyim yo'l so'raysiz (Excuse me, how do I get to…? Is there a pharmacy near here?) va yo'l ko'rsatasiz (Go straight on, take the second left, it's opposite the bank). Javobni tinglab tushunasiz.","words":[{"en":"pharmacy","uz":"dorixona","ipa":"ˈfɑː.mə.si"},{"en":"traffic lights","uz":"svetofor","ipa":"ˈtræf.ɪk laɪts"},{"en":"crossroads","uz":"chorraha","ipa":"ˈkrɒs.rəʊdz"},{"en":"corner","uz":"burchak, muyulish","ipa":"ˈkɔː.nə"},{"en":"roundabout","uz":"aylanma yo'l (halqa)","ipa":"ˈraʊnd.ə.baʊt"},{"en":"straight on","uz":"to'g'riga","ipa":"ˌstreɪt ˈɒn"},{"en":"turn","uz":"burilmoq","ipa":"tɜːn"},{"en":"cross","uz":"kesib o'tmoq","ipa":"krɒs"},{"en":"go past","uz":"yonidan o'tib ketmoq","ipa":"ɡəʊ ˈpɑːst"},{"en":"nearest","uz":"eng yaqin","ipa":"ˈnɪə.rɪst"}],"summary":["Savol: Excuse me, how do I get to…? / Is there a… near here? / Where's the nearest…?","Yo'l ko'rsatish (buyruq): Go straight on, turn left/right, take the second left, go past…, cross the road.","Joylashuv: on the left, opposite (❌ of), next to, between, on the corner, at the end of.","Masofa: It's not far. It's about ten minutes' walk.","Tushunmasangiz: Sorry, can you say that again, please? — va yo'lni qisqa takrorlab tekshiring."]},{"id":"u6-l10","slug":"lost-in-the-city-asking-the-way","title":"Lost in the city: asking the way","titleUz":"Shaharda adashdim: yo'l so'rash","goal":"Shaharda adashib qolsangiz, muloyim yo'l so'raysiz (Excuse me, how do I get to the station?) va javobni tushunasiz: Go straight on, turn left at the traffic lights.","words":[{"en":"lost","uz":"adashgan","ipa":"lɒst"},{"en":"opposite","uz":"qarshisida","ipa":"ˈɒp.ə.zɪt"},{"en":"block","uz":"kvartal","ipa":"blɒk"},{"en":"on foot","uz":"piyoda","ipa":"ɒn fʊt"},{"en":"square","uz":"maydon","ipa":"skweə"},{"en":"slowly","uz":"sekin","ipa":"ˈsləʊ.li"}],"summary":["So'rash: Excuse me, how do I get to…? Is there a … near here? Is it far?","Ko'rsatish: Go straight on. Turn left/right at the … Take the second left. It's opposite …","Tushunmasangiz: Can you say that again, please? Yangi so'zlar: lost, opposite, block, on foot, square, slowly."]},{"id":"u6-l14","slug":"listening-and-speaking-giving-directions","title":"Listening and speaking: giving directions","titleUz":"Tinglash va gapirish: yo'l ko'rsatish","goal":"Yo'l ko'rsatilganini tinglab tushunasiz va o'zingiz aniq yo'l ko'rsatasiz: Go straight on, turn left, it's next to the bank, opposite the pharmacy.","words":[{"en":"bridge","uz":"ko'prik","ipa":"brɪdʒ"},{"en":"entrance","uz":"kirish","ipa":"ˈen.trəns"},{"en":"exit","uz":"chiqish","ipa":"ˈek.sɪt"},{"en":"pavement","uz":"yo'lak, trotuar","ipa":"ˈpeɪv.mənt"},{"en":"tunnel","uz":"tunnel","ipa":"ˈtʌn.əl"},{"en":"at the end of","uz":"oxirida","ipa":"ət ði ˈend əv"}],"summary":["Yo'l ko'rsatish: Go straight on… Turn left/right at… Go past… Cross the bridge…","Joylashuv: next to, opposite, between, behind, in front of, at the end of. Yangi so'zlar: bridge, entrance, exit, pavement, tunnel.","Tushunmasangiz: Can you say that again, please?"]},{"id":"u6-l8","slug":"a-an-the-no-article","title":"a / an / the / no article","titleUz":"Artikllar: a / an / the yoki artiklsiz","goal":"Qachon a / an, qachon the, qachon artiklsiz gapirishni bilasiz: I saw a cat. The cat was black. I like cats. She's a doctor. The sun is hot. I go to work by bus. O'zbek tilida artikl yo'qligi sababli qilinadigan eng ko'p xatolardan qutulasiz.","words":[{"en":"the sun","uz":"quyosh","ipa":"ðə ˈsʌn"},{"en":"the moon","uz":"oy (osmondagi)","ipa":"ðə ˈmuːn"},{"en":"the sky","uz":"osmon","ipa":"ðə ˈskaɪ"},{"en":"the world","uz":"dunyo","ipa":"ðə ˈwɜːld"},{"en":"the internet","uz":"internet","ipa":"ði ˈɪn.tə.net"},{"en":"the city centre","uz":"shahar markazi","ipa":"ðə ˌsɪt.i ˈsen.tə"},{"en":"the same","uz":"bir xil, o'sha","ipa":"ðə ˈseɪm"},{"en":"the only","uz":"yagona","ipa":"ði ˈəʊn.li"},{"en":"by bus","uz":"avtobusda","ipa":"baɪ ˈbʌs"},{"en":"at work","uz":"ishda","ipa":"ət ˈwɜːk"}],"summary":["a / an — birinchi marta, \"bitta, qandaydir\"; kasb oldidan majburiy: I'm a student, She's an engineer.","the — ma'lum narsa (2-marta), yagona (the sun, the world), the biggest, the first, the same, shahardagi joylar (the station), cholg'ular.","Artiklsiz — umumiy ma'no (I like cats. Life is beautiful.), ismlar va ko'p davlatlar, tillar, sport, ovqatlar, by bus.","Iboralar: go to school / work / bed, at home, at work, go home — artiklsiz.","an — unli tovush oldidan: an hour, lekin a university."]},{"id":"u6-l13","slug":"the-or-no-article","title":"The or no article?","titleUz":"the yoki artiklsiz: aniq, yagona va umumiy narsalar","goal":"Gapda the kerakmi yoki artiklsizmi tez hal qilasiz: aniq va yagona narsa — the, umumiy ko'plik va sanalmaydigan ot — artiklsiz.","words":[{"en":"weather","uz":"ob-havo","ipa":"ˈweð.ə"},{"en":"news","uz":"yangiliklar","ipa":"njuːz"},{"en":"capital","uz":"poytaxt","ipa":"ˈkæp.ɪ.təl"},{"en":"airport","uz":"aeroport","ipa":"ˈeə.pɔːt"},{"en":"radio","uz":"radio","ipa":"ˈreɪ.di.əʊ"},{"en":"countryside","uz":"shahar tashqarisi, qishloq joy","ipa":"ˈkʌn.tri.saɪd"}],"summary":["Aniq, ikkalamiz biladigan narsa — the: the music in this café.","Umumiy fikrda ko'plik va sanalmaydigan ot artiklsiz: Dogs are friendly. Water is important.","Yagona narsalar: the weather, the news, the capital, the radio, the airport."]},{"id":"u6-l15","slug":"reading-and-writing-my-new-neighbourhood","title":"Reading and writing: my new neighbourhood","titleUz":"O'qish va yozish: yangi mahallam","goal":"Joy haqidagi qisqa matnlarni o'qib tushunasiz va o'z mahallangiz haqida 4–5 gapli tavsif yozasiz: I live in a quiet area. There's a park next to my house.","words":[{"en":"neighbourhood","uz":"mahalla","ipa":"ˈneɪ.bə.hʊd"},{"en":"crowded","uz":"gavjum, odam ko'p","ipa":"ˈkraʊ.dɪd"},{"en":"lively","uz":"jonli, quvnoq","ipa":"ˈlaɪv.li"},{"en":"local","uz":"mahalliy","ipa":"ˈləʊ.kəl"},{"en":"area","uz":"hudud, tuman","ipa":"ˈeə.ri.ə"},{"en":"playground","uz":"o'yin maydonchasi","ipa":"ˈpleɪ.ɡraʊnd"}],"summary":["Tavsif tartibi: qayerda yashaysiz → nima bor → odamlar → sizga yoqadimi?","There is — birlik, There are — ko'plik; sabab uchun because it's quiet.","Yangi so'zlar: neighbourhood, crowded, lively, local, area, playground."]},{"id":"u6-l11","slug":"people-and-places-final-review","title":"People and places: final review","titleUz":"Odamlar va joylar: yakuniy takror","goal":"Bo'lim bo'yicha yakuniy takror: tanishuv, odamlarni tasvirlash, xarakter, mine / yours / Whose?, tartib sonlar va sanalar, uy, yo'l so'rash va a / an / the.","words":[{"en":"describe","uz":"tasvirlamoq","ipa":"dɪˈskraɪb"},{"en":"twin","uz":"egizak","ipa":"twɪn"},{"en":"tidy","uz":"ozoda, tartibli","ipa":"ˈtaɪ.di"},{"en":"honest","uz":"halol, rostgo'y","ipa":"ˈɒn.ɪst"},{"en":"cheerful","uz":"quvnoq, xushchaqchaq","ipa":"ˈtʃɪə.fəl"}],"summary":["Tanishuv va tasvir: What does she look like? — She has…; xarakter — She's quite shy.","Egalik: my → mine, your → yours, savol: Whose…? Sana: the third of May.","Yo'l: How do I get to…? Go straight on, turn left. Artikl: a / an / the yoki hech narsa."]}]},{"id":"u7","n":7,"title":"Work & Free Time","titleUz":"Ish va bo'sh vaqt: yoqtirish, rejalar, takliflar","description":"Kasblar, like / love / hate + -ing, ravishlar, play / go / do, rejalar, would like, takliflar, soat va jadval.","canDo":["Nimani yoqtirishimni like/love/hate + -ing bilan aytaman","Sport va hobbilar haqida gapiraman","Rejalarimni va takliflarni (would like) bildiraman","How often / How long savollarini beraman"],"lessons":[{"id":"u7-l1","slug":"jobs-workplaces","title":"Jobs & workplaces","titleUz":"Kasblar va ish joylari","goal":"Kasb haqida so'raysiz va javob berasiz: What do you do? — I'm a chef. I work in a restaurant. Kasblar nomini, ish joylari bilan in / at / on / for predloglarini to'g'ri ishlatasiz va ishingiz haqida 4–5 gap aytib berasiz.","words":[{"en":"job","uz":"ish, kasb","ipa":"dʒɒb"},{"en":"chef","uz":"oshpaz (restoranda)","ipa":"ʃef"},{"en":"waiter","uz":"ofitsiant","ipa":"ˈweɪ.tə"},{"en":"shop assistant","uz":"do'kon sotuvchisi","ipa":"ˈʃɒp əˌsɪs.tənt"},{"en":"receptionist","uz":"administrator, qabulxona xodimi","ipa":"rɪˈsep.ʃən.ɪst"},{"en":"mechanic","uz":"mexanik, avtousta","ipa":"mɪˈkæn.ɪk"},{"en":"pilot","uz":"uchuvchi","ipa":"ˈpaɪ.lət"},{"en":"factory","uz":"zavod, fabrika","ipa":"ˈfæk.tər.i"},{"en":"uniform","uz":"forma, maxsus kiyim","ipa":"ˈjuː.nɪ.fɔːm"},{"en":"earn","uz":"pul topmoq, ishlab topmoq","ipa":"ɜːn"}],"summary":["Kasb haqida savol: What do you do? / What does she do? — What are you doing? emas!","Birlikdagi kasb oldida a / an shart: I'm a chef, she's an engineer.","Ish joyi: in an office / a hospital / a factory, at the airport / a school, on a farm, for + kompaniya, as + kasb.","job sanaladi (a new job), work sanalmaydi (a lot of work, go to work).","he / she bilan -s: She works, he earns, he wears a uniform; savolda — does … work?"]},{"id":"u7-l2","slug":"like-love-hate-ing","title":"like, love, hate + -ing","titleUz":"Yoqtirish: like, love, hate + -ing","goal":"Nimani yoqtirishingiz va yoqtirmasligingizni aniq darajada aytasiz: I love cooking. I don't mind ironing. I can't stand getting up early. Fe'lga -ing qo'shish imlosini va bo'sh vaqt haqidagi savollarni o'rganasiz.","words":[{"en":"enjoy","uz":"zavq olmoq, yoqtirmoq","ipa":"ɪnˈdʒɔɪ"},{"en":"don't mind","uz":"qarshi emasman, mayli","ipa":"dəʊnt ˈmaɪnd"},{"en":"can't stand","uz":"chiday olmaslik, umuman yoqtirmaslik","ipa":"kɑːnt ˈstænd"},{"en":"free time","uz":"bo'sh vaqt","ipa":"ˌfriː ˈtaɪm"},{"en":"shopping","uz":"xarid qilish","ipa":"ˈʃɒp.ɪŋ"},{"en":"gardening","uz":"bog'dorchilik","ipa":"ˈɡɑː.dən.ɪŋ"},{"en":"fishing","uz":"baliq ovi","ipa":"ˈfɪʃ.ɪŋ"},{"en":"chat","uz":"suhbatlashmoq, gaplashmoq","ipa":"tʃæt"},{"en":"relax","uz":"dam olmoq, hordiq chiqarmoq","ipa":"rɪˈlæks"},{"en":"take photos","uz":"suratga olmoq","ipa":"teɪk ˈfəʊ.təʊz"}],"summary":["Harakatni yoqtirish: like / love / enjoy / hate + fe'l-ing — I love cooking.","Shkala: love > really like / enjoy > like > don't mind > don't like > hate > can't stand.","enjoy, don't mind, can't stand dan keyin faqat -ing (❌ enjoy to).","Imlo: dance → dancing (e tushadi), swim → swimming (ikkilanadi), lie → lying.","❌ I am like… — like fe'l: I like…, She likes…, I don't like…, Does he like…?"]},{"id":"u7-l3","slug":"adverbs-quickly-well-hard","title":"Adverbs: quickly, well, hard","titleUz":"Ravishlar: quickly, well, hard","goal":"Ish qanday bajarilishini aytasiz: She works quickly. He speaks English well. They work hard. Sifatdan ravish yasashni (-ly), noto'g'ri ravishlarni (well, fast, hard, early, late) va ravishning gapdagi o'rnini o'rganasiz.","words":[{"en":"quickly","uz":"tez, tezda","ipa":"ˈkwɪk.li"},{"en":"slowly","uz":"sekin","ipa":"ˈsləʊ.li"},{"en":"carefully","uz":"ehtiyotkorlik bilan, diqqat bilan","ipa":"ˈkeə.fəl.i"},{"en":"quietly","uz":"jimgina, past ovozda","ipa":"ˈkwaɪ.ət.li"},{"en":"loudly","uz":"baland ovozda","ipa":"ˈlaʊd.li"},{"en":"badly","uz":"yomon","ipa":"ˈbæd.li"},{"en":"easily","uz":"osongina, oson","ipa":"ˈiː.zɪ.li"},{"en":"well","uz":"yaxshi (qanday qilib)","ipa":"wel"},{"en":"hard","uz":"qattiq, astoydil (ishlamoq)","ipa":"hɑːd"},{"en":"early","uz":"erta","ipa":"ˈɜː.li"}],"summary":["Sifat otni tasvirlaydi (a quick worker), ravish fe'lni (works quickly).","Ravish = sifat + -ly: slowly, carefully, easily, gently.","Noto'g'ri ravishlar: good → well, fast → fast, hard → hard, early, late o'zgarmaydi. hardly = deyarli ... emas!","Tartib: fe'l + ob'ekt + ravish — She speaks English well. (❌ speaks well English)","be dan keyin sifat: Your English is good. — fe'ldan keyin ravish: You speak English well."]},{"id":"u7-l4","slug":"sports-hobbies-play-go-do","title":"Sports & hobbies: play, go, do","titleUz":"Sport va hobbi: play, go, do","goal":"Sport va hobbi haqida to'g'ri fe'l bilan gapirasiz: play tennis, go swimming, do yoga. Musiqa asboblari bilan the, go to the gym va go swimming farqini, sport joylari va match, win so'zlarini o'rganasiz.","words":[{"en":"basketball","uz":"basketbol","ipa":"ˈbɑː.skɪt.bɔːl"},{"en":"volleyball","uz":"voleybol","ipa":"ˈvɒl.i.bɔːl"},{"en":"tennis","uz":"tennis","ipa":"ˈten.ɪs"},{"en":"cycling","uz":"velosipedda yurish","ipa":"ˈsaɪ.klɪŋ"},{"en":"hiking","uz":"tog'da piyoda sayohat","ipa":"ˈhaɪ.kɪŋ"},{"en":"yoga","uz":"yoga","ipa":"ˈjəʊ.ɡə"},{"en":"karate","uz":"karate","ipa":"kəˈrɑː.ti"},{"en":"gym","uz":"sport zal","ipa":"dʒɪm"},{"en":"match","uz":"o'yin, uchrashuv (sportda)","ipa":"mætʃ"},{"en":"win – won","uz":"yutmoq, g'olib bo'lmoq","ipa":"wɪn – wʌn"}],"summary":["play — to'p bilan va raqib bilan o'yinlar: play tennis, chess, volleyball.","go + -ing — go swimming, hiking, cycling, fishing (to siz!).","do — to'psiz va kurash turlari: do yoga, karate, judo, gymnastics, exercise.","Asbob oldida the: play the guitar; sport oldida yo'q: play football. Joy: go to the gym / pool.","win – won, lose – lost: We won the match."]},{"id":"u7-l9","slug":"at-a-party-hobbies-and-free-time","title":"At a party: hobbies and free time","titleUz":"Ziyofatda: hobbi va bo'sh vaqt","goal":"Ziyofatda yangi odam bilan tanishib, kasbi va hobbisi haqida suhbatlashasiz: What do you do? What do you like doing in your free time? How often do you go swimming? Javobda like / love / hate + -ing ishlatasiz.","words":[{"en":"cake","uz":"tort, pirog","ipa":"keɪk"},{"en":"present","uz":"sovg‘a","ipa":"ˈprez.ənt"},{"en":"balloon","uz":"shar","ipa":"bəˈluːn"},{"en":"popular","uz":"mashhur, ommabop","ipa":"ˈpɒp.jə.lər"},{"en":"favourite","uz":"sevimli","ipa":"ˈfeɪ.vər.ɪt"}],"summary":["Kasb: What do you do? — I'm a nurse. Hobbi: What do you like doing?","like / love / hate / enjoy + fe'l-ing: I love playing football.","Tez-tezlik: How often…? — Twice a week. Savolni qaytaring: And you?","Yangi so'zlar: favourite, cake, present, balloon, popular."]},{"id":"u7-l5","slug":"plans-present-continuous-for-future","title":"Plans: Present Continuous for future","titleUz":"Rejalar: Present Continuous kelasi zamon uchun","goal":"Aniq kelishilgan rejalaringiz haqida gapirasiz: I'm meeting Aziz tomorrow. We're flying to Istanbul on Friday. Savol bera olasiz: What are you doing tonight? Are you working on Saturday? va kundaligingizdagi haftani aytib berasiz.","words":[{"en":"tonight","uz":"bugun kechqurun","ipa":"təˈnaɪt"},{"en":"this evening","uz":"bugun kechqurun (shu oqshom)","ipa":"ðɪs ˈiːv.nɪŋ"},{"en":"available","uz":"bo'sh, vaqti bor","ipa":"əˈveɪ.lə.bəl"},{"en":"day off","uz":"dam olish kuni (ishdan ozod kun)","ipa":"ˌdeɪ ˈɒf"},{"en":"meeting","uz":"majlis, uchrashuv (ishda)","ipa":"ˈmiː.tɪŋ"},{"en":"dentist","uz":"tish shifokori","ipa":"ˈden.tɪst"},{"en":"diary","uz":"kundalik, rejalar daftari","ipa":"ˈdaɪə.ri"},{"en":"free","uz":"bo'sh (band emas)","ipa":"friː"},{"en":"nervous","uz":"hayajonlangan, xavotirli","ipa":"ˈnɜː.vəs"},{"en":"pick up","uz":"(mashinada) olib ketmoq, kutib olmoq","ipa":"ˌpɪk ˈʌp"}],"summary":["Present Continuous (am / is / are + -ing) + kelajak vaqti = kelishilgan reja: I'm meeting Aziz tomorrow.","Shaxsiy rejalar uchun odatda Present Simple emas: ❌ I go to Samarkand tomorrow. ✅ I'm going…","tonight, this evening, tomorrow, next week, the day after tomorrow — predlogsiz; on Friday, at six, in July.","Savollar: What are you doing tonight? Are you doing anything on Saturday? — No, I'm free. / Yes, I'm working."]},{"id":"u7-l13","slug":"now-or-plan-present-continuous","title":"Now or plan? Present Continuous","titleUz":"Hozir yoki reja? Present Continuous farqi","goal":"Present Continuous gapi hozir haqidami yoki reja haqidami — buni vaqt so'zlariga qarab aniqlaysiz: I'm working now. / I'm meeting Ali tomorrow.","words":[{"en":"right now","uz":"aynan hozir","ipa":"ˌraɪt ˈnaʊ"},{"en":"at the moment","uz":"hozir, shu paytda","ipa":"ət ðə ˈməʊ.mənt"},{"en":"next week","uz":"kelasi hafta","ipa":"nekst wiːk"},{"en":"next month","uz":"kelasi oy","ipa":"nekst mʌnθ"},{"en":"this weekend","uz":"bu hafta oxiri","ipa":"ðɪs ˌwiːkˈend"},{"en":"later","uz":"keyinroq","ipa":"ˈleɪ.tər"}],"summary":["Shakl bir xil: am / is / are + fe'l-ing.","Hozir: now, right now, at the moment. Reja: tomorrow, tonight, next week, this weekend.","Odat uchun Present Simple: I play tennis every Sunday.","Yangi so'zlar: right now, at the moment, next week, next month, this weekend, later."]},{"id":"u7-l6","slug":"would-like-invitations","title":"would like & invitations","titleUz":"would like, taklif qilish va javob berish","goal":"Odobli istak bildirasiz va taklif qilasiz: I'd like a coffee. Would you like to come to my party? Turli taklif iboralarini (How about…? Why don't we…? Let's…) ishlatasiz, taklifni qabul qilasiz (I'd love to!) yoki odobli rad etasiz (I'm afraid I can't.).","words":[{"en":"would like","uz":"xohlamoq (odobli)","ipa":"wʊd ˈlaɪk"},{"en":"invite","uz":"taklif qilmoq","ipa":"ɪnˈvaɪt"},{"en":"invitation","uz":"taklif, taklifnoma","ipa":"ˌɪn.vɪˈteɪ.ʃən"},{"en":"I'd love to","uz":"jon deb, juda xohlardim","ipa":"aɪd ˈlʌv tuː"},{"en":"sounds great","uz":"zo'r, ajoyib eshitiladi","ipa":"saʊndz ˈɡreɪt"},{"en":"How about…?","uz":"… -sak-chi?","ipa":"haʊ əˈbaʊt"},{"en":"Why don't we…?","uz":"Nega … -maylik? (taklif)","ipa":"waɪ dəʊnt wiː"},{"en":"Let's…","uz":"Keling, … -aylik","ipa":"lets"},{"en":"another time","uz":"boshqa safar","ipa":"əˈnʌð.ə taɪm"},{"en":"I'm afraid…","uz":"afsuski…","ipa":"aɪm əˈfreɪd"}],"summary":["would like = odobli want: I'd like + ot (a coffee), I'd like + to + fe'l (to book a table); -s yo'q.","Do you like…? — umuman (Yes, I do.); Would you like…? — taklif (Yes, please. / I'd love to!).","Taklif: Would you like to…? / Do you want to…? / How about + -ing? / Why don't we + fe'l? / Let's + fe'l.","Qabul: I'd love to! That sounds great! Rad: I'm afraid I can't. I'm working… / Maybe another time."]},{"id":"u7-l12","slug":"invitations-accepting-and-declining","title":"Invitations: accepting and declining","titleUz":"Takliflar: qabul qilish va muloyim rad etish","goal":"Taklifni ingliz tilida odobli qabul qilasiz yoki rad etasiz: Would you like to…? Let's… Shall we…? Why don't we…? — I'd love to! / Sorry, I can't, but…","words":[{"en":"accept","uz":"qabul qilmoq","ipa":"əkˈsept"},{"en":"decline","uz":"rad etmoq","ipa":"dɪˈklaɪn"},{"en":"polite","uz":"odobli","ipa":"pəˈlaɪt"},{"en":"reason","uz":"sabab","ipa":"ˈriː.zən"},{"en":"perhaps","uz":"balki","ipa":"pəˈhæps"},{"en":"join","uz":"qo'shilmoq","ipa":"dʒɔɪn"}],"summary":["Taklif: Would you like to…? / Let's… / Shall we…? / Why don't we…?","Qabul: I'd love to! Good idea! Yes, let's!","Rad: Sorry, I can't. + sabab + Maybe another time?","Yangi so'zlar: accept, decline, polite, reason, perhaps, join."]},{"id":"u7-l10","slug":"making-plans-with-a-friend","title":"Making plans with a friend","titleUz":"Do'st bilan reja tuzish","goal":"Do'stingizni taklif qilasiz, taklifni qabul qilasiz yoki muloyim rad etasiz va vaqtni kelishasiz: Would you like to go to the cinema? I'm meeting Aziz at six. Sorry, I can't.","words":[{"en":"plan","uz":"reja","ipa":"plæn"},{"en":"popcorn","uz":"popkorn","ipa":"ˈpɒp.kɔːn"},{"en":"seat","uz":"o‘rindiq, joy","ipa":"siːt"},{"en":"screen","uz":"ekran","ipa":"skriːn"},{"en":"ticket","uz":"chipta","ipa":"ˈtɪk.ɪt"}],"summary":["Reja: am / is / are + fe'l-ing — I'm meeting Aziz at six.","Taklif: Would you like to…? Qabul: I'd love to! Rad: I'm afraid I can't.","Vaqt: Let's meet at half past six. How about Sunday?","Yangi so'zlar: plan, ticket, popcorn, seat, screen."]},{"id":"u7-l7","slug":"time-timetables","title":"Time & timetables","titleUz":"Soat, jadval: from… to, until, before, after","goal":"Har qanday vaqtni aytasiz (ten to nine, twenty-five past six, 18:30), jadvalni o'qiysiz va so'raysiz (What time does the train leave?), ish va dam olish vaqtini from… to, until, before, after bilan aniq ifodalaysiz.","words":[{"en":"timetable","uz":"jadval (poyezd, dars)","ipa":"ˈtaɪmˌteɪ.bəl"},{"en":"a.m.","uz":"ertalab, tushgacha (00:00–12:00)","ipa":"ˌeɪˈem"},{"en":"p.m.","uz":"tushdan keyin, kechqurun (12:00–24:00)","ipa":"ˌpiːˈem"},{"en":"midday","uz":"tush, soat 12","ipa":"ˌmɪdˈdeɪ"},{"en":"midnight","uz":"yarim tun","ipa":"ˈmɪd.naɪt"},{"en":"until","uz":"…gacha","ipa":"ənˈtɪl"},{"en":"before","uz":"…dan oldin","ipa":"bɪˈfɔː"},{"en":"after","uz":"…dan keyin","ipa":"ˈɑːf.tə"},{"en":"leave","uz":"jo'nab ketmoq, chiqib ketmoq","ipa":"liːv"},{"en":"break","uz":"tanaffus","ipa":"breɪk"}],"summary":["past — o'tdi (ten past eight = 8:10), to — keyingi soatga kam (ten to nine = 8:50). Oddiy usul: eight fifty.","a.m. — tushgacha, p.m. — tushdan keyin; midday — 12:00, midnight — 00:00.","Jadvallar — Present Simple: The train leaves at 7:28. What time does it arrive?","from … to / until, yolg'iz until (…gacha); before / after + ot / -ing: after work, before going to bed."]},{"id":"u7-l8","slug":"questions-how-often-how-long","title":"Questions: How often? How long?…","titleUz":"Savollar: How often, How long, How far…","goal":"How + sifat/ravish savollarini tuzasiz va javob berasiz: How often do you go to the gym? — Three times a week. How long does it take? — It takes 20 minutes. How far is it? — It's 5 kilometres away.","words":[{"en":"how long","uz":"qancha vaqt","ipa":"haʊ ˈlɒŋ"},{"en":"how far","uz":"qancha uzoq (masofa)","ipa":"haʊ ˈfɑː"},{"en":"it takes","uz":"(vaqt) oladi, ketadi","ipa":"ɪt ˈteɪks"},{"en":"kilometre","uz":"kilometr","ipa":"ˈkɪl.əˌmiː.tə"},{"en":"hour","uz":"soat (60 daqiqa)","ipa":"ˈaʊ.ə"},{"en":"journey","uz":"yo'l, safar (bir joydan boshqasiga)","ipa":"ˈdʒɜː.ni"},{"en":"on foot","uz":"piyoda","ipa":"ɒn ˈfʊt"},{"en":"three times","uz":"uch marta","ipa":"θriː ˈtaɪmz"},{"en":"how tall","uz":"bo'yi qancha","ipa":"haʊ ˈtɔːl"},{"en":"away","uz":"narida, uzoqlikda","ipa":"əˈweɪ"}],"summary":["How + sifat/ravish + do/does/is…?: How often, How long, How far, How tall, How fast, How well.","How often? — once / twice / three times a week / month / year, gap oxirida.","How long? — vaqt: It takes (me) + vaqt + to + fe'l; It's two hours long; for a week.","How far? — masofa: It's 5 kilometres away. ❌ How far is? — it shart."]},{"id":"u7-l14","slug":"listening-and-speaking-my-job-and-my-free-time","title":"Listening and speaking: my job and my free time","titleUz":"Tinglash va gapirish: ishim va bo'sh vaqtim","goal":"Ikki suhbatni tinglab, kasb va bo'sh vaqt haqidagi asosiy ma'lumotni topasiz va o'zingiz haqingizda ish va hobbilaringizni aytib berasiz.","words":[{"en":"manager","uz":"menejer, boshliq","ipa":"ˈmæn.ɪ.dʒər"},{"en":"perfect","uz":"ajoyib, juda yaxshi","ipa":"ˈpɜː.fekt"},{"en":"friendly","uz":"mehribon, samimiy","ipa":"ˈfrend.li"},{"en":"spare time","uz":"bo'sh vaqt","ipa":"speə taɪm"},{"en":"part-time","uz":"yarim kunlik","ipa":"ˌpɑːt ˈtaɪm"}],"summary":["Tinglaganda avval kim, qaysi kasb, hobbi nima ekanini toping.","Kasb: I'm an engineer. Hobbi: I love cycling. Tez-tezlik: twice a week.","Taklif va javob: Shall we…? — I'd love to, but I can't.","Yangi so'zlar: manager, friendly, spare time, part-time, perfect."]},{"id":"u7-l15","slug":"reading-and-writing-a-profile-of-me","title":"Reading and writing: a profile of me","titleUz":"O'qish va yozish: o'zim haqimda profil","goal":"Odamlarning ishi va hobbisi haqidagi qisqa profillarni o'qib tushunasiz va o'zingiz haqingizda 5–6 gapdan iborat profil yozasiz.","words":[{"en":"profile","uz":"profil, qisqa tavsif","ipa":"ˈprəʊ.faɪl"},{"en":"company","uz":"kompaniya","ipa":"ˈkʌm.pə.ni"},{"en":"photography","uz":"suratga olish","ipa":"fəˈtɒɡ.rə.fi"},{"en":"both","uz":"ikkalasi ham","ipa":"bəʊθ"},{"en":"full-time","uz":"to'liq kunlik","ipa":"ˌfʊl ˈtaɪm"},{"en":"bookshop","uz":"kitob do'koni","ipa":"ˈbʊk.ʃɒp"}],"summary":["Profil tuzilishi: ism va kasb → ish joyi → hobbi → reja.","also va sometimes odatda fe'ldan oldin: I also work. I sometimes swim.","Hobbi: like / love + fe'l-ing. Reja: I'm + fe'l-ing + vaqt.","Yangi so'zlar: profile, bookshop, both, company, photography, full-time."]},{"id":"u7-l11","slug":"work-and-free-time-final-review","title":"Work and free time: final review","titleUz":"Ish va bo'sh vaqt: yakuniy takror","goal":"7-bo'limni takrorlaysiz: kasblar, like + -ing, ravishlar, play / go / do, rejalar, would like, soat va jadval, How often / How long. Hammasini bitta matnda ko'rasiz.","words":[{"en":"colleague","uz":"hamkasb","ipa":"ˈkɒl.iːɡ"},{"en":"busy","uz":"band","ipa":"ˈbɪz.i"},{"en":"enough","uz":"yetarli","ipa":"ɪˈnʌf"},{"en":"finish","uz":"tugatmoq, tugamoq","ipa":"ˈfɪn.ɪʃ"}],"summary":["like / love / hate / enjoy + -ing; ravish fe'ldan keyin: works hard, speaks well.","play jamoa o'yini, go + -ing, do yakka mashq; reja — am / is / are + -ing.","Would you like to…? — I'd love to. / I'm afraid I can't.","How often…? — twice a week. How long…? — two hours. Vaqt: from… to, until, before, after."]}]},{"id":"u8","n":8,"title":"Food & Shopping","titleUz":"Ovqat va xarid: miqdor, narx, buyurtma","description":"Ovqat, idishlar (a cup of…), a few / a little, narx va pul, kafeda buyurtma, kiyim do'koni, retsept, should, qiyoslash.","canDo":["Kafe va do'konda buyurtma beraman","Miqdorni (a lot of, a little, a few) to'g'ri ishlataman","Narx va pulni so'rayman va aytaman","Retsept va maslahat (should) beraman"],"lessons":[{"id":"u8-l1","slug":"food-containers-a-cup-of","title":"Food & containers: a cup of…","titleUz":"Ovqat va o'lchovlar: a cup of, a bottle of…","goal":"Sanalmaydigan ovqat va ichimliklarni idish yoki bo'lak bilan aytasiz: a cup of tea, a bowl of soup, a loaf of bread, a slice of cake, a bunch of grapes — va ko'plikda ham to'g'ri ishlatasiz: two cartons of milk.","words":[{"en":"a bowl of","uz":"bir kosa …","ipa":"ə ˈbəʊl əv"},{"en":"a plate of","uz":"bir tarelka (likopcha) …","ipa":"ə ˈpleɪt əv"},{"en":"a jar of","uz":"bir (shisha) banka …","ipa":"ə ˈdʒɑː əv"},{"en":"a can of","uz":"bir (temir) banka …","ipa":"ə ˈkæn əv"},{"en":"a carton of","uz":"bir karton quti …","ipa":"ə ˈkɑː.tən əv"},{"en":"a loaf of","uz":"bir buxanka (butun non)","ipa":"ə ˈləʊf əv"},{"en":"a slice of","uz":"bir tilim, yupqa bo'lak …","ipa":"ə ˈslaɪs əv"},{"en":"a bar of","uz":"bir plitka …","ipa":"ə ˈbɑː əv"},{"en":"a bag of","uz":"bir xalta / paket …","ipa":"ə ˈbæɡ əv"},{"en":"a bunch of","uz":"bir shingil / bosh / dasta …","ipa":"ə ˈbʌntʃ əv"}],"summary":["Sanalmaydigan ovqat uchun: a / two + idish + of + ovqat — a cup of tea, a bowl of soup.","Ko'plik -s idishga qo'shiladi: two cups of tea, two loaves of bread (loaf → loaves).","Idishlar: cup (issiq), glass (sovuq), bowl (kosa), plate (tarelka), bottle, can, jar, carton, bag, packet, box.","Bo'laklar: a loaf / slice / piece of bread, a bar of chocolate, a bunch of grapes.","Talaffuz: of kuchsiz — \"əv\": a cup of tea = \"ə kapəv ti:\"."]},{"id":"u8-l2","slug":"a-lot-of-a-few-a-little-no","title":"a lot of, a few, a little, no","titleUz":"Miqdor: a lot of, a few, a little, no","goal":"Miqdorni aniq aytasiz: a lot of (ko'p), a few / a little (bir nechta / ozgina), not many / not much (ko'p emas) va no (umuman yo'q) — qaysi biri sanaladigan, qaysi biri sanalmaydigan ot bilan kelishini adashtirmaysiz.","words":[{"en":"onion","uz":"piyoz","ipa":"ˈʌn.jən"},{"en":"carrot","uz":"sabzi","ipa":"ˈkær.ət"},{"en":"potato","uz":"kartoshka","ipa":"pəˈteɪ.təʊ"},{"en":"tomato","uz":"pomidor","ipa":"təˈmɑː.təʊ"},{"en":"nuts","uz":"yong'oq (har xil)","ipa":"nʌts"},{"en":"pepper","uz":"murch; qalampir","ipa":"ˈpep.ə"},{"en":"cupboard","uz":"shkaf (oshxona javoni)","ipa":"ˈkʌb.əd"},{"en":"empty","uz":"bo'sh","ipa":"ˈemp.ti"},{"en":"enough","uz":"yetarli","ipa":"ɪˈnʌf"},{"en":"only","uz":"faqat, bor-yo'g'i","ipa":"ˈəʊn.li"}],"summary":["a lot of / lots of — ko'p, ikkala tur bilan: a lot of eggs, a lot of milk.","a few + sanaladigan ko'plik (a few eggs), a little + sanalmaydigan (a little milk, a little time).","not many (sanaladigan) / not much (sanalmaydigan) — ko'p emas.","no + ot = not any: There's no milk. Bitta gapda bitta inkor — There isn't no… ❌."]},{"id":"u8-l12","slug":"how-much-how-many-food-questions","title":"How much? How many? Food questions","titleUz":"How much? How many? Ovqat haqida savollar","goal":"Ovqat haqida miqdor savollarini berasiz: How many eggs…? / How much flour…? — va qisqa javob qaytarasiz: A lot. A few. A little. Not many. Not much. None.","words":[{"en":"flour","uz":"un","ipa":"ˈflaʊ.ər"},{"en":"butter","uz":"sariyog'","ipa":"ˈbʌt.ər"},{"en":"cheese","uz":"pishloq","ipa":"tʃiːz"},{"en":"yoghurt","uz":"qatiq, yogurt","ipa":"ˈjɒɡ.ət"},{"en":"oil","uz":"yog' (o'simlik yog'i)","ipa":"ɔɪl"},{"en":"lemon","uz":"limon","ipa":"ˈlem.ən"},{"en":"honey","uz":"asal","ipa":"ˈhʌn.i"}],"summary":["Sanaladigan ko'plik ot bilan How many: How many eggs…?","Sanalmaydigan ot bilan How much: How much flour…?","Qisqa javoblar: a lot, a few / a little, not many / not much, none.","How much is…? — narx; How much milk is there? — miqdor.","Yangi so'zlar: flour, butter, cheese, yoghurt, oil, lemon, honey."]},{"id":"u8-l3","slug":"money-prices","title":"Money & prices","titleUz":"Pul, narx va How much?","goal":"Narxni so'raysiz va aytasiz: How much is this? / How much are these? / How much does it cost? Katta summalarni (fifteen thousand soums, £3.50) to'g'ri o'qiysiz va to'lov iboralarini ishlatasiz: pay by card, pay in cash, change, receipt.","words":[{"en":"cost","uz":"turmoq (narxi …)","ipa":"kɒst"},{"en":"pay","uz":"to'lamoq","ipa":"peɪ"},{"en":"cash","uz":"naqd pul","ipa":"kæʃ"},{"en":"card","uz":"(bank) karta","ipa":"kɑːd"},{"en":"change","uz":"qaytim; mayda pul","ipa":"tʃeɪndʒ"},{"en":"receipt","uz":"chek","ipa":"rɪˈsiːt"},{"en":"discount","uz":"chegirma","ipa":"ˈdɪs.kaʊnt"},{"en":"coin","uz":"tanga","ipa":"kɔɪn"},{"en":"note","uz":"qog'oz pul (kupyura)","ipa":"nəʊt"},{"en":"thousand","uz":"ming","ipa":"ˈθaʊ.zənd"}],"summary":["Birlik: How much is it? / How much does it cost? — It costs…; ko'plik: How much are they? / do they cost?","hundred, thousand son bilan -s olmaydi: fifteen thousand soums; £3.50 = three pounds fifty.","To'lov: pay by card, pay in cash, pay for something; change = qaytim, receipt = chek (\"risi:t\").","Savdolashish: It's a bit expensive. Can you give me a discount?"]},{"id":"u8-l9","slug":"at-the-market-quantities-and-prices","title":"At the market: quantities and prices","titleUz":"Bozorda: miqdor va narx","goal":"Bozorda kerakli miqdorni aytasiz (a kilo of apples, a few tomatoes, a little cheese) va narxni so'raysiz: How much is it? / How much are they?","words":[{"en":"kilo","uz":"kilogramm","ipa":"ˈkiː.ləʊ"},{"en":"price","uz":"narx","ipa":"praɪs"},{"en":"stall","uz":"peshtaxta, rasta","ipa":"stɔːl"},{"en":"weigh","uz":"tortmoq, og'irligini o'lchamoq","ipa":"weɪ"}],"summary":["Miqdor: a kilo of…, a few + sanaladigan, a little + sanalmaydigan.","Narx: How much is it? (birlik), How much are they? (ko'plik).","Yangi so'zlar: kilo, price, stall, weigh."]},{"id":"u8-l4","slug":"at-the-cafe","title":"At the café","titleUz":"Kafeda: buyurtma berish","goal":"Kafeda xushmuomala buyurtma berasiz (I'd like…, Could I have…?, I'll have…), ofitsiantning savollarini tushunib javob berasiz (Are you ready to order? Eat in or take away? Anything else?) va hisobni so'raysiz: Can we have the bill, please?","words":[{"en":"menu","uz":"menyu","ipa":"ˈmen.juː"},{"en":"starter","uz":"birinchi (boshlang'ich) taom","ipa":"ˈstɑː.tə"},{"en":"order","uz":"buyurtma bermoq; buyurtma","ipa":"ˈɔː.də"},{"en":"bill","uz":"hisob (to'lov qog'ozi)","ipa":"bɪl"},{"en":"main course","uz":"asosiy taom","ipa":"ˌmeɪn ˈkɔːs"},{"en":"dessert","uz":"shirinlik (ovqatdan keyin)","ipa":"dɪˈzɜːt"},{"en":"take away","uz":"olib ketish uchun","ipa":"ˌteɪk əˈweɪ"},{"en":"sparkling","uz":"gazli (suv)","ipa":"ˈspɑː.klɪŋ"},{"en":"tip","uz":"choychaqa","ipa":"tɪp"},{"en":"delicious","uz":"juda mazali","ipa":"dɪˈlɪʃ.əs"}],"summary":["Buyurtma: I'd like…, please. / Could I have…? / I'll have… — Give me… qo'pol eshitiladi.","Ofitsiant savollari: Are you ready to order? Anything else? Still or sparkling? Eat in or take away?","Kafeda ichimliklar sanaladi: two coffees, three waters (= cups / glasses of…).","Hisob: Excuse me! Can we have the bill, please? · Let's split the bill. / It's on me."]},{"id":"u8-l5","slug":"shopping-for-clothes","title":"Shopping for clothes","titleUz":"Kiyim do'konida: o'lcham, rang, too big","goal":"Kiyim do'konida gaplashasiz: What size are you? Can I try it on? Have you got this in blue? Muammoni aytasiz: It's too big. / It isn't long enough. / It doesn't fit. va maqtaysiz: It suits you!","words":[{"en":"trousers","uz":"shim","ipa":"ˈtraʊ.zəz"},{"en":"pocket","uz":"cho'ntak","ipa":"ˈpɒk.ɪt"},{"en":"a pair of","uz":"bir juft …","ipa":"ə ˈpeə əv"},{"en":"size","uz":"o'lcham","ipa":"saɪz"},{"en":"try on","uz":"kiyib ko'rmoq","ipa":"ˌtraɪ ˈɒn"},{"en":"fitting room","uz":"kiyinish (kiyib ko'rish) xonasi","ipa":"ˈfɪt.ɪŋ ˌruːm"},{"en":"fit","uz":"(o'lchami) to'g'ri kelmoq","ipa":"fɪt"},{"en":"suit","uz":"yarashmoq; kostyum","ipa":"suːt"},{"en":"tight","uz":"tor, qisib turadigan","ipa":"taɪt"},{"en":"loose","uz":"keng, bo'sh (kiyim)","ipa":"luːs"}],"summary":["trousers, jeans, shorts, glasses — doim ko'plik: These jeans are…, I like them; bitta = a pair of jeans.","Do'konda: What size are you? Can I try it on? Have you got this in blue? Where's the fitting room?","too + sifat (ortiqcha, muammo) / not + sifat + enough (kam): too small = not big enough.","fit = o'lchami to'g'ri kelmoq; suit = yarashmoq: It fits, but it doesn't suit me."]},{"id":"u8-l6","slug":"recipes-first-then-finally","title":"Recipes: first, then, finally","titleUz":"Retsept: first, then, after that, finally","goal":"Oddiy retseptni o'qiysiz va o'zingiz tushuntirasiz: buyruq gaplar (Chop the onions. Don't add oil.), oshxona fe'llari (chop, peel, boil, fry, mix, stir…) va ketma-ketlik so'zlari: First, Then, After that, Finally.","words":[{"en":"chop","uz":"mayda to'g'ramoq","ipa":"tʃɒp"},{"en":"peel","uz":"po'stini archmoq","ipa":"piːl"},{"en":"boil","uz":"qaynatmoq; qaynamoq","ipa":"bɔɪl"},{"en":"fry","uz":"qovurmoq","ipa":"fraɪ"},{"en":"bake","uz":"(duxovkada) pishirmoq","ipa":"beɪk"},{"en":"mix","uz":"aralashtirmoq","ipa":"mɪks"},{"en":"stir","uz":"(qoshiq bilan) aylantirmoq","ipa":"stɜː"},{"en":"add","uz":"qo'shmoq","ipa":"æd"},{"en":"pour","uz":"quymoq","ipa":"pɔː"},{"en":"pan","uz":"tova; kastryulka","ipa":"pæn"}],"summary":["Retseptda buyruq gap: fe'l + … — Chop the onions. Inkor: Don't + fe'l — Don't add oil.","Fe'llar: wash, peel, chop, boil, fry, bake, mix, stir, add, pour; umumiy — cook.","Tartib: First, → Then → Next, → After that, → Finally, (At last emas!).","Vaqt: for ten minutes (davomida), until golden (… bo'lguncha)."]},{"id":"u8-l10","slug":"planning-a-dinner-shopping-list-and-recipe","title":"Planning a dinner: shopping list and recipe","titleUz":"Kechki ovqat rejasi: ro'yxat va retsept","goal":"Kechki ovqatga xaridlar ro'yxatini tuzasiz (We need…, We don't need…), retseptni first, then, finally bilan aytasiz va maslahat berasiz: You should / shouldn't…","words":[{"en":"list","uz":"ro'yxat","ipa":"lɪst"},{"en":"guest","uz":"mehmon","ipa":"ɡest"},{"en":"ingredient","uz":"masalliq, tarkibiy qism","ipa":"ɪnˈɡriː.di.ənt"},{"en":"serve","uz":"(ovqat) tortmoq","ipa":"sɜːv"}],"summary":["Ro'yxat: We need…, We don't need any…","Retsept: First, … Then … Finally, …","Maslahat: You should / shouldn't + oddiy fe'l.","Yangi so'zlar: list, guest, ingredient, serve."]},{"id":"u8-l7","slug":"healthy-habits-should-shouldnt","title":"Healthy habits: should / shouldn't","titleUz":"Sog'lom odatlar: should / shouldn't","goal":"Maslahat berasiz va so'raysiz: You should eat more fruit. You shouldn't skip breakfast. What should I do? — I think you should… Sog'lom va zararli odatlar haqida gapirasiz.","words":[{"en":"healthy","uz":"sog'lom, foydali","ipa":"ˈhel.θi"},{"en":"junk food","uz":"zararli tez ovqat (fast food, chips…)","ipa":"ˈdʒʌŋk ˌfuːd"},{"en":"habit","uz":"odat","ipa":"ˈhæb.ɪt"},{"en":"skip","uz":"tashlab ketmoq, o'tkazib yubormoq","ipa":"skɪp"},{"en":"exercise","uz":"jismoniy mashq; mashq qilmoq","ipa":"ˈek.sə.saɪz"},{"en":"diet","uz":"ovqatlanish tartibi; parhez","ipa":"ˈdaɪ.ət"},{"en":"fresh","uz":"yangi, toza (uzilgan, pishgan)","ipa":"freʃ"},{"en":"fried","uz":"qovurilgan","ipa":"fraɪd"},{"en":"sweets","uz":"shirinliklar, konfetlar","ipa":"swiːts"},{"en":"stay up late","uz":"kechgacha uxlamay o'tirmoq","ipa":"ˌsteɪ ʌp ˈleɪt"}],"summary":["should + fe'lning o'zi — maslahat: You should eat more fruit. (to yo'q, -s yo'q).","Inkor: shouldn't — You shouldn't skip breakfast. Savol: Should I…? / What should I do? — Yes, you should. / No, you shouldn't.","Yumshoq maslahat: I think you should… / I don't think you should… / Maybe you should…","Talaffuz: should = \"shud\" (l o'qilmaydi); should va shouldn't ni n orqali farqlang."]},{"id":"u8-l8","slug":"comparing-better-the-best-as-as","title":"Comparing: better, the best, as… as","titleUz":"Qiyoslash: better, the best, as… as","goal":"Ovqat, narx va joylarni chuqurroq qiyoslaysiz: much cheaper, a bit spicier than me, tenglik va farq: as tasty as / not as fresh as, eng zo'ri: the best plov in town. Ta'm sifatlarini (sweet, sour, salty, spicy, juicy…) bilasiz.","words":[{"en":"tasty","uz":"mazali","ipa":"ˈteɪ.sti"},{"en":"sweet","uz":"shirin","ipa":"swiːt"},{"en":"sour","uz":"nordon","ipa":"ˈsaʊ.ə"},{"en":"salty","uz":"sho'r","ipa":"ˈsɔːl.ti"},{"en":"bitter","uz":"taxir, achchiq (qahvadek)","ipa":"ˈbɪt.ə"},{"en":"spicy","uz":"achchiq (qalampirli)","ipa":"ˈspaɪ.si"},{"en":"juicy","uz":"sersuv, shirali","ipa":"ˈdʒuː.si"},{"en":"ripe","uz":"pishgan (meva)","ipa":"raɪp"},{"en":"crispy","uz":"qarsildoq","ipa":"ˈkrɪs.pi"},{"en":"soft","uz":"yumshoq","ipa":"sɒft"}],"summary":["Imlo: tasty → tastier, hot → hotter, fresh → fresher; uzun: more delicious; istisno: better / the best, worse / the worst.","Farq darajasi: much / a lot / a bit + qiyosiy — much cheaper (very cheaper ❌); than me.","Tenglik: as + sifat + as — as soft as; farq: not as … as — Cola isn't as healthy as juice.","Orttirma: the best … in (joy) / of (guruh): the best plov in Tashkent, the busiest day of the week.","Ta'mlar: sweet, sour, salty, bitter, spicy; sifatlar: juicy, ripe, crispy, soft, tasty."]},{"id":"u8-l13","slug":"as-as-and-the-same-as","title":"as … as and the same as","titleUz":"as … as va the same as: tenglashtirish","goal":"Ikki narsani tenglashtirasiz: as cheap as, the same price as, the same size as — va farqni aytasiz: different from, not the same as. Narx, o'lcham va ovqat haqida gapirganda ishlatasiz.","words":[{"en":"same","uz":"bir xil, o'sha","ipa":"seɪm"},{"en":"different","uz":"boshqacha, farqli","ipa":"ˈdɪf.ər.ənt"},{"en":"similar","uz":"o'xshash","ipa":"ˈsɪm.ɪ.lər"},{"en":"brand","uz":"marka, brend","ipa":"brænd"},{"en":"heavy","uz":"og'ir","ipa":"ˈhev.i"},{"en":"fair","uz":"adolatli, o'rtacha (narx)","ipa":"feə"}],"summary":["Tenglik: as + sifat + as (as cheap as) yoki the same + ot + as (the same price as).","Farq: different from yoki not the same as.","as … as ichida sifat o'zgarmaydi; the same da the tushmaydi.","Yangi so'zlar: same, different, similar, brand, heavy, fair."]},{"id":"u8-l14","slug":"listening-and-speaking-ordering-a-meal","title":"Listening and speaking: ordering a meal","titleUz":"Tinglash va gapirish: ovqat buyurtma qilish","goal":"Restoran suhbatini tinglab, nima buyurtma qilingani va maxsus talablarni topasiz, o'zingiz esa stol band qilib, ovqat tanlab, muloyim buyurtma berasiz.","words":[{"en":"waiter","uz":"ofitsiant","ipa":"ˈweɪ.tər"},{"en":"recommend","uz":"tavsiya qilmoq","ipa":"ˌrek.əˈmend"},{"en":"vegetarian","uz":"vegetarian (go'sht yemaydigan)","ipa":"ˌvedʒ.ɪˈteə.ri.ən"},{"en":"allergic","uz":"allergik","ipa":"əˈlɜː.dʒɪk"},{"en":"special","uz":"maxsus taom (bugungi)","ipa":"ˈspeʃ.əl"},{"en":"book a table","uz":"stol band qilmoq","ipa":"bʊk ə ˈteɪ.bəl"}],"summary":["Stol band qilish: I'd like to book a table for two.","Tavsiya so'rash: What do you recommend?; maxsus talab: I'm vegetarian. I'm allergic to nuts.","Buyurtma: I'd like… / I'll have… / Could I have…, please? — Give me emas.","Yangi so'zlar: waiter, recommend, vegetarian, allergic, special, book a table."]},{"id":"u8-l15","slug":"reading-and-writing-a-menu-and-a-shopping-list","title":"Reading and writing: a menu and a shopping list","titleUz":"O'qish va yozish: menyu va xarid ro'yxati","goal":"Menyu va retseptni o'qib kerakli ma'lumotni (narx, masalliq, tartib) topasiz va o'zingiz xarid ro'yxati hamda qisqa buyurtma xati yozasiz.","words":[{"en":"recipe","uz":"retsept","ipa":"ˈres.ɪ.pi"},{"en":"grilled","uz":"panjarada pishirilgan","ipa":"ɡrɪld"},{"en":"snack","uz":"yengil taom, gazak","ipa":"snæk"},{"en":"sauce","uz":"sous","ipa":"sɔːs"},{"en":"extra","uz":"qo'shimcha","ipa":"ˈek.strə"},{"en":"served with","uz":"... bilan beriladi","ipa":"sɜːvd wɪð"}],"summary":["Menyuda avval narx, nima bilan beriladi (served with) va qo'shimcha (extra) ni qidiring.","Retseptda tartib: First, … Then … After that … Finally, …","Ro'yxat: a kilo of flour, a bottle of oil, 6 eggs.","Buyurtma xati: Hello, I'd like to order… please. Thank you.","Yangi so'zlar: recipe, grilled, snack, sauce, extra, served with."]},{"id":"u8-l11","slug":"food-and-shopping-final-review","title":"Food and shopping: final review","titleUz":"Ovqat va xarid: yakuniy takror","goal":"8-bo'lim mavzularini takrorlaysiz: idish va o'lchovlar, miqdor so'zlari, narx, kafe, kiyim, retsept, should, qiyoslash.","words":[{"en":"bargain","uz":"arzon xarid","ipa":"ˈbɑː.ɡɪn"},{"en":"customer","uz":"xaridor, mijoz","ipa":"ˈkʌs.tə.mər"},{"en":"offer","uz":"taklif qilmoq","ipa":"ˈɒf.ər"}],"summary":["Miqdor: a kilo of, a bottle of, a few + ko'plik, a little + sanalmaydigan.","Narx va buyurtma: How much is/are…? Could I have…? Can I pay by card?","Retsept va maslahat: First, then, finally; should / shouldn't + oddiy fe'l.","Qiyoslash: better than, the best, as … as."]}]},{"id":"u9","n":9,"title":"Stories from the Past","titleUz":"O'tmishdan hikoyalar: Past Simple chuqurroq","description":"Past Simple chuqurroq: ago / last, yangi noto'g'ri fe'llar, Wh-savollar, there was, could, tarjimai hol, hikoya qilish.","canDo":["O'tmishdagi voqealarni hikoya qilaman","Wh-savollarni o'tgan zamonda beraman","Hayot yo'lim haqida gapiraman","Gaplarni and, but, so, because bilan bog'layman"],"lessons":[{"id":"u9-l1","slug":"yesterday-last-week-two-days-ago","title":"Yesterday, last week, two days ago","titleUz":"O'tgan zamon vaqt so'zlari: ago, last, yesterday","goal":"O'tgan voqea qachon bo'lganini aniq ayta olasiz: yesterday afternoon, the day before yesterday, last month, a long time ago, in 2019, this morning, when I was a child — va bu iboralarni to'g'ri joyda, predlogsiz yoki to'g'ri predlog bilan ishlatasiz.","words":[{"en":"the day before yesterday","uz":"kechadan oldingi kun (ikki kun oldin)","ipa":"ðə ˌdeɪ bɪˌfɔː ˈjes.tə.deɪ"},{"en":"yesterday afternoon","uz":"kecha tushdan keyin","ipa":"ˌjes.tə.deɪ ˌɑːf.təˈnuːn"},{"en":"this morning","uz":"bugun ertalab","ipa":"ðɪs ˈmɔː.nɪŋ"},{"en":"last month","uz":"o'tgan oy","ipa":"ˌlɑːst ˈmʌnθ"},{"en":"last summer","uz":"o'tgan yoz","ipa":"ˌlɑːst ˈsʌm.ə"},{"en":"a long time ago","uz":"ancha oldin, uzoq vaqt oldin","ipa":"ə ˌlɒŋ ˈtaɪm əˌɡəʊ"},{"en":"a few minutes ago","uz":"bir necha daqiqa oldin","ipa":"ə ˌfjuː ˈmɪn.ɪts əˌɡəʊ"},{"en":"last weekend","uz":"o'tgan dam olish kunlari","ipa":"ˌlɑːst ˌwiːkˈend"},{"en":"when I was a child","uz":"bolaligimda","ipa":"wen aɪ wəz ə ˈtʃaɪld"},{"en":"cousin","uz":"amakivachcha, xolavachcha, ammavachcha, tog'avachcha (qarindoshingizning farzandi)","ipa":"ˈkʌz.ən"}],"summary":["yesterday morning / afternoon / evening, lekin last night (yesterday night emas); the day before yesterday = kechadan oldingi kun.","last + week / month / summer / Monday — oldida the ham, in / on ham yo'q.","Vaqt miqdori + ago: five minutes ago, a long time ago (❌ before two years). O'tmishdagi voqeadan keyin — later.","Aniq vaqt: in 2019 / May, on Friday / 3 March, at six; davr: when I was a child."]},{"id":"u9-l2","slug":"irregular-verbs-3","title":"Irregular verbs 3","titleUz":"Noto'g'ri fe'llar 3","goal":"Yana 10 ta noto'g'ri fe'lni o'rganasiz: slept, felt, left, spent, sent, lost, brought, taught, told, heard — va ularni to'g'ri talaffuz qilib, tell / say, bring / take kabi chalkash juftliklarni adashtirmay ishlatasiz.","words":[{"en":"sleep – slept","uz":"uxlamoq","ipa":"sliːp – slept"},{"en":"feel – felt","uz":"his qilmoq","ipa":"fiːl – felt"},{"en":"leave – left","uz":"ketmoq; qoldirmoq","ipa":"liːv – left"},{"en":"spend – spent","uz":"sarflamoq; (vaqt) o'tkazmoq","ipa":"spend – spent"},{"en":"send – sent","uz":"yubormoq","ipa":"send – sent"},{"en":"lose – lost","uz":"yo'qotmoq; yutqazmoq","ipa":"luːz – lɒst"},{"en":"bring – brought","uz":"olib kelmoq","ipa":"brɪŋ – brɔːt"},{"en":"teach – taught","uz":"o'rgatmoq, dars bermoq","ipa":"tiːtʃ – tɔːt"},{"en":"tell – told","uz":"aytib bermoq (kimgadir)","ipa":"tel – təʊld"},{"en":"hear – heard","uz":"eshitmoq","ipa":"hɪə – hɜːd"}],"summary":["sleep – slept, feel – felt, leave – left (i: → e + t); spend – spent, send – sent (d → t).","bring – brought, teach – taught (\"o:t\", gh o'qilmaydi); tell – told; lose – lost; hear – heard (\"hö:d\").","tell somebody (told me), lekin say something (said hello). bring — bu yerga, take — u yerga.","Iboralar: left home, left my phone, spent money/a week, sent a message, felt tired, lost the match."]},{"id":"u9-l3","slug":"where-did-you-go-what-did-you-do","title":"Where did you go? What did you do?","titleUz":"O'tgan zamonda Wh-savollar","goal":"O'tgan voqea haqida batafsil so'ray olasiz: Where did you go? What did you do? Who did you meet? How long did you stay? How was it? What happened? — va bunday savollarga qisqa, tabiiy javob berasiz.","words":[{"en":"happen","uz":"sodir bo'lmoq, bo'lmoq","ipa":"ˈhæp.ən"},{"en":"picnic","uz":"piknik","ipa":"ˈpɪk.nɪk"},{"en":"musician","uz":"sozanda, musiqachi","ipa":"mjuˈzɪʃ.ən"},{"en":"everybody","uz":"hamma, barcha","ipa":"ˈev.ri.bɒd.i"},{"en":"stay up","uz":"kech yotmaslik","ipa":"steɪ ʌp"},{"en":"relatives","uz":"qarindoshlar","ipa":"ˈrel.ə.tɪvz"},{"en":"boring","uz":"zerikarli","ipa":"ˈbɔː.rɪŋ"},{"en":"fantastic","uz":"ajoyib, zo'r","ipa":"fænˈtæs.tɪk"},{"en":"sleepy","uz":"uyqusiragan","ipa":"ˈsliː.pi"},{"en":"have fun","uz":"xursandchilik qilmoq, maza qilmoq","ipa":"ˌhæv ˈfʌn"}],"summary":["Savol so'zi + did + ega + V1: Where did you go? What did she buy? How long did you stay?","be bilan did yo'q: Where were you? How was your trip? Why was she late?","Ega so'ralsa — did yo'q, fe'l V2: Who called you? What happened?","Tez nutqda did you = \"didʒu\"; Wh-savol ohangi oxirida pasayadi ↘."]},{"id":"u9-l12","slug":"past-simple-negatives-and-questions-mixed","title":"Past Simple: negatives and questions mixed","titleUz":"Past Simple: inkor va savollar aralash mashq","goal":"O'tgan zamonda inkor (didn't + V1) va savol (Did + ega + V1?) ni oddiy ham, noto'g'ri fe'llar bilan ham xatosiz qurasiz va tayyor gapdagi xatoni topib tuzata olasiz: I didn't see him. Did you buy a ticket?","words":[{"en":"mistake","uz":"xato","ipa":"mɪˈsteɪk"},{"en":"wallet","uz":"hamyon","ipa":"ˈwɒl.ɪt"},{"en":"umbrella","uz":"soyabon","ipa":"ʌmˈbrel.ə"},{"en":"wait","uz":"kutmoq","ipa":"weɪt"},{"en":"answer","uz":"javob bermoq; javob","ipa":"ˈɑːn.sə"},{"en":"correct","uz":"to'g'ri; tuzatmoq","ipa":"kəˈrekt"}],"summary":["Ijobiy gap: V2 (bought, visited). Inkor: didn't + V1. Savol: Did + ega + V1?","Qisqa javob: Yes, I did. / No, I didn't.","did / didn't dan keyin hech qachon V2 qo'ymang: ❌ didn't went, ❌ Did you saw?","was / were bilan did kerak emas: He wasn't at home. Were you late?","Yangi so'zlar: mistake, wallet, umbrella, wait, answer, correct."]},{"id":"u9-l4","slug":"there-was-were-could-couldnt","title":"there was / were, could / couldn't","titleUz":"there was / were va could / couldn't","goal":"O'tmishda nima bor edi / yo'q edi ekanini (there was / there were, there wasn't any…, Was there…?) va nimani qila olardingiz / qila olmadingiz (could / couldn't) aytib bera olasiz: shahringiz, bolaligingiz, biror voqea haqida.","words":[{"en":"playground","uz":"o'yin maydonchasi","ipa":"ˈpleɪ.ɡraʊnd"},{"en":"field","uz":"dala; maydon","ipa":"fiːld"},{"en":"candle","uz":"sham","ipa":"ˈkæn.dəl"},{"en":"fountain","uz":"favvora","ipa":"ˈfaʊn.tɪn"},{"en":"traffic","uz":"yo'l harakati; tirbandlik","ipa":"ˈtræf.ɪk"},{"en":"crowded","uz":"odam gavjum, tiqilinch","ipa":"ˈkraʊ.dɪd"},{"en":"charge","uz":"quvvatlamoq (telefonni)","ipa":"tʃɑːdʒ"},{"en":"noisy","uz":"shovqinli","ipa":"ˈnɔɪ.zi"},{"en":"square","uz":"maydon (shahar maydoni)","ipa":"skweə"},{"en":"power cut","uz":"svet o'chishi (elektr uzilishi)","ipa":"ˈpaʊə ˌkʌt"}],"summary":["There was + birlik / sanalmaydigan ot; There were + ko'plik: There were a lot of people.","Inkor: There wasn't / weren't any… yoki There was / were no…; savol: Was / Were there…? — Yes, there was. / No, there weren't.","\"... bor edi\" ni ❌ had yoki ❌ It was bilan emas, There was / were bilan ayting.","could / couldn't + V1 — o'tmishdagi qobiliyat: I could swim at six. I couldn't sleep. (\"kud\", l o'qilmaydi)."]},{"id":"u9-l13","slug":"could-couldnt-and-was-able-to","title":"could / couldn't and was able to","titleUz":"could / couldn't: o'tmishdagi qobiliyat","goal":"O'tmishda nimani qila olganingiz / qila olmaganingizni aytasiz: umumiy qobiliyat uchun could / couldn't, bitta aniq voqeada muvaffaqiyat uchun was / were able to: I could swim at six. Yesterday I was able to climb the mountain.","words":[{"en":"be able to","uz":"qila olmoq","ipa":"bi ˈeɪ.bəl tuː"},{"en":"carry","uz":"ko'tarib yurmoq, olib yurmoq","ipa":"ˈkær.i"},{"en":"heavy","uz":"og'ir","ipa":"ˈhev.i"},{"en":"lift","uz":"ko'tarmoq","ipa":"lɪft"},{"en":"top","uz":"cho'qqi, tepa","ipa":"tɒp"},{"en":"lock","uz":"qulflamoq; qulf","ipa":"lɒk"}],"summary":["Umumiy qobiliyat: could / couldn't + V1 (I could swim at six).","Bitta aniq voqeada muvaffaqiyat: was / were able to + V1 (I was able to find the key).","Inkorda ikkalasi ham to'g'ri: couldn't = wasn't / weren't able to.","Xato: ❌ They was able to, ❌ wasn't able carry, ❌ couldn't opened.","Yangi so'zlar: carry, heavy, lift, top, lock, be able to."]},{"id":"u9-l5","slug":"life-stories","title":"Life stories","titleUz":"Hayot yo'li: born, grew up, moved…","goal":"O'zingiz yoki boshqa odamning hayot yo'lini gapirib bera olasiz: was born, grew up, left school, got a job, got married, moved to, became, retired — sanalar va at the age of, after that, two years later kabi iboralar bilan.","words":[{"en":"grow up – grew up","uz":"o'smoq, voyaga yetmoq","ipa":"ɡrəʊ ˈʌp – ɡruː ˈʌp"},{"en":"become – became","uz":"… bo'lmoq (kasb, holat)","ipa":"bɪˈkʌm – bɪˈkeɪm"},{"en":"move","uz":"ko'chmoq, ko'chib o'tmoq","ipa":"muːv"},{"en":"get a job","uz":"ishga joylashmoq","ipa":"ˌɡet ə ˈdʒɒb"},{"en":"get married","uz":"turmush qurmoq (uylanmoq / turmushga chiqmoq)","ipa":"ˌɡet ˈmær.id"},{"en":"have a baby","uz":"farzand ko'rmoq","ipa":"ˌhæv ə ˈbeɪ.bi"},{"en":"retire","uz":"nafaqaga chiqmoq","ipa":"rɪˈtaɪə"},{"en":"die","uz":"vafot etmoq, o'lmoq","ipa":"daɪ"},{"en":"childhood","uz":"bolalik","ipa":"ˈtʃaɪld.hʊd"},{"en":"at the age of","uz":"… yoshida","ipa":"ət ði ˈeɪdʒ əv"}],"summary":["Hayot voqealari: was born, grew up, left school, got a job, got married, had a baby, moved to, became, retired, died.","I was born (❌ I born / I am born); savolda: Where were you born? lekin Where did you grow up?","at the age of 17, in 1990, move to + joy, get married to + kishi, become a + kasb.","Voqealarni then, after that, two years later, in the end bilan bog'lang."]},{"id":"u9-l9","slug":"my-weekend-telling-a-friend","title":"My weekend: telling a friend","titleUz":"Dam olish kunim: do'stga hikoya","goal":"Do'stingizga o'tgan dam olish kuningiz haqida gapirib berasiz: I visited my grandmother and we cooked plov. Past Simple (ijobiy, inkor, savol) va vaqt so'zlari (last weekend, on Saturday, in the evening, then) ni real suhbatda ishlatasiz.","words":[{"en":"relax","uz":"dam olmoq, xotirjam bo'lmoq","ipa":"rɪˈlæks"},{"en":"lazy","uz":"dangasa","ipa":"ˈleɪ.zi"},{"en":"wonderful","uz":"ajoyib, a'lo","ipa":"ˈwʌn.də.fəl"}],"summary":["Savol: How was your weekend? / What did you do? Javob: Past Simple + vaqt so'zlari (on Saturday, then, in the evening).","Ijobiy: V2 (went, cooked); inkor va savol: didn't / did + V1.","Yangi so'zlar: relax, lazy, wonderful."]},{"id":"u9-l6","slug":"telling-a-story-and-but-so-because","title":"Telling a story: and, but, so, because","titleUz":"Hikoya qilish: and, but, so, because","goal":"Qisqa gaplarni and, but, so, because bilan bog'lab, izchil hikoya qila olasiz; so (natija) va because (sabab) ni adashtirmaysiz; hikoyani suddenly, luckily, unfortunately, in the end bilan jonli qilasiz.","words":[{"en":"suddenly","uz":"to'satdan, birdan","ipa":"ˈsʌd.ən.li"},{"en":"luckily","uz":"baxtimizga, omad kelib","ipa":"ˈlʌk.ɪ.li"},{"en":"unfortunately","uz":"afsuski","ipa":"ʌnˈfɔː.tʃən.ət.li"},{"en":"in the end","uz":"oxir-oqibat, oxirida","ipa":"ɪn ði ˈend"},{"en":"miss","uz":"(transportdan) qolib ketmoq; sog'inmoq","ipa":"mɪs"},{"en":"worried","uz":"xavotirda, tashvishli","ipa":"ˈwʌr.id"},{"en":"surprised","uz":"hayron, ajablangan","ipa":"səˈpraɪzd"},{"en":"spices","uz":"ziravorlar","ipa":"spaɪ.sɪz"},{"en":"remember","uz":"eslamoq, esda tutmoq","ipa":"rɪˈmem.bə"},{"en":"nobody","uz":"hech kim","ipa":"ˈnəʊ.bə.di"}],"summary":["and — qo'shish, but — qarama-qarshilik, so — natija (shuning uchun), because — sabab (chunki).","Bitta vaziyat ikki xil: I was tired, so I went to bed = I went to bed because I was tired.","because va so bitta gapda birga ishlatilmaydi (❌ Because it rained, so…).","Hikoyani jonlantiring: First, Then, Suddenly, Luckily, Unfortunately, In the end."]},{"id":"u9-l7","slug":"holidays-transport","title":"Holidays & transport","titleUz":"Ta'til va transport: by bus, on foot","goal":"Ta'tilingiz va safaringiz haqida gapirib bera olasiz: by bus / by train / on foot, took a taxi, got on / got off, flew, drove, rode, It took four hours, went sightseeing, stayed at a hotel.","words":[{"en":"camel","uz":"tuya","ipa":"ˈkæm.əl"},{"en":"fly – flew","uz":"uchmoq, samolyotda bormoq","ipa":"flaɪ – fluː"},{"en":"drive – drove","uz":"(mashina) haydamoq, mashinada bormoq","ipa":"draɪv – drəʊv"},{"en":"ride – rode","uz":"minmoq (velosiped, ot, tuya)","ipa":"raɪd – rəʊd"},{"en":"get on","uz":"(avtobus, poyezd, samolyotga) chiqmoq","ipa":"ˌɡet ˈɒn"},{"en":"get off","uz":"(avtobus, poyezddan) tushmoq","ipa":"ˌɡet ˈɒf"},{"en":"go on holiday","uz":"ta'tilga / dam olishga bormoq","ipa":"ˌɡəʊ ɒn ˈhɒl.ə.deɪ"},{"en":"go sightseeing","uz":"diqqatga sazovor joylarni aylanmoq","ipa":"ˌɡəʊ ˈsaɪtˌsiː.ɪŋ"},{"en":"souvenir","uz":"esdalik sovg'asi","ipa":"ˌsuː.vəˈnɪə"},{"en":"comfortable","uz":"qulay, rohat","ipa":"ˈkʌm.fə.tə.bəl"}],"summary":["by bus / car / train / plane / taxi / metro — artiklsiz; piyoda — on foot (❌ by foot, ❌ with bus).","Yangi fe'llar: fly – flew, drive – drove, ride – rode; took a taxi / the train.","get on / off — avtobus, poyezd, samolyot; get in(to) / out of — mashina, taksi.","How did you get there? — It took (us) four hours. Ta'til: went on holiday, went abroad, went sightseeing, stayed at a hotel, bought souvenirs."]},{"id":"u9-l10","slug":"a-trip-last-summer","title":"A trip last summer","titleUz":"O'tgan yozgi sayohat","goal":"O'tgan yozgi sayohatingiz haqida gapirib berasiz: We went to Samarkand by train. There was a beautiful square, but it was crowded, so we couldn't take many photos. Transport, there was / were, could / couldn't va and, but, so, because ni real suhbatda ishlatasiz.","words":[{"en":"beach","uz":"plyaj, sohil","ipa":"biːtʃ"},{"en":"luggage","uz":"yuk, sumkalar","ipa":"ˈlʌɡ.ɪdʒ"},{"en":"view","uz":"manzara","ipa":"vjuː"}],"summary":["Sayohat haqida: Where did you go? How did you get there? — We went by train / on foot.","Tasvir: There was + birlik, There were + ko'plik; could / couldn't + V1.","Bog'lovchilar: and (qo'shish), but (lekin), so (natija), because (sabab).","Yangi so'zlar: beach, luggage, view."]},{"id":"u9-l8","slug":"irregular-verbs-4","title":"Irregular verbs 4","titleUz":"Noto'g'ri fe'llar 4 va o'tgan zamon takrori","goal":"Yana 10 ta noto'g'ri fe'lni o'rganasiz: swam, ran, began, sang, won, broke, forgot, wore, caught, fell — va butun bo'lim bo'yicha Past Simple'ni (ijobiy, inkor, savol, was / were, there was, could) xatosiz ishlatib, hikoya qila olasiz.","words":[{"en":"swim – swam","uz":"suzmoq","ipa":"swɪm – swæm"},{"en":"run – ran","uz":"yugurmoq","ipa":"rʌn – ræn"},{"en":"begin – began","uz":"boshlamoq, boshlanmoq","ipa":"bɪˈɡɪn – bɪˈɡæn"},{"en":"sing – sang","uz":"kuylamoq, qo'shiq aytmoq","ipa":"sɪŋ – sæŋ"},{"en":"cut – cut","uz":"kesmoq; (qo'lni) kesib olmoq","ipa":"kʌt – kʌt"},{"en":"break – broke","uz":"sindirmoq, sinmoq","ipa":"breɪk – brəʊk"},{"en":"forget – forgot","uz":"unutmoq","ipa":"fəˈɡet – fəˈɡɒt"},{"en":"wear – wore","uz":"kiymoq, kiyib yurmoq","ipa":"weə – wɔː"},{"en":"catch – caught","uz":"tutmoq; ulgurmoq; (kasal) yuqtirmoq","ipa":"kætʃ – kɔːt"},{"en":"fall – fell","uz":"yiqilmoq, tushmoq","ipa":"fɔːl – fel"}],"summary":["Yangi fe'llar: swim – swam, run – ran, begin – began, sing – sang, win – won (\"wan\").","break – broke, forget – forgot, wear – wore, catch – caught (\"ko:t\"), fall – fell (felt emas!).","O'zgarmaydiganlar: put, cut, cost, hit — vaqt so'zidan bilinadi.","Oltin qoida: did / didn't / could / couldn't + V1; V2 — ijobiy gapda va Who won? kabi ega-savollarda.","Hikoya: vaqt so'zlari (ago, last, later) + there was / were + and, but, so, because."]},{"id":"u9-l14","slug":"listening-and-speaking-what-did-you-do","title":"Listening and speaking: what did you do?","titleUz":"Tinglash va gapirish: nima qildingiz?","goal":"O'tgan kun haqidagi qisqa suhbatni tinglab tushunasiz (kim, qayerda, nima qildi) va o'zingiz nima qilganingizni ovoz chiqarib aytasiz: What did you do? — I went to a concert with my friends. We had a lovely evening.","words":[{"en":"invite","uz":"taklif qilmoq, chaqirmoq","ipa":"ɪnˈvaɪt"},{"en":"enjoy","uz":"yoqtirmoq, zavqlanmoq","ipa":"ɪnˈdʒɔɪ"},{"en":"lovely","uz":"yoqimli, chiroyli","ipa":"ˈlʌv.li"},{"en":"midnight","uz":"yarim tun","ipa":"ˈmɪd.naɪt"},{"en":"alone","uz":"yolg'iz","ipa":"əˈləʊn"},{"en":"until","uz":"gacha, qadar","ipa":"ənˈtɪl"}],"summary":["Suhbatda qidiring: kim, qachon / qayerda, nima qildi. Javoblar ko'pincha V2 va did / didn't da.","Javob formulasi: qisqa javob + tafsilot (Yes, I did. It was lovely.).","Tez gapirishda did you — \"didya\"; asosiy fe'lni ushlang.","Yangi so'zlar: invite, enjoy, lovely, midnight, alone, until."]},{"id":"u9-l15","slug":"reading-and-writing-a-short-story","title":"Reading and writing: a short story","titleUz":"O'qish va yozish: qisqa hikoya","goal":"O'tgan zamondagi qisqa hikoyani o'qib tushunasiz va o'zingiz hikoya yozasiz: voqealarni one day, at first, then, finally bilan tartiblab, and, but, so, because bilan bog'laysiz.","words":[{"en":"at first","uz":"avval, dastlab","ipa":"æt fɜːst"},{"en":"finally","uz":"oxiri, nihoyat","ipa":"ˈfaɪ.nəl.i"},{"en":"one day","uz":"bir kuni","ipa":"wʌn deɪ"},{"en":"gift","uz":"sovg'a","ipa":"ɡɪft"},{"en":"neighbour","uz":"qo'shni","ipa":"ˈneɪ.bə"},{"en":"knock","uz":"taqillatmoq","ipa":"nɒk"}],"summary":["Hikoya tartibi: One day → At first → Then / After that → Finally.","Bog'lovchilar: and (qo'shish), but (qarama-qarshilik), so (natija), because (sabab).","Hikoya o'tgan zamonda yoziladi: V2, inkorda didn't + V1.","Yangi so'zlar: at first, finally, one day, gift, neighbour, knock."]},{"id":"u9-l11","slug":"stories-from-the-past-final-review","title":"Stories from the past: final review","titleUz":"O'tmishdan hikoyalar: yakuniy takror","goal":"Butun bo'limni takrorlaysiz: ago / last / yesterday, noto'g'ri fe'llar, o'tgan zamon Wh-savollari, there was / were, could / couldn't, hayot hikoyasi, and / but / so / because va transport. Oxirida o'tmish haqida kichik hikoya aytib bera olasiz.","words":[{"en":"journey","uz":"safar, yo'l","ipa":"ˈdʒɜː.ni"},{"en":"adventure","uz":"sarguzasht","ipa":"ədˈven.tʃər"},{"en":"memory","uz":"xotira, esdalik","ipa":"ˈmem.ər.i"}],"summary":["Vaqt: ago (two days ago), last (last week), yesterday.","Savol: Wh + did + ega + V1; ega-savolda: Who won?","there was (birlik) / there were (ko'plik); could / couldn't + V1.","Hikoya: and, but, so, because; transport: by bus, on foot.","Yangi so'zlar: journey, adventure, memory."]}]},{"id":"u10","n":10,"title":"Travel & Health","titleUz":"Sayohat va sog'liq: will, going to, have to, must","description":"Ob-havo, aeroport va vokzal, mehmonxona, Could I…?, will yoki going to, kasallik va maslahat, have to, must.","canDo":["Aeroport va mehmonxonada muammosiz muomala qilaman","Ob-havo haqida gapiraman","Shifokorga nima bezovta qilayotganini aytaman","Qoida va majburiyatlarni (must, have to) ayta olaman"],"lessons":[{"id":"u10-l1","slug":"whats-the-weather-like","title":"What's the weather like?","titleUz":"Ob-havo va fasllar","goal":"Ob-havo haqida erkin so'raysiz va javob berasiz: What's the weather like? — It's cold and foggy. It's minus five. It's raining. Haroratni aytasiz, ob-havo ma'lumotini (forecast) tushunasiz va fasllarni tasvirlaysiz.","words":[{"en":"forecast","uz":"ob-havo ma'lumoti, bashorat","ipa":"ˈfɔː.kɑːst"},{"en":"temperature","uz":"harorat","ipa":"ˈtem.prə.tʃə"},{"en":"degree","uz":"daraja","ipa":"dɪˈɡriː"},{"en":"freezing","uz":"qahraton, juda sovuq","ipa":"ˈfriː.zɪŋ"},{"en":"cool","uz":"salqin","ipa":"kuːl"},{"en":"foggy","uz":"tumanli","ipa":"ˈfɒɡ.i"},{"en":"storm","uz":"bo'ron, dovul","ipa":"stɔːm"},{"en":"snow","uz":"qor; qor yog'moq","ipa":"snəʊ"},{"en":"wet","uz":"ho'l, nam; yomg'irli","ipa":"wet"},{"en":"dry","uz":"quruq","ipa":"draɪ"}],"summary":["What's the weather like? = How's the weather? Javobda like yo'q: It's sunny.","It's + sifat: sunny, cloudy, windy, foggy, stormy (It's fog ❌). Ega It shart.","Hozir: It's raining / snowing. Odat: It rains a lot in April. Does it snow here?","Harorat: hot > warm > cool > cold > freezing; It's twenty degrees. It's minus five.","I'm cold (menga sovuq) ≠ It's cold (havo sovuq). Fasllar: in summer / in the summer."]},{"id":"u10-l2","slug":"at-the-station-airport","title":"At the station & airport","titleUz":"Vokzal va aeroportda","goal":"Vokzalda chipta olasiz (A return ticket to Samarkand, please.), jadval haqida so'raysiz (What time does the train leave? Which platform?) va aeroportda ro'yxatdan o'tish, gate, boarding pass, delayed kabi so'zlarni tushunasiz.","words":[{"en":"platform","uz":"platforma (vokzalda)","ipa":"ˈplæt.fɔːm"},{"en":"return ticket","uz":"borib-kelish chiptasi","ipa":"rɪˈtɜːn ˌtɪk.ɪt"},{"en":"departure","uz":"jo'nash","ipa":"dɪˈpɑː.tʃə"},{"en":"arrival","uz":"yetib kelish","ipa":"əˈraɪ.vəl"},{"en":"check in","uz":"ro'yxatdan o'tmoq","ipa":"ˌtʃek ˈɪn"},{"en":"boarding pass","uz":"bortga chiqish taloni","ipa":"ˈbɔː.dɪŋ pɑːs"},{"en":"gate","uz":"chiqish (aeroportda), darvoza","ipa":"ɡeɪt"},{"en":"delayed","uz":"kechikkan, kechikmoqda","ipa":"dɪˈleɪd"},{"en":"luggage","uz":"yuk, bagaj","ipa":"ˈlʌɡ.ɪdʒ"},{"en":"flight","uz":"reys, parvoz","ipa":"flaɪt"}],"summary":["Chipta: A single / A return (ticket) to Samarkand, please. Yo'nalish — to.","Jadval — Present Simple: What time does the train leave? It leaves at 8:15. Which platform does it leave from?","arrive in + shahar, arrive at + joy (arrive to ❌).","Aeroport: check in → boarding pass → passport control → security → gate → board. The flight is delayed / cancelled.","luggage sanalmaydi: my luggage is, two bags (luggages ❌)."]},{"id":"u10-l13","slug":"tickets-times-and-prices","title":"Tickets, times and prices","titleUz":"Chipta, vaqt va narx: single, return, platform","goal":"Vokzalda chipta, vaqt va narx haqida so'raysiz va javobni tushunasiz: How much is a return ticket? What time does the train leave? Which platform? It's delayed.","words":[{"en":"timetable","uz":"jadval (qatnov)","ipa":"ˈtaɪmˌteɪ.bəl"},{"en":"ticket office","uz":"chipta kassasi","ipa":"ˈtɪk.ɪt ˌɒf.ɪs"},{"en":"fare","uz":"yo'l haqi","ipa":"feə"},{"en":"direct train","uz":"to'g'ridan-to'g'ri poyezd","ipa":"dəˈrekt treɪn"},{"en":"carriage","uz":"vagon","ipa":"ˈkær.ɪdʒ"},{"en":"change trains","uz":"poyezd almashtirmoq","ipa":"tʃeɪndʒ treɪnz"}],"summary":["Narx: How much is a single ticket? / How much are two tickets?","Vaqt va perron: What time does the train leave? Which platform does it leave from? — does dan keyin fe'l oddiy.","Foydali: single, return, delayed, direct train, change trains.","Yangi so'zlar: timetable, ticket office, fare, direct train, carriage, change trains."]},{"id":"u10-l3","slug":"at-the-hotel-could-i","title":"At the hotel: Could I…?","titleUz":"Mehmonxonada: Can I / Could I…?","goal":"Mehmonxonada xona band qilasiz, ruxsat so'raysiz va xushmuomala iltimos qilasiz: Could I have a room for two nights? Could you call a taxi, please? Iltimosga to'g'ri javob berasiz: Yes, of course. / I'm afraid not.","words":[{"en":"reception","uz":"qabulxona, resepshn","ipa":"rɪˈsep.ʃən"},{"en":"reservation","uz":"bron, oldindan band qilish","ipa":"ˌrez.əˈveɪ.ʃən"},{"en":"single room","uz":"bir kishilik xona","ipa":"ˌsɪŋ.ɡəl ˈruːm"},{"en":"double room","uz":"ikki kishilik xona","ipa":"ˌdʌb.əl ˈruːm"},{"en":"key card","uz":"kalit-karta","ipa":"ˈkiː kɑːd"},{"en":"towel","uz":"sochiq","ipa":"ˈtaʊ.əl"},{"en":"lift","uz":"lift","ipa":"lɪft"},{"en":"check out","uz":"mehmonxonadan chiqib ketmoq (xonani topshirmoq)","ipa":"ˌtʃek ˈaʊt"},{"en":"included","uz":"narxga kirgan, qo'shilgan","ipa":"ɪnˈkluː.dɪd"},{"en":"view","uz":"manzara, ko'rinish","ipa":"vjuː"}],"summary":["Ruxsat: Can I…? / Could I + V1…? (Could — muloyimroq): Could I have the key, please?","Iltimos: Could you + V1…, please? — Could you call a taxi? (to va -ing yo'q).","Javob: Yes, of course. / Sure. / No problem. Rad: I'm afraid not. (Yes, you could tabiiy emas → Yes, you can).","could \"kud\" o'qiladi (l jim). Bu yerda u o'tgan zamon emas.","Mehmonxona: reception, reservation, single / double room, key card, towel, lift, check out, included, view."]},{"id":"u10-l9","slug":"booking-a-hotel-room","title":"Booking a hotel room","titleUz":"Mehmonxona xonasini band qilish","goal":"Mehmonxonaga qo'ng'iroq qilib xona band qilasiz: sanalarni va narxni aytasiz, Could I book a room? How much is it per night? kabi savollarni berasiz.","words":[{"en":"available","uz":"bo'sh, mavjud","ipa":"əˈveɪ.lə.bəl"},{"en":"per night","uz":"bir kechasiga","ipa":"pɜː naɪt"},{"en":"guest","uz":"mehmon","ipa":"ɡest"},{"en":"cost","uz":"turmoq (narxi)","ipa":"kɒst"}],"summary":["Xona band qilish: Could I book a room, please? — fe'l oddiy shaklda, to yo'q.","Sana va narx: from the fifth to the eighth of May, eighty dollars per night.","Savollar: Is breakfast included?, Is a room available?","Yangi so'zlar: available, per night, guest, cost."]},{"id":"u10-l4","slug":"will-or-going-to","title":"will or going to?","titleUz":"will yoki going to?","goal":"Kelajak haqida to'g'ri shaklni tanlaysiz: oldindan reja — I'm going to visit Khiva, shu zahoti qaror va taklif — I'll carry your bag, va'da — I'll call you, dalilga asoslangan bashorat — It's going to rain. Shall I…? bilan yordam taklif qilasiz.","words":[{"en":"pack","uz":"(sumka/chamadonga) narsalarni joylamoq","ipa":"pæk"},{"en":"sunglasses","uz":"quyosh ko'zoynagi","ipa":"ˈsʌnˌɡlɑː.sɪz"},{"en":"postcard","uz":"ochiq xat (otkritka)","ipa":"ˈpəʊst.kɑːd"},{"en":"cloud","uz":"bulut","ipa":"klaʊd"},{"en":"tour guide","uz":"gid, ekskursovod","ipa":"ˈtʊə ɡaɪd"},{"en":"hurry up","uz":"shoshilmoq, tezroq bo'lmoq","ipa":"ˌhʌr.i ˈʌp"},{"en":"grey","uz":"kulrang","ipa":"ɡreɪ"},{"en":"map","uz":"xarita","ipa":"mæp"},{"en":"rent","uz":"ijaraga olmoq","ipa":"rent"},{"en":"answer","uz":"javob bermoq; javob","ipa":"ˈɑːn.sə"}],"summary":["going to — oldindan reja: I'm going to visit Khiva. (Chiptalarni oldim.)","will — shu zahoti qaror, taklif, va'da: The bus is late. I'll take a taxi. I promise I'll call.","Bashorat: dalil bor → going to (Look! It's going to rain.); fikr → will (I think you'll like it.).","Taklif savolda: Shall I…? (…aymi?), Shall we…? (…aylikmi?).","O'zbekcha \"olaman\" ni ❌ I take deb tarjima qilmang — kelajak uchun I'll take / I'm going to take."]},{"id":"u10-l5","slug":"whats-the-matter","title":"What's the matter?","titleUz":"Sog'liq: What's the matter? I've got a headache","goal":"Kasalligingizni inglizcha aytasiz (I've got a headache / a cold / a sore throat. My back hurts.), boshqalardan What's the matter? deb so'raysiz va maslahat berasiz: You should see a doctor. Why don't you…? Dorixonada kerakli narsani so'ray olasiz.","words":[{"en":"headache","uz":"bosh og'rig'i","ipa":"ˈhed.eɪk"},{"en":"toothache","uz":"tish og'rig'i","ipa":"ˈtuːθ.eɪk"},{"en":"stomachache","uz":"qorin og'rig'i","ipa":"ˈstʌm.ək.eɪk"},{"en":"a cold","uz":"shamollash","ipa":"ə kəʊld"},{"en":"cough","uz":"yo'tal; yo'talmoq","ipa":"kɒf"},{"en":"sore throat","uz":"tomoq og'rig'i","ipa":"ˌsɔː ˈθrəʊt"},{"en":"have a temperature","uz":"isitmasi bo'lmoq","ipa":"hæv ə ˈtem.prə.tʃə"},{"en":"hurt","uz":"og'rimoq; shikastlamoq","ipa":"hɜːt"},{"en":"medicine","uz":"dori","ipa":"ˈmed.sən"},{"en":"plaster","uz":"plastir","ipa":"ˈplɑː.stə"}],"summary":["So'rash: What's the matter? / What's wrong? / Are you OK? Javob: I don't feel well. I'm ill.","I've got + a headache / cold / cough / sore throat / temperature; (a) toothache, (a) stomachache.","My leg hurts. My eyes hurt. (bitta → hurts, ko'p → hurt). Where does it hurt?","Maslahat: You should + V1, Why don't you + V1? Xayrlashuv: Get well soon!","Talaffuz: ache, stomach — ch = k; cough — \"kof\"; She's got a cold ≠ She's cold."]},{"id":"u10-l12","slug":"giving-advice-should-shouldnt-why-dont-you","title":"Giving advice: should, shouldn't, Why don't you…?","titleUz":"Maslahat berish: should, shouldn't, Why don't you…?","goal":"Sayohat va sog'liq haqida maslahat so'raysiz va berasiz: What should I do? Should I take a coat? You should drink water. You shouldn't stay in the sun. Why don't you lie down?","words":[{"en":"advice","uz":"maslahat (sanalmaydi)","ipa":"ədˈvaɪs"},{"en":"sunscreen","uz":"quyoshdan himoya kremi","ipa":"ˈsʌn.skriːn"},{"en":"fresh air","uz":"toza havo","ipa":"freʃ eə"},{"en":"lie down","uz":"yotmoq, cho'zilmoq","ipa":"laɪ daʊn"},{"en":"bottled water","uz":"shishadagi suv","ipa":"ˈbɒt.əld ˈwɔː.tər"},{"en":"take care","uz":"ehtiyot bo'lmoq, o'zingizni asrang","ipa":"teɪk keə"}],"summary":["Maslahat: You should + V1; qilmaslik kerak: You shouldn't + V1.","Savol: Should I take a coat? va What should I do? — do kerak emas.","Qisqa javob: Yes, you should. / No, you shouldn't. Maslahat: Why don't you lie down?","Yangi so'zlar: advice, sunscreen, fresh air, lie down, bottled water, take care."]},{"id":"u10-l10","slug":"at-the-pharmacy-and-the-doctor","title":"At the pharmacy and the doctor","titleUz":"Dorixona va shifokorda","goal":"Dorixona va shifokorda nima bezovta qilayotganini aytasiz va maslahatni tushunasiz: What's the matter? I've got a fever. You should rest. You shouldn't go to work.","words":[{"en":"pharmacy","uz":"dorixona","ipa":"ˈfɑː.mə.si"},{"en":"fever","uz":"isitma, harorat","ipa":"ˈfiː.vər"},{"en":"tablet","uz":"tabletka","ipa":"ˈtæb.lət"},{"en":"rest","uz":"dam olmoq","ipa":"rest"}],"summary":["Shifokor: What's the matter? — javob: I've got a headache / a fever / a cough.","Maslahat: should + V1, qilmaslik: shouldn't + V1 (to va -s yo'q).","Dorixonada: I need something for a cough. Dorini necha marta ichish: How often do I take it?","Yangi so'zlar: pharmacy, fever, tablet, rest."]},{"id":"u10-l6","slug":"have-to-dont-have-to","title":"have to / don't have to","titleUz":"Majburiyat: have to / don't have to","goal":"Majburiyat haqida gapirasiz: I have to show my passport. She has to wear a uniform. don't have to — \"shart emas\" ekanini bilasiz va so'raysiz: Do I have to fill in this form? O'tgan zamonda: I had to wait for an hour.","words":[{"en":"visa","uz":"viza","ipa":"ˈviː.zə"},{"en":"fill in","uz":"to'ldirmoq (anketa, blanka)","ipa":"ˌfɪl ˈɪn"},{"en":"form","uz":"shakl, anketa, blanka","ipa":"fɔːm"},{"en":"waiting room","uz":"kutish xonasi","ipa":"ˈweɪ.tɪŋ ruːm"},{"en":"queue","uz":"navbat; navbatda turmoq","ipa":"kjuː"},{"en":"on time","uz":"o'z vaqtida","ipa":"ɒn ˈtaɪm"},{"en":"prescription","uz":"retsept","ipa":"prɪˈskrɪp.ʃən"},{"en":"insurance","uz":"sug'urta","ipa":"ɪnˈʃɔː.rəns"},{"en":"document","uz":"hujjat","ipa":"ˈdɒk.jə.mənt"},{"en":"embassy","uz":"elchixona","ipa":"ˈem.bə.si"}],"summary":["have to / has to + V1 — majburiyat (\"-ishim kerak\"): She has to wear a uniform. (has to wears ❌)","don't / doesn't have to — shart emas (mumkin emas EMAS!): You don't have to pay. It's free.","Savol: Do I have to…? Does she have to…? — Yes, you do. / No, she doesn't.","O'tgan zamon: had to / didn't have to / Did you have to…? (had to went ❌).","Talaffuz: \"hafta\", \"hasta\", \"hatta\"."]},{"id":"u10-l7","slug":"must-mustnt-rules-signs","title":"must / mustn't: rules & signs","titleUz":"Qoidalar: must / mustn't","goal":"Qoidalar va belgilarni (signs) tushuntirasiz: You must fasten your seat belt. You mustn't smoke here. mustn't (mumkin emas) va don't have to (shart emas) ni adashtirmaysiz, mustn't ni to'g'ri talaffuz qilasiz.","words":[{"en":"sign","uz":"belgi, yozuv (ko'rsatkich)","ipa":"saɪn"},{"en":"smoke","uz":"chekmoq; tutun","ipa":"sməʊk"},{"en":"fasten","uz":"taqmoq, mahkamlamoq","ipa":"ˈfɑː.sən"},{"en":"seat belt","uz":"xavfsizlik kamari","ipa":"ˈsiːt belt"},{"en":"switch off","uz":"o'chirmoq (telefon, chiroq)","ipa":"ˌswɪtʃ ˈɒf"},{"en":"rule","uz":"qoida","ipa":"ruːl"},{"en":"rubbish","uz":"axlat, chiqindi","ipa":"ˈrʌb.ɪʃ"},{"en":"grass","uz":"o'tloq, maysa","ipa":"ɡrɑːs"},{"en":"be allowed to","uz":"ruxsat berilgan bo'lmoq","ipa":"bi əˈlaʊd tə"},{"en":"danger","uz":"xavf","ipa":"ˈdeɪn.dʒə"}],"summary":["must + V1 — kuchli majburiyat, qoida: You must fasten your seat belt. (must to, musts ❌)","mustn't + V1 — taqiq: You mustn't smoke. Talaffuz: \"masnt\". (don't must ❌)","mustn't (mumkin emas) ≠ don't have to (shart emas): You mustn't touch. / You don't have to pay.","Belgilar: NO SMOKING → mustn't smoke; SWITCH OFF PHONES → must switch off.","must ning o'tgan zamoni yo'q → had to. Savolda odatda Do I have to…?"]},{"id":"u10-l14","slug":"listening-and-speaking-announcements-and-messages","title":"Listening and speaking: announcements and messages","titleUz":"Tinglash va gapirish: e'lonlar va xabarlar","goal":"Vokzal va aeroport e'lonlarini tushunasiz (platforma, vaqt, kechikish) va ovozli xabar qoldirasiz: Hello, this is Anna. Please call me back.","words":[{"en":"announcement","uz":"e'lon (ovozli)","ipa":"əˈnaʊns.mənt"},{"en":"passenger","uz":"yo'lovchi","ipa":"ˈpæs.ɪn.dʒər"},{"en":"attention","uz":"diqqat","ipa":"əˈten.ʃən"},{"en":"voicemail","uz":"ovozli xabar","ipa":"ˈvɔɪs.meɪl"},{"en":"leave a message","uz":"xabar qoldirmoq","ipa":"liːv ə ˈmes.ɪdʒ"},{"en":"call back","uz":"qayta qo'ng'iroq qilmoq","ipa":"kɔːl bæk"}],"summary":["E'londa kalit ma'lumotlarni tuting: reys/poyezd, vaqt, platforma yoki gate, kechikish.","Telefonda: Hello, this is Anna. Xabar: sabab + Please call me back. + Thank you. Bye!","call me back — me o'rtada. Please leave a message — signaldan keyin.","Yangi so'zlar: announcement, passenger, attention, voicemail, leave a message, call back."]},{"id":"u10-l8","slug":"writing-a-message-or-email","title":"Writing a message or email","titleUz":"Xabar va xat yozish","goal":"Do'stingizga norasmiy xat (Hi Anna, Thanks for your email… Write soon! Love, Malika) va mehmonxona yoki maktabga qisqa rasmiyroq xat (Dear Mr Smith, I would like to… Kind regards) yozasiz. Bosh harf, vergul va and, but, because, so bilan bog'langan gaplar yozishni o'rganasiz.","words":[{"en":"reply","uz":"javob; javob bermoq","ipa":"rɪˈplaɪ"},{"en":"subject","uz":"mavzu (xat qatori)","ipa":"ˈsʌb.dʒɪkt"},{"en":"attach","uz":"(faylni) biriktirmoq","ipa":"əˈtætʃ"},{"en":"Dear…","uz":"Hurmatli… (xatda murojaat)","ipa":"dɪə"},{"en":"Best wishes","uz":"Eng yaxshi tilaklar bilan (xat oxirida)","ipa":"ˌbest ˈwɪʃ.ɪz"},{"en":"Kind regards","uz":"Hurmat bilan (xat oxirida)","ipa":"ˌkaɪnd rɪˈɡɑːdz"},{"en":"look forward to","uz":"intiqlik bilan kutmoq","ipa":"lʊk ˈfɔː.wəd tə"},{"en":"let me know","uz":"menga xabar bering","ipa":"ˌlet mi ˈnəʊ"},{"en":"greetings","uz":"salom, ko'rishgan joydan salom (xatda)","ipa":"ˈɡriː.tɪŋz"},{"en":"write back","uz":"javob yozmoq","ipa":"ˌraɪt ˈbæk"}],"summary":["Xat: murojaat → kirish → asosiy qism → yakun → xayrlashuv + ism.","Do'stga: Hi …, / Thanks for your message! / Write soon! / Love, Best wishes,","Rasmiyroq: Dear Sir or Madam, / I would like to… / Could you…? / I look forward to hearing from you. / Kind regards,","look forward to + -ing; bosh harf: I, Monday, July, English, Tashkent.","Bog'lovchilar: and, but, because (sabab), so (natija), also."]},{"id":"u10-l15","slug":"reading-and-writing-a-postcard-and-an-email","title":"Reading and writing: a postcard and an email","titleUz":"O'qish va yozish: otkritka va xat","goal":"Sayohatdan yozilgan otkritka va qisqa xatni o'qib tushunasiz va o'zingiz otkritka yozasiz: joy, ob-havo, nima qildingiz va keyin nima qilasiz.","words":[{"en":"beach","uz":"plyaj","ipa":"biːtʃ"},{"en":"sunset","uz":"quyosh botishi","ipa":"ˈsʌn.set"},{"en":"lovely","uz":"ajoyib, yoqimli","ipa":"ˈlʌv.li"},{"en":"miss","uz":"sog'inmoq","ipa":"mɪs"},{"en":"stamp","uz":"marka (pochta)","ipa":"stæmp"},{"en":"address","uz":"manzil","ipa":"əˈdres"}],"summary":["Otkritka tuzilishi: Dear… → Greetings from… → ob-havo → Yesterday we… → Tomorrow we are going to… → I miss you → Love,","O'tgan voqealar: Yesterday we visited / walked…; reja: Tomorrow we are going to…","Xatda taklif: Why don't you come next summer? Tugatish: Best wishes, / Love,","Yangi so'zlar: beach, sunset, lovely, miss, stamp, address."]},{"id":"u10-l11","slug":"travel-and-health-final-review","title":"Travel and health: final review","titleUz":"Sayohat va sog'liq: yakuniy takror","goal":"Birlikdagi hamma narsani takrorlaysiz: ob-havo, vokzal va aeroport, mehmonxona, will / going to, salomatlik maslahati, have to, must / mustn't va qisqa xabar yozish.","words":[{"en":"journey","uz":"safar, yo'l","ipa":"ˈdʒɜː.ni"},{"en":"souvenir","uz":"esdalik sovg'a","ipa":"ˌsuː.vəˈnɪər"},{"en":"safe","uz":"xavfsiz","ipa":"seɪf"},{"en":"hope","uz":"umid qilmoq","ipa":"həʊp"}],"summary":["will — shu zahotiy qaror va va'da; going to — reja va belgi asosidagi bashorat.","should / shouldn't — maslahat; have to / don't have to — majburiyat / shart emas.","must — shart, mustn't — taqiqlangan; ulardan keyin to qo'yilmaydi.","Mehmonxona va xabar: Could I…? Could you…?, Dear… / Best wishes."]}]},{"id":"u11","n":11,"title":"Experiences","titleUz":"Tajribalar va yakun: Present Perfect va barcha zamonlar","description":"Present Perfect bilan tanishuv, ever / never, been / gone, fe'l + to / -ing, harakat predloglari, phrasal verbs, A1 yakuniy takrori.","canDo":["Hayotimdagi tajribalar haqida (Have you ever…?) gapiraman","Present Perfect va Past Simple farqini bilaman","want to / enjoy -ing kabi birikmalarni to'g'ri ishlataman","Kundalik phrasal verblarni tushunaman"],"lessons":[{"id":"u11-l1","slug":"have-you-ever","title":"Have you ever…?","titleUz":"Present Perfect: Have you ever…?","goal":"Hayotingizdagi tajribalar haqida gapirasiz va so'raysiz: Have you ever been to…? — Yes, I have. / No, I haven't. I've never… Yangi zamon — Present Perfect (have / has + V3) bilan tanishasiz.","words":[{"en":"ever","uz":"hech, qachondir (savolda)","ipa":"ˈevə"},{"en":"many times","uz":"ko'p marta","ipa":"ˈmeni taɪmz"},{"en":"desert","uz":"sahro","ipa":"ˈdez.ət"},{"en":"ocean","uz":"okean","ipa":"ˈəʊʃn"},{"en":"try","uz":"tatib ko'rmoq, sinab ko'rmoq","ipa":"traɪ"},{"en":"ride – rode – ridden","uz":"minmoq (ot, tuya, velosiped)","ipa":"raɪd – rəʊd – ˈrɪdn"},{"en":"foreign","uz":"xorijiy, chet ellik","ipa":"ˈfɒrən"},{"en":"famous","uz":"mashhur","ipa":"ˈfeɪməs"},{"en":"experience","uz":"tajriba, hodisa","ipa":"ɪkˈspɪəriəns"},{"en":"in my life","uz":"hayotimda","ipa":"ɪn maɪ laɪf"}],"summary":["Present Perfect = have / has + V3 — hayotdagi tajriba, qachon bo'lgani muhim emas: I've been to Samarkand.","Savol: Have you ever + V3? → Yes, I have. / No, I haven't. (Yes, I did emas!)","Inkor: I've never + V3 yoki I haven't + V3 — never bilan not birga ishlatilmaydi.","V3: been, seen, eaten, done, met, read, ridden, flown; to'g'ri fe'llarda V3 = -ed.","Necha marta: once, twice, three times, many times — gap oxirida."]},{"id":"u11-l2","slug":"past-participles-been-or-gone","title":"Past participles; been or gone?","titleUz":"3-shakl fe'llar va been / gone","goal":"25 dan ortiq noto'g'ri fe'lning V3 shaklini guruhlab yodlaysiz (written, spoken, lost, broken…), I've lost my keys kabi \"natija hozir\" gaplarini tuzasiz va been to (borib kelgan) bilan gone to (ketgan, hali u yerda) farqini bilasiz.","words":[{"en":"lose – lost – lost","uz":"yo'qotmoq","ipa":"luːz – lɒst – lɒst"},{"en":"find – found – found","uz":"topmoq","ipa":"faɪnd – faʊnd – faʊnd"},{"en":"win – won – won","uz":"yutmoq, g'olib bo'lmoq","ipa":"wɪn – wʌn – wʌn"},{"en":"write – wrote – written","uz":"yozmoq","ipa":"raɪt – rəʊt – ˈrɪtn"},{"en":"speak – spoke – spoken","uz":"gapirmoq","ipa":"spiːk – spəʊk – ˈspəʊkən"},{"en":"break – broke – broken","uz":"sindirmoq","ipa":"breɪk – brəʊk – ˈbrəʊkən"},{"en":"forget – forgot – forgotten","uz":"unutmoq","ipa":"fəˈɡet – fəˈɡɒt – fəˈɡɒtn"},{"en":"drive – drove – driven","uz":"(mashina) haydamoq","ipa":"draɪv – drəʊv – ˈdrɪvn"},{"en":"wear – wore – worn","uz":"kiymoq, taqmoq","ipa":"weə – wɔː – wɔːn"},{"en":"swim – swam – swum","uz":"suzmoq","ipa":"swɪm – swæm – swʌm"}],"summary":["V3 ni guruhlab yodlang: A-A-A (put), A-B-B (bought, lost, found), A-B-C (written, spoken, broken), A-B-A (come).","have + V3, hech qachon have + V2 emas: I've taken (✅), I've took (❌).","Present Perfect natija va yangilik uchun ham: I've lost my keys. We've bought a flat!","has been to = borib kelgan (hozir qaytgan); has gone to = ketgan (hali u yerda)."]},{"id":"u11-l12","slug":"present-perfect-short-answers-and-never-ever","title":"Present Perfect: short answers and never / ever","titleUz":"Present Perfect: qisqa javoblar, ever va never","goal":"Have you ever…? savoliga to'g'ri qisqa javob berasiz (Yes, I have. / No, I haven't.) va ever bilan never o'rnini bilasiz: Have you ever seen snow? — No, never. I've never seen snow.","words":[{"en":"island","uz":"orol","ipa":"ˈaɪlənd"},{"en":"zoo","uz":"hayvonot bog'i","ipa":"zuː"},{"en":"elephant","uz":"fil","ipa":"ˈelɪfənt"},{"en":"snow","uz":"qor","ipa":"snəʊ"},{"en":"boat","uz":"qayiq, kema","ipa":"bəʊt"},{"en":"helicopter","uz":"vertolyot","ipa":"ˈhelɪkɒptə"}],"summary":["Qisqa javob savoldagi yordamchi fe'l bilan: Have you…? → Yes, I have. / No, I haven't.","he / she / it bilan: Has she…? → Yes, she has. / No, she hasn't.","ever — savolda: Have you ever…? never — darak gapda: I've never… (not kerak emas).","Yangi so'zlar: island, zoo, elephant, snow, boat, helicopter."]},{"id":"u11-l3","slug":"present-perfect-or-past-simple","title":"Present Perfect or Past Simple?","titleUz":"Present Perfect yoki Past Simple?","goal":"Ikki zamonni to'g'ri tanlaysiz: vaqt aytilmasa — Present Perfect (I've been to Bukhara), aniq o'tgan vaqt bo'lsa — Past Simple (I went there last summer). Tabiiy suhbat quriladi: Have you ever…? → When did you…? Did you like it?","words":[{"en":"mountain","uz":"tog'","ipa":"ˈmaʊntən"},{"en":"hundreds of","uz":"yuzlab","ipa":"ˈhʌndrədz əv"},{"en":"memory","uz":"esdalik, xotira","ipa":"ˈmeməri"},{"en":"tourist","uz":"turist, sayyoh","ipa":"ˈtʊərɪst"},{"en":"guide","uz":"gid, yo'lboshlovchi","ipa":"ɡaɪd"},{"en":"local","uz":"mahalliy","ipa":"ˈləʊkl"},{"en":"amazing","uz":"ajoyib, hayratlanarli","ipa":"əˈmeɪzɪŋ"},{"en":"unforgettable","uz":"unutilmas","ipa":"ˌʌnfəˈɡetəbl"},{"en":"waterfall","uz":"sharshara","ipa":"ˈwɔːtəfɔːl"},{"en":"festival","uz":"festival, bayram","ipa":"ˈfestɪvl"}],"summary":["Present Perfect — vaqt aytilmaydi: tajriba (I've been to Khiva) yoki yangilik (I've lost my phone).","Past Simple — aniq tugagan vaqt: yesterday, last…, …ago, in 2020, when I was…","When…? savoli doim Past Simple: When did you go? (When have you been ❌)","Suhbat qolipi: Have you ever…? → Yes, I have. → When did you…? Did you like it?"]},{"id":"u11-l13","slug":"how-many-times-once-twice-three-times","title":"How many times? once, twice, three times","titleUz":"Necha marta? once, twice, three times","goal":"Necha marta bo'lganini so'raysiz va aytasiz: How many times have you been to Khiva? — Twice. Hamda so far, again, the first time iboralarini ishlatasiz.","words":[{"en":"a few times","uz":"bir necha marta","ipa":"ə fjuː taɪmz"},{"en":"again","uz":"yana, qayta","ipa":"əˈɡen"},{"en":"so far","uz":"hozirgacha","ipa":"səʊ fɑː"},{"en":"the first time","uz":"birinchi marta","ipa":"ðə fɜːst taɪm"},{"en":"how many times","uz":"necha marta","ipa":"haʊ ˈmeni taɪmz"}],"summary":["Necha marta: once, twice, three times, a few times, many times — gap oxirida.","Savol: How many times + have / has + ega + V3? Javob: Twice.","so far — hozirgacha; again — yana; the first time — birinchi marta.","Yangi so'zlar: a few times, again, so far, the first time, how many times."]},{"id":"u11-l9","slug":"sharing-experiences-have-you-ever","title":"Sharing experiences: have you ever…?","titleUz":"Tajriba almashish: Have you ever…?","goal":"Suhbatdoshingizdan tajribasi haqida so'raysiz (Have you ever…?), o'zingiz haqingizda aytasiz (I've been to… / I've never…) va tafsilotlarni Past Simple bilan davom ettirasiz. been va gone farqini ham bilib olasiz.","words":[{"en":"trip","uz":"sayohat, safar","ipa":"trɪp"},{"en":"lucky","uz":"omadli","ipa":"ˈlʌk.i"},{"en":"adventure","uz":"sarguzasht","ipa":"ədˈven.tʃər"},{"en":"postcard","uz":"otkritka, pochta kartochkasi","ipa":"ˈpəʊstkɑːd"},{"en":"souvenir","uz":"esdalik sovg'a","ipa":"ˌsuːvəˈnɪə"}],"summary":["Tajriba haqida so'rash: Have you ever + V3? — javob Yes, I have. / No, I haven't.","been — borib qaytgan; gone — ketgan, hali qaytmagan.","Tafsilot va aniq vaqt bo'lsa — Past Simple: When did you go? I went in 2023.","Yangi so'zlar: trip, lucky, adventure."]},{"id":"u11-l4","slug":"prepositions-of-movement","title":"Prepositions of movement","titleUz":"Harakat predloglari: into, across, along…","goal":"Harakat yo'nalishini aniq aytasiz: into, out of, up, down, across, along, through, over, under, past, towards, around. Yo'l ko'rsatasiz va sayr haqida gapirasiz: Go along the river, across the bridge and through the park.","words":[{"en":"bridge","uz":"ko'prik","ipa":"brɪdʒ"},{"en":"river","uz":"daryo","ipa":"ˈrɪvə"},{"en":"tunnel","uz":"tunnel","ipa":"ˈtʌnl"},{"en":"path","uz":"so'qmoq, yo'lak","ipa":"pɑːθ"},{"en":"hill","uz":"tepalik","ipa":"hɪl"},{"en":"stairs","uz":"zina","ipa":"steəz"},{"en":"wall","uz":"devor","ipa":"wɔːl"},{"en":"canal","uz":"kanal, ariq","ipa":"kəˈnæl"},{"en":"bakery","uz":"novvoyxona, nonvoyxona","ipa":"ˈbeɪkəri"},{"en":"follow","uz":"ergashmoq, orqasidan bormoq","ipa":"ˈfɒləʊ"}],"summary":["Joy predloglari — qayerda? (in, on); harakat predloglari — qayoqqa? (into, out of, onto, off).","across — kesib o'tib, along — bo'ylab, through — ichidan o'tib, over / under — ustidan / ostidan.","up / down, past, towards, around, from… to — yo'l ko'rsatishda eng kerakli so'zlar.","get on / off the bus, train; get into / out of a car, taxi. go home — predlogsiz."]},{"id":"u11-l5","slug":"want-to-enjoy-ing","title":"want to, enjoy -ing","titleUz":"Fe'l + to yoki -ing: want to, enjoy -ing","goal":"Ikki fe'lni to'g'ri bog'laysiz: want / need / decide / hope + to (I want to learn) va enjoy / finish / practise / don't mind + -ing (I enjoy cooking). I want you to come kabi gaplarni ham tuzasiz va rejalar, orzular haqida gapirasiz.","words":[{"en":"organise","uz":"tashkil qilmoq","ipa":"ˈɔːɡənaɪz"},{"en":"shout","uz":"baqirmoq","ipa":"ʃaʊt"},{"en":"go hiking","uz":"tog'da piyoda sayr qilmoq","ipa":"ɡəʊ ˈhaɪkɪŋ"},{"en":"refuse","uz":"rad qilmoq, rad etmoq","ipa":"rɪˈfjuːz"},{"en":"agree","uz":"rozi bo'lmoq","ipa":"əˈɡriː"},{"en":"offer","uz":"taklif qilmoq","ipa":"ˈɒfə"},{"en":"prefer","uz":"afzal ko'rmoq","ipa":"prɪˈfɜː"},{"en":"report","uz":"hisobot","ipa":"rɪˈpɔːt"},{"en":"practise","uz":"mashq qilmoq","ipa":"ˈpræktɪs"},{"en":"I don't mind","uz":"qarshi emasman, menga farqi yo'q","ipa":"aɪ dəʊnt maɪnd"}],"summary":["want, would like, need, hope, plan, decide, learn, promise, agree, offer + to + V1: I've decided to learn Chinese.","enjoy, finish, stop, practise, (don't) mind, go + V-ing: I enjoy cooking. Let's go shopping.","like, love, hate, start, begin — ikkalasi ham to'g'ri; lekin would like — faqat to.","Boshqa odam haqida: want + kishi + to + V1 — I want you to come (I want that you come ❌)."]},{"id":"u11-l6","slug":"when-before-after-or","title":"when, before, after, or","titleUz":"Gaplarni bog'lash: when, before, after, or","goal":"Ikki gapni vaqt bo'yicha bog'laysiz: When I was a child, I lived in Andijan. After I finished school, I went to university. Kelasi zamonda When I get home, I'll call you (will get emas!) qoidasini bilasiz va or ni savol va inkorda to'g'ri ishlatasiz.","words":[{"en":"army","uz":"armiya","ipa":"ˈɑːmi"},{"en":"graduate","uz":"(oliy o'quv yurtini) bitirmoq","ipa":"ˈɡrædʒueɪt"},{"en":"university","uz":"universitet","ipa":"ˌjuːnɪˈvɜːsəti"},{"en":"business","uz":"biznes, ish","ipa":"ˈbɪznəs"},{"en":"story","uz":"hikoya, voqea","ipa":"ˈstɔːri"},{"en":"grandparents","uz":"bobo va buvi","ipa":"ˈɡrænpeərənts"},{"en":"course","uz":"kurs","ipa":"kɔːs"},{"en":"career","uz":"martaba, kasb yo'li","ipa":"kəˈrɪə"},{"en":"grandchildren","uz":"nevaralar","ipa":"ˈɡræntʃɪldrən"},{"en":"join","uz":"qo'shilmoq, a'zo bo'lmoq","ipa":"dʒɔɪn"}],"summary":["when, before, after ikki gapni vaqt bo'yicha bog'laydi; bu qism boshida bo'lsa — vergul: When I was a child, I…","before / after + gap yoki ot: after I finished school / after school (after of ❌).","Kelajak haqida: when / before / after + Present Simple, asosiy gapda will: When I get home, I'll call you.","or — savolda tanlov (tea or coffee?) va inkorda: I don't eat meat or fish."]},{"id":"u11-l7","slug":"everyday-phrasal-verbs","title":"Everyday phrasal verbs","titleUz":"Kundalik phrasal verbs: get up, put on…","goal":"Kundalik hayotdagi eng kerakli phrasal verbs ni ishlatasiz: wake up, put on, take off, turn on / off, look for, look after, try on, pick up, throw away. Put it on (put on it emas) qoidasini bilasiz va open the light ❌ kabi xatolardan qutulasiz.","words":[{"en":"go out","uz":"(uydan) chiqmoq; sayrga chiqmoq","ipa":"ɡəʊ aʊt"},{"en":"put on","uz":"kiymoq","ipa":"pʊt ɒn"},{"en":"take off","uz":"yechmoq","ipa":"teɪk ɒf"},{"en":"come back","uz":"qaytib kelmoq","ipa":"kʌm bæk"},{"en":"turn off","uz":"o'chirmoq","ipa":"tɜːn ɒf"},{"en":"look for","uz":"qidirmoq","ipa":"lʊk fɔː"},{"en":"look after","uz":"qaramoq, g'amxo'rlik qilmoq","ipa":"lʊk ˈɑːftə"},{"en":"give back","uz":"qaytarib bermoq","ipa":"ɡɪv bæk"},{"en":"switch on","uz":"yoqmoq (chiroq, asbob)","ipa":"swɪtʃ ɒn"},{"en":"throw away","uz":"tashlab yubormoq","ipa":"θrəʊ əˈweɪ"}],"summary":["Phrasal verb = fe'l + kichik so'z, yangi ma'no: look for — qidirmoq, look after — qaramoq.","Har kungi: wake up, get up, put on, take off, turn on / off, go out, come back.","Uy va do'kon: try on, pick up, throw away, give back, fill in.","Olmosh o'rtada: turn it off, put them on (turn off it ❌); lekin look for it.","Chiroq va texnika — turn on / off (open / close the light ❌); put on — harakat, wear — holat."]},{"id":"u11-l10","slug":"mixed-conversations-real-life-situations","title":"Mixed conversations: real-life situations","titleUz":"Aralash suhbatlar: hayotiy vaziyatlar","goal":"Haqiqiy suhbatda zamonlar aralash keladi: kim ekaningiz (Present Simple), hozir nima qilayotganingiz (Continuous), nima bo'lgani (Past Simple, Present Perfect) va rejalaringiz (going to, will). Vokzalda va kafeda shunday suhbat qurasiz.","words":[{"en":"platform","uz":"platforma (vokzalda)","ipa":"ˈplæt.fɔːm"},{"en":"delayed","uz":"kechikkan","ipa":"dɪˈleɪd"},{"en":"seat","uz":"o'rindiq, joy","ipa":"siːt"},{"en":"nervous","uz":"xavotirli","ipa":"ˈnɜː.vəs"},{"en":"free","uz":"bo'sh (joy)","ipa":"friː"},{"en":"Excuse me","uz":"Kechirasiz (murojaat)","ipa":"ɪkˈskjuːs miː"}],"summary":["Bitta suhbatda zamonlar aralashadi: odat/fakt — Simple, hozir — Continuous, o'tmish — Past Simple / Present Perfect, kelajak — going to / will.","Aniq vaqt (ago, yesterday) bo'lsa — Past Simple; tajriba — Present Perfect.","Vokzal iboralari: Is this seat free? It's delayed. Nice to meet you.","Yangi so'zlar: platform, delayed, seat, nervous, free, Excuse me."]},{"id":"u11-l14","slug":"listening-and-speaking-my-experiences","title":"Listening and speaking: my experiences","titleUz":"Tinglash va gapirish: mening tajribalarim","goal":"Tajriba haqidagi qisqa suhbatlarni tinglab tushunasiz va o'zingiz gapirasiz: Have you ever…? — Yes, I have. I went there… — How about you?","words":[{"en":"That sounds fun!","uz":"Qiziq ekan!","ipa":"ðæt saʊndz fʌn"},{"en":"How about you?","uz":"Siz-chi?","ipa":"haʊ əˈbaʊt juː"},{"en":"Me neither","uz":"Men ham (yo'q)","ipa":"miː ˈnaɪðə"},{"en":"by the way","uz":"aytgancha","ipa":"baɪ ðə weɪ"},{"en":"I'd love to","uz":"Xursand bo'lardim","ipa":"aɪd lʌv tuː"},{"en":"take a photo","uz":"rasmga olmoq","ipa":"teɪk ə ˈfəʊtəʊ"}],"summary":["Suhbatda tinglang: savol → qisqa javob → tafsilot (Past Simple).","Yaxshi javob: Yes, I have. + tafsilot + How about you?","Inkorga qo'shilish: Me neither. Qiziqish: That sounds fun!","Yangi iboralar: by the way, I'd love to, take a photo."]},{"id":"u11-l8","slug":"a1-review-all-the-tenses","title":"A1 review: all the tenses","titleUz":"A1 yakuniy takrori: barcha zamonlar","goal":"A1 darajasidagi barcha zamonlarni bitta tizimga solasiz: Present Simple, Present Continuous, Past Simple, going to, will, Present Perfect. Signal so'zlarga qarab zamonni tanlaysiz, yordamchi fe'llarni (do / does / did / am / is / are / will / have / has) adashtirmaysiz va o'zingiz haqida o'tmish, hozir va kelajakni qo'shib gapirasiz.","words":[{"en":"progress","uz":"rivojlanish, o'sish","ipa":"ˈprəʊɡres"},{"en":"goal","uz":"maqsad","ipa":"ɡəʊl"},{"en":"mistake","uz":"xato","ipa":"mɪˈsteɪk"},{"en":"improve","uz":"yaxshilamoq, yaxshilanmoq","ipa":"ɪmˈpruːv"},{"en":"confident","uz":"o'ziga ishongan","ipa":"ˈkɒnfɪdənt"},{"en":"fluent","uz":"erkin, ravon (tilda)","ipa":"ˈfluːənt"},{"en":"level","uz":"daraja","ipa":"ˈlevl"},{"en":"review","uz":"takrorlamoq; takrorlash","ipa":"rɪˈvjuː"},{"en":"achieve","uz":"erishmoq","ipa":"əˈtʃiːv"},{"en":"do your best","uz":"qo'lingizdan kelganini qilmoq","ipa":"duː jɔː best"}],"summary":["Present Simple — odat (I work), Present Continuous — hozir va kelishilgan reja (I'm working).","Past Simple — aniq tugagan vaqt (I worked yesterday), Present Perfect — vaqtsiz tajriba va yangilik (I've worked abroad).","Kelajak: going to — niyat va belgi, will — shu zahoti qaror, taklif, taxmin.","Yordamchi fe'l qoidasi: do / does / did / will + V1, am / is / are + V-ing, have / has + V3.","A1 tugadi! Keyingi qadam — A2: bu zamonlarni yanada erkin va murakkab gaplarda ishlatish."]},{"id":"u11-l15","slug":"reading-and-writing-an-email-about-my-experiences","title":"Reading and writing: an email about my experiences","titleUz":"O'qish va yozish: tajribalarim haqida xat","goal":"Tajribalar haqidagi qisqa xatlarni o'qib tushunasiz va o'zingiz do'stingizga xat yozasiz: salomlashish, tajriba (I've been to…), tafsilot (I went…) va savol (Have you ever…?).","words":[{"en":"Dear…","uz":"Aziz… (xat boshida)","ipa":"dɪə"},{"en":"write back","uz":"javob yozmoq","ipa":"raɪt bæk"},{"en":"Thanks for your email","uz":"Xatingiz uchun rahmat","ipa":"θæŋks fə jɔː ˈiːmeɪl"},{"en":"Best wishes","uz":"Eng yaxshi tilaklar bilan","ipa":"best ˈwɪʃɪz"},{"en":"beach","uz":"plyaj","ipa":"biːtʃ"},{"en":"email","uz":"elektron xat","ipa":"ˈiːmeɪl"}],"summary":["Xat tuzilishi: salom → rahmat → tajriba (Present Perfect) → tafsilot (Past Simple) → savol → xayrlashuv.","Tajriba: I have been to… / I have never…; tafsilot: I went there last summer.","Foydali iboralar: Dear…, Thanks for your email, Please write back, Best wishes."]},{"id":"u11-l11","slug":"elementary-final-review","title":"Elementary: final review","titleUz":"Elementary: yakuniy takror","goal":"Elementary darajasini yakunlaysiz: Present Simple, Present Continuous, Past Simple, going to, will, Present Perfect va modal fe'llar can, have to, must, should — hammasini bitta kichik takrorda mustahkamlaysiz.","words":[{"en":"tense","uz":"zamon (grammatikada)","ipa":"tens"},{"en":"sentence","uz":"gap","ipa":"ˈsen.təns"},{"en":"grammar","uz":"grammatika","ipa":"ˈɡræm.ər"},{"en":"exam","uz":"imtihon","ipa":"ɪɡˈzæm"},{"en":"correct","uz":"to'g'ri (javob, gap)","ipa":"kəˈrekt"}],"summary":["Zamonlar: Simple — odat, Continuous — hozir, Past Simple — aniq o'tmish, Present Perfect — tajriba, going to / will — kelajak.","Modallar: can (qila olish), have to / must (majburiyat), should (maslahat) + oddiy fe'l.","Oltin qoida: yordamchi fe'ldan keyin to'g'ri shakl (V1, V-ing, V3).","Yangi so'zlar: tense, sentence, grammar, exam, correct."]}]}]},{"id":"a2","slug":"pre-intermediate","title":"Pre-Intermediate","cefr":"A2","text":"Kundalik mavzularda gaplasha olaman, lekin xatolarim ko'p.","units":[{"id":"u12","n":12,"title":"Stories from the past","titleUz":"O'tmish hikoyalari: Past Simple, Past Continuous, used to","description":"Past Simple takrori, Past Continuous, used to, when / while va hikoya aytish.","canDo":["Voqealarni ketma-ket hikoya qilaman","Past Simple va Past Continuous ni ajrata olaman","Avvalgi odatlarimni (used to) aytaman","Sabab va qarama-qarshilikni bildiraman"],"lessons":[{"id":"u12-l1","slug":"past-simple-regular-and-irregular","title":"Past Simple: regular and irregular","titleUz":"Past Simple takrori: to'g'ri va noto'g'ri fe'llar","goal":"Past Simple ni mustahkamlaysiz: to'g'ri fe'llarga -ed qo'shish qoidalari (study – studied, stop – stopped), -ed ning uch xil o'qilishi, eng ko'p ishlatiladigan noto'g'ri fe'llar (went, saw, ate, bought, met, left…) va was / were. O'tgan hafta oxiri haqida 6–8 gaplik hikoya yoza olasiz.","words":[{"en":"arrive","uz":"yetib kelmoq","ipa":"əˈraɪv"},{"en":"decide","uz":"qaror qilmoq","ipa":"dɪˈsaɪd"},{"en":"spend – spent","uz":"sarflamoq; (vaqt) o'tkazmoq","ipa":"spend – spent"},{"en":"leave – left","uz":"ketmoq; tark etmoq","ipa":"liːv – left"},{"en":"meet – met","uz":"uchrashmoq, tanishmoq","ipa":"miːt – met"},{"en":"wake up – woke up","uz":"uyg'onmoq","ipa":"weɪk ʌp – wəʊk ʌp"},{"en":"stay","uz":"qolmoq; turmoq (mehmonxonada)","ipa":"steɪ"},{"en":"travel","uz":"sayohat qilmoq","ipa":"ˈtrævl"},{"en":"catch – caught","uz":"ulgurmoq (transport); tutmoq","ipa":"kætʃ – kɔːt"},{"en":"weekend","uz":"hafta oxiri","ipa":"ˌwiːkˈend"}],"summary":["Past Simple tugagan o'tmish uchun: I visited…, we went…. Hamma shaxslarda fe'l bir xil.","To'g'ri fe'llar: +ed (worked), +d (lived), -ied (studied), undosh ikkilanadi (stopped). Noto'g'ri fe'llarni yodlash kerak (go – went, buy – bought).","-ed uch xil o'qiladi: /t/ (worked), /d/ (played), /ɪd/ (wanted) — alohida \"ed\" bo'g'ini faqat t / d dan keyin.","be → was (I, he, she, it) va were (you, we, they). Hech qachon tushirib qoldirmang."]},{"id":"u12-l2","slug":"past-simple-questions-and-negatives","title":"Past Simple: questions and negatives","titleUz":"Past Simple: savol va inkor, ago va vaqt iboralari","goal":"Past Simple da didn't bilan inkor gap (I didn't go), Did…? bilan savol (Did you see him?), Wh- savollar (Where did you go?), was / were ning inkor va savol shakllarini tuzasiz va yesterday, last week, two days ago, in 2019 kabi vaqt iboralarini to'g'ri ishlatasiz.","words":[{"en":"ago","uz":"oldin (hozirdan hisoblab)","ipa":"əˈɡəʊ"},{"en":"recently","uz":"yaqinda, ko'p o'tmay","ipa":"ˈriːsntli"},{"en":"last night","uz":"kecha kechqurun","ipa":"lɑːst naɪt"},{"en":"the day before yesterday","uz":"avvalgi kuni (kechadan oldingi kun)","ipa":"ðə deɪ bɪˈfɔː ˈjestədeɪ"},{"en":"a long time ago","uz":"ancha oldin","ipa":"ə lɒŋ taɪm əˈɡəʊ"},{"en":"during","uz":"davomida","ipa":"ˈdjʊərɪŋ"},{"en":"all day","uz":"kun bo'yi","ipa":"ɔːl deɪ"},{"en":"remember","uz":"eslamoq, yodda tutmoq","ipa":"rɪˈmembə"},{"en":"enjoy","uz":"yoqtirmoq, zavqlanmoq","ipa":"ɪnˈdʒɔɪ"},{"en":"miss","uz":"ulgurmaslik, o'tkazib yubormoq","ipa":"mɪs"}],"summary":["Inkor: ega + didn't + V1 (I didn't go). Asosiy fe'l o'tgan shaklga o'tmaydi.","Savol: Did + ega + V1? (Did you see it?). Qisqa javob: Yes, I did. / No, I didn't. Wh-: Where did you go?","be bilan did kerak emas: Was she…? I wasn't… Were you…? We weren't…","Vaqt: yesterday, last week, two days ago, in 2019, on Monday. ago davrdan keyin turadi; last oldida in / on yo'q.","Who / What egasi bo'lsa, did ishlatilmaydi: Who called you?"]},{"id":"u12-l3","slug":"past-continuous","title":"Past Continuous","titleUz":"Past Continuous: was / were + -ing","goal":"Past Continuous (was / were + V-ing) ni tuzasiz va ishlatasiz: o'tmishdagi aniq paytda davom etayotgan ish-harakatni (At eight I was cooking) aytasiz, -ing imlosini bilasiz va Past Simple bilan farqini tushunasiz.","words":[{"en":"crowded","uz":"gavjum, odam ko'p","ipa":"ˈkraʊdɪd"},{"en":"queue","uz":"navbat","ipa":"kjuː"},{"en":"wait for","uz":"kutmoq","ipa":"weɪt fɔː"},{"en":"chat","uz":"suhbatlashmoq, gaplashmoq","ipa":"tʃæt"},{"en":"cross","uz":"kesib o'tmoq","ipa":"krɒs"},{"en":"noise","uz":"shovqin","ipa":"nɔɪz"},{"en":"pour","uz":"quymoq; (yomg'ir) sharros quymoq","ipa":"pɔː"},{"en":"asleep","uz":"uxlab yotgan","ipa":"əˈsliːp"},{"en":"at that moment","uz":"o'sha paytda, shu zahoti","ipa":"æt ðæt ˈməʊmənt"},{"en":"all evening","uz":"kechqurun bo'yi","ipa":"ɔːl ˈiːvnɪŋ"}],"summary":["Past Continuous = was / were + V-ing: o'tmishdagi aniq paytda davom etayotgan ish (At nine I was cooking).","Inkor: wasn't / weren't + V-ing; savol: Was / Were + ega + V-ing? — did ishlatilmaydi.","-ing imlosi: make → making, run → running, lie → lying, study → studying.","Jarayon (was cooking) va tugagan ish (cooked) ni farqlang. Holat fe'llari (know, like, want) Continuous da ishlatilmaydi."]},{"id":"u12-l4","slug":"past-simple-or-past-continuous","title":"Past Simple or Past Continuous?","titleUz":"Past Simple yoki Past Continuous? when va while","goal":"Ikki zamonni bir gapda ishlatasiz: uzoq davom etgan ish (Past Continuous) va uni to'xtatgan qisqa voqea (Past Simple): I was walking home when I saw an accident. when va while ning farqini bilasiz va ikki parallel ishni ham ayta olasiz.","words":[{"en":"accident","uz":"halokat, baxtsiz hodisa","ipa":"ˈæksɪdənt"},{"en":"suddenly","uz":"birdan, to'satdan","ipa":"ˈsʌdənli"},{"en":"ring – rang","uz":"jiringlamoq; qo'ng'iroq qilmoq","ipa":"rɪŋ – ræŋ"},{"en":"fall – fell","uz":"yiqilmoq, tushmoq","ipa":"fɔːl – fel"},{"en":"break down","uz":"buzilmoq (mashina)","ipa":"breɪk daʊn"},{"en":"shout","uz":"baqirmoq","ipa":"ʃaʊt"},{"en":"notice","uz":"payqamoq, sezmoq","ipa":"ˈnəʊtɪs"},{"en":"hurt","uz":"og'rimoq; jarohatlamoq","ipa":"hɜːt"},{"en":"lights went out","uz":"chiroq o'chdi","ipa":"laɪts went aʊt"},{"en":"on my way","uz":"yo'lda ketayotib","ipa":"ɒn maɪ weɪ"}],"summary":["Past Continuous — fon, davom etayotgan ish (was walking); Past Simple — to'satdan bo'lgan qisqa voqea (saw, rang).","Namuna: I was walking home when I saw an accident.","while + uzun ish (While I was cooking…); when + qisqa voqea (…when the phone rang).","Ikkala ish ham bir vaqtda davom etgan bo'lsa — ikkalasi Past Continuous: While I was cooking, he was watching TV.","Gap boshida when / while bo'lsa, vergul qo'yiladi: While I was walking, I saw him."]},{"id":"u12-l5","slug":"used-to","title":"Used to","titleUz":"Used to: avval shunday edi","goal":"used to + V1 bilan o'tmishdagi odatlar va holatlarni aytasiz (I used to play chess every day), didn't use to va Did you use to…? shakllarini tuzasiz, used to va Past Simple ni to'g'ri tanlaysiz hamda use to / used to going kabi xatolardan qochasiz.","words":[{"en":"childhood","uz":"bolalik","ipa":"ˈtʃaɪldhʊd"},{"en":"grow up – grew up","uz":"ulg'ayib kamolga yetmoq","ipa":"ɡrəʊ ʌp – ɡruː ʌp"},{"en":"neighbourhood","uz":"mahalla, tuman","ipa":"ˈneɪbəhʊd"},{"en":"in those days","uz":"o'sha kunlarda","ipa":"ɪn ðəʊz deɪz"},{"en":"no longer","uz":"endi ... emas","ipa":"nəʊ ˈlɒŋɡə"},{"en":"change","uz":"o'zgarmoq; o'zgarish","ipa":"tʃeɪndʒ"},{"en":"traditional","uz":"an'anaviy","ipa":"trəˈdɪʃənl"},{"en":"habit","uz":"odat","ipa":"ˈhæbɪt"},{"en":"memory","uz":"xotira; esdalik","ipa":"ˈmeməri"},{"en":"village","uz":"qishloq","ipa":"ˈvɪlɪdʒ"}],"summary":["used to + V1 — o'tgan odat yoki holat, hozir endi bunday emas: I used to play chess.","Inkor va savol: didn't use to, Did you use to…? — used emas, use.","Sanalgan marta, aniq muddat va yakka voqea uchun Past Simple: I went to Paris three times.","use to (darak gapda), used to going, didn't used to — odatiy xatolar."]},{"id":"u12-l6","slug":"because-so-but-although","title":"Because, so, but, although","titleUz":"Because, so, but, although: sabab va qarama-qarshilik","goal":"Gaplarni because (sababi), so (shuning uchun), but (lekin) va although (garchi ... bo'lsa ham) bilan bog'laysiz. Uzun, ma'noli o'tmish gaplarini tuzasiz va because ... so, although ... but kabi odatiy xatolardan qochasiz.","words":[{"en":"reason","uz":"sabab","ipa":"ˈriːzn"},{"en":"result","uz":"natija","ipa":"rɪˈzʌlt"},{"en":"cancel","uz":"bekor qilmoq","ipa":"ˈkænsl"},{"en":"delay","uz":"kechiktirmoq; kechikish","ipa":"dɪˈleɪ"},{"en":"disappointed","uz":"xafa bo'lgan, umidi puchga chiqqan","ipa":"ˌdɪsəˈpɔɪntɪd"},{"en":"exhausted","uz":"juda charchagan","ipa":"ɪɡˈzɔːstɪd"},{"en":"delighted","uz":"juda xursand","ipa":"dɪˈlaɪtɪd"},{"en":"apologise","uz":"uzr so'ramoq","ipa":"əˈpɒlədʒaɪz"},{"en":"lucky","uz":"omadli","ipa":"ˈlʌki"},{"en":"sold out","uz":"sotilib bo'lgan","ipa":"səʊld aʊt"}],"summary":["because — sabab (I stayed home because I was ill); so — natija (I was ill, so I stayed home).","but — gap orasida, oldidan vergul; although — gap boshida yoki o'rtada, keyin to'liq gap.","Bitta gapda because ... so yoki although ... but birga ishlatilmaydi.","Gap boshidagi Because / Although dan keyingi bo'lakdan so'ng vergul qo'yiladi: Although it was cold, we went out."]},{"id":"u12-l7","slug":"telling-a-story","title":"Telling a story","titleUz":"Hikoya aytish: first, then, after that, finally","goal":"O'tgan voqeani tartib bilan hikoya qilasiz: first, then, after that, next, later, finally, in the end, after / before / as soon as bilan bog'laysiz, hikoyada Past Simple va Past Continuous ni to'g'ri aralashtirasiz va Guess what? What happened next? kabi iboralar bilan suhbatda hikoya aytasiz.","words":[{"en":"at first","uz":"dastlab, avvaliga","ipa":"æt fɜːst"},{"en":"in the end","uz":"oxirida, oxir-oqibat","ipa":"ɪn ði end"},{"en":"meanwhile","uz":"shu orada, shu vaqtda","ipa":"ˈmiːnwaɪl"},{"en":"luckily","uz":"omadga, baxtimizga","ipa":"ˈlʌkɪli"},{"en":"unfortunately","uz":"afsuski","ipa":"ʌnˈfɔːtʃənətli"},{"en":"happen","uz":"sodir bo'lmoq, bo'lmoq","ipa":"ˈhæpən"},{"en":"realise","uz":"anglab yetmoq","ipa":"ˈriːəlaɪz"},{"en":"as soon as","uz":"...ishi bilan","ipa":"æz suːn æz"},{"en":"shocked","uz":"hayratda, dovdirab qolgan","ipa":"ʃɒkt"},{"en":"go on","uz":"davom etmoq, yuz bermoq","ipa":"ɡəʊ ɒn"}],"summary":["Hikoya = boshlanish (fon: Past Continuous, was / were), voqealar (Past Simple), yakun.","Ketma-ketlik so'zlari: First, Then, Next / After that, Later, Suddenly, Finally / In the end. Boshida vergul (Then dan tashqari).","after, before, as soon as + Past Simple bilan voqealarni bitta gapda bog'laymiz.","Hikoyada zamonni almashtirmang — boshdan oxirigacha o'tgan zamon.","Og'zaki: Guess what! / What happened next? / No way!"]},{"id":"u12-l8","slug":"unit-review-the-past","title":"Unit review: the past","titleUz":"Bosqich takrori: o'tgan zamon","goal":"12-bosqichdagi hamma narsani takrorlaysiz: Past Simple (to'g'ri / noto'g'ri fe'llar, savol va inkor), Past Continuous, when / while, used to, because / so / but / although va hikoya aytish. Oxirida o'tgan hafta oxiri yoki sayohat haqida bog'langan hikoya yoza va aytib bera olasiz.","words":[{"en":"journey","uz":"yo'l, safar","ipa":"ˈdʒɜːni"},{"en":"adventure","uz":"sarguzasht","ipa":"ədˈventʃə"},{"en":"souvenir","uz":"esdalik (sovg'a)","ipa":"ˌsuːvəˈnɪə"},{"en":"memorable","uz":"esda qoladigan","ipa":"ˈmemərəbl"},{"en":"experience","uz":"tajriba; boshdan kechirmoq","ipa":"ɪkˈspɪəriəns"},{"en":"argue","uz":"tortishmoq, janjallashmoq","ipa":"ˈɑːɡjuː"},{"en":"promise","uz":"va'da bermoq; va'da","ipa":"ˈprɒmɪs"},{"en":"whole","uz":"butun, tamom","ipa":"həʊl"},{"en":"brave","uz":"jasur","ipa":"breɪv"},{"en":"strange","uz":"g'alati","ipa":"streɪndʒ"}],"summary":["Past Simple: I went / worked; inkor didn't + V1; savol Did + ega + V1?; be → was / were. Vaqt: yesterday, last week, two days ago, in 2019.","Past Continuous (was / were + V-ing) — jarayon; Past Simple — qisqa voqea: I was walking when I saw…; while + uzun ish.","used to + V1 — o'tgan odat va holat; sanalgan marta va aniq muddat uchun Past Simple.","because (sabab), so (natija), but / although (qarama-qarshilik) — bir gapda because ... so va although ... but yo'q.","Hikoya: fon (Continuous) → voqealar (First, Then, After that, Finally) → yakun. Zamon boshdan oxirigacha o'tgan."]},{"id":"u12-l9","slug":"what-happened-telling-a-story-to-a-friend","title":"What happened? Telling a story to a friend","titleUz":"Nima bo'ldi? Do'stga hikoya aytib berish","goal":"Do'stingizga kecha yoki o'tgan hafta bo'lgan voqeani qiziqarli aytib berasiz: Guess what happened! bilan boshlaysiz, Past Continuous (fon) va Past Simple (voqea) ni when / while bilan bog'laysiz, so, because, but, then, finally dan foydalanasiz va do'stingizning hikoyasiga No way! What happened next? deb javob berasiz.","words":[{"en":"embarrassed","uz":"xijolat bo'lgan, noqulay","ipa":"ɪmˈbærəst"},{"en":"unbelievable","uz":"ishonib bo'lmaydigan","ipa":"ˌʌnbɪˈliːvəbl"},{"en":"get stuck – got stuck","uz":"tiqilib qolmoq, qotib qolmoq","ipa":"get stʌk – gɒt stʌk"},{"en":"lift","uz":"lift","ipa":"lɪft"},{"en":"scream","uz":"chinqirmoq, qichqirmoq","ipa":"skriːm"},{"en":"No way!","uz":"Yo'q-e! Mumkin emas!","ipa":"nəʊ weɪ"}],"summary":["Hikoyani Guess what happened…! bilan boshlang.","Fon — Past Continuous (was waiting), voqea — Past Simple (saw, rang). Ularni when / while bog'laydi.","because — sabab, so — natija, but — qarama-qarshilik, then / finally — tartib.","Tinglovchi sifatida: Really? No way! What happened next?"]},{"id":"u12-l10","slug":"lost-property-reporting-a-lost-bag","title":"Lost property: reporting a lost bag","titleUz":"Yo'qolgan narsa: sumka yo'qolganini xabar qilish","goal":"Yo'qolgan narsalar bo'limida sumkangiz yo'qolganini xabar qilasiz: narsani tasvirlaysiz (rangi, o'lchami, ichida nima bor), qayerda va qachon yo'qolganini Past Simple va Past Continuous bilan aytasiz (I left it on the bus. I was talking on the phone when…) va xodimning savollariga javob berasiz.","words":[{"en":"lost property office","uz":"yo'qolgan narsalar bo'limi","ipa":"lɒst ˈprɒpəti ˈɒfɪs"},{"en":"item","uz":"narsa, buyum","ipa":"ˈaɪtəm"},{"en":"describe","uz":"tasvirlamoq","ipa":"dɪˈskraɪb"},{"en":"leather","uz":"charm","ipa":"ˈleðə"},{"en":"zip","uz":"zanjir (kiyim, sumkada)","ipa":"zɪp"},{"en":"strap","uz":"tasma, qayish","ipa":"stræp"},{"en":"form","uz":"blanka, anketa","ipa":"fɔːm"}],"summary":["Narsani tasvirlang: o'lcham → rang → material → narsa (a big black leather bag), keyin it has a strap / a zip.","Qachon va qayerda: Past Simple — I lost it yesterday. I left it on the bus.","Yo'qotish paytidagi fon: Past Continuous — I was talking on the phone when I got off.","Savollar: What does it look like? When did you lose it? Where did you last see it? What was inside?","Oxirida xodim form (blanka) to'ldirtiradi va qo'ng'iroq qiladi."]},{"id":"u12-l11","slug":"stories-from-the-past-final-review","title":"Stories from the past: final review","titleUz":"O'tmish hikoyalari: yakuniy takror","goal":"Butun bosqichni takrorlaysiz: Past Simple (to'g'ri/noto'g'ri fe'llar, savol, inkor, ago), Past Continuous, when / while, used to, because / so / but / although va hikoya tartibi (first, then, after that, finally) — va ularni bitta kichik hikoyada birga ishlatasiz.","words":[{"en":"terrified","uz":"dahshatga tushgan, juda qo'rqqan","ipa":"ˈterɪfaɪd"},{"en":"relieved","uz":"yengil tortgan","ipa":"rɪˈliːvd"},{"en":"all of a sudden","uz":"to'satdan, birdan","ipa":"ɔːl əv ə ˈsʌdn"},{"en":"at last","uz":"nihoyat, oxiri","ipa":"æt lɑːst"},{"en":"in the middle of","uz":"o'rtasida","ipa":"ɪn ðə ˈmɪdl əv"}],"summary":["Past Simple: V2; savol — Did you…?, inkor — didn't + V1; ago — o'tgan vaqt.","Past Continuous (was / were + -ing) — fon; Past Simple — voqea; when / while bog'laydi.","used to + V1 — avvalgi odat.","because — sabab, so — natija, but / although — qarama-qarshilik.","Tartib: First, then, after that, finally — hikoya shunday quriladi."]}]},{"id":"u13","n":13,"title":"Plans and the future","titleUz":"Rejalar va kelajak: going to, will, may / might, shart gap","description":"Going to, will, Present Continuous rejalar uchun, may / might va birinchi shart gap.","canDo":["Reja va qarorlarni (going to, will) farqlab aytaman","Ehtimolni (may, might) bildiraman","First conditional gap tuzaman","Uchrashuv va rejalar belgilayman"],"lessons":[{"id":"u13-l1","slug":"going-to","title":"Going to","titleUz":"Going to: rejalar va aniq belgilar","goal":"be going to + fe'l yordamida kelajak rejalaringiz (I'm going to study medicine) va hozirgi belgilarga asoslangan taxminlarni (Look at the clouds! It's going to rain) ayta olasiz, inkor va savol gaplar tuzasiz.","words":[{"en":"plan","uz":"reja; rejalashtirmoq","ipa":"plæn"},{"en":"decide","uz":"qaror qilmoq","ipa":"dɪˈsaɪd"},{"en":"book","uz":"oldindan band qilmoq","ipa":"bʊk"},{"en":"pack","uz":"(yukni) joylamoq","ipa":"pæk"},{"en":"save money","uz":"pul yig'moq","ipa":"seɪv ˈmʌni"},{"en":"take an exam","uz":"imtihon topshirmoq","ipa":"teɪk ən ɪɡˈzæm"},{"en":"move","uz":"ko'chib o'tmoq","ipa":"muːv"},{"en":"get married","uz":"turmush qurmoq; uylanmoq","ipa":"ɡet ˈmærid"},{"en":"next year","uz":"kelasi yil","ipa":"nekst jɪə"},{"en":"careful","uz":"ehtiyotkor","ipa":"ˈkeəfl"}],"summary":["am / is / are + going to + V1 — oldindan qilingan reja yoki niyat: I'm going to study.","Inkor: isn't / aren't / 'm not going to. Savol: Are you going to…? — do / does kerak emas.","Hozir ko'rinib turgan dalil bo'lsa ham going to: Look at the clouds! It's going to rain.","gonna — faqat og'zaki shakl; yozuvda going to."]},{"id":"u13-l2","slug":"will-and-wont","title":"Will and won't","titleUz":"Will / won't: qaror, va'da, taxmin","goal":"will / won't bilan gap qurasiz va uni uchta holatda ishlatasiz: shu zahoti qaror (I'll answer it), va'da va taklif (I'll help you) hamda fikrga asoslangan taxmin (I think it will be hot).","words":[{"en":"promise","uz":"va'da bermoq; va'da","ipa":"ˈprɒmɪs"},{"en":"probably","uz":"ehtimol, ko'pincha","ipa":"ˈprɒbəbli"},{"en":"definitely","uz":"albatta, shubhasiz","ipa":"ˈdefɪnətli"},{"en":"perhaps","uz":"balki","ipa":"pəˈhæps"},{"en":"secret","uz":"sir","ipa":"ˈsiːkrət"},{"en":"future","uz":"kelajak","ipa":"ˈfjuːtʃə"},{"en":"robot","uz":"robot","ipa":"ˈrəʊbɒt"},{"en":"carry","uz":"ko'tarib yurmoq, olib bormoq","ipa":"ˈkæri"},{"en":"on time","uz":"o'z vaqtida","ipa":"ɒn taɪm"},{"en":"right away","uz":"darhol","ipa":"raɪt əˈweɪ"}],"summary":["will + V1 barcha egalar bilan: I / he / they will go. Inkor: won't. Savol: Will you…? Hech qachon will to go, wills.","Shu zahoti qaror, va'da va taklif: The phone is ringing — I'll answer it. I won't tell anyone.","Fikr va taxmin: I think / I'm sure / probably / definitely + will.","Inkor fikr: I don't think it will rain (I think it won't emas)."]},{"id":"u13-l3","slug":"will-or-going-to","title":"Will or going to?","titleUz":"Will yoki going to? Shall bilan taklif","goal":"will va going to farqini bilib, vaziyatga qarab to'g'ri birini tanlaysiz hamda Shall I…? va Shall we…? bilan yordam taklif qilasiz va birgalikda ish qilishni taklif etasiz.","words":[{"en":"decision","uz":"qaror","ipa":"dɪˈsɪʒn"},{"en":"offer","uz":"taklif qilmoq (yordam)","ipa":"ˈɒfə"},{"en":"suggest","uz":"taklif qilmoq, maslahat bermoq","ipa":"səˈdʒest"},{"en":"instead","uz":"o'rniga","ipa":"ɪnˈsted"},{"en":"already","uz":"allaqachon","ipa":"ɔːlˈredi"},{"en":"Good idea!","uz":"Yaxshi fikr!","ipa":"ɡʊd aɪˈdɪə"},{"en":"No problem","uz":"Hech gap emas","ipa":"nəʊ ˈprɒbləm"},{"en":"It depends","uz":"Bunga bog'liq","ipa":"ɪt dɪˈpendz"},{"en":"umbrella","uz":"soyabon","ipa":"ʌmˈbrelə"},{"en":"guide","uz":"gid, yo'lboshchi","ipa":"ɡaɪd"}],"summary":["going to — oldindan qilingan reja yoki hozir ko'rinib turgan dalil; will — shu zahoti qaror, fikr, va'da, taklif.","Savol bering: bu reja / dalilmi yoki hozirgina o'ylab topdimmi? Shunga qarab tanlang.","will va going to bir gapda birga kelmaydi: will going to ❌.","Shall I…? — yordam taklifi; Shall we…? — birgalikda ish taklifi. Faqat I / we bilan, dan keyin V1."]},{"id":"u13-l4","slug":"present-continuous-for-plans","title":"Present Continuous for plans","titleUz":"Present Continuous: kelishilgan rejalar","goal":"Present Continuous ni kelajak uchun ishlatasiz: kelishib qo'yilgan uchrashuv va rejalarni (I'm meeting Laylo at six) aytasiz, uni going to va Present Simple (jadval) bilan chalkashtirmaysiz.","words":[{"en":"arrange","uz":"kelishmoq, uyushtirmoq","ipa":"əˈreɪndʒ"},{"en":"appointment","uz":"qabul, belgilangan uchrashuv","ipa":"əˈpɔɪntmənt"},{"en":"dentist","uz":"tish shifokori","ipa":"ˈdentɪst"},{"en":"wedding","uz":"to'y","ipa":"ˈwedɪŋ"},{"en":"flight","uz":"reys, parvoz","ipa":"flaɪt"},{"en":"pick up","uz":"olib ketmoq (mashinada)","ipa":"pɪk ʌp"},{"en":"diary","uz":"kundalik; reja daftari","ipa":"ˈdaɪəri"},{"en":"busy","uz":"band","ipa":"ˈbɪzi"},{"en":"free","uz":"bo'sh (vaqti bor)","ipa":"friː"},{"en":"stay with","uz":"birovnikida qolmoq","ipa":"steɪ wɪð"}],"summary":["am / is / are + V-ing + vaqt iborasi = kelishilgan yaqin reja: I'm meeting Laylo at six.","Rasmiy jadval va dasturda Present Simple: The train leaves at 8:15.","Taxmin va ob-havo uchun Present Continuous emas, going to / will: It's going to rain.","Savol va inkor oddiy Present Continuous kabi: Are you coming? I'm not working on Sunday."]},{"id":"u13-l5","slug":"may-and-might","title":"May and might","titleUz":"May / might: ehtimol","goal":"Kelajak haqida ishonchingiz komil bo'lmaganda may / might + fe'l bilan ehtimolni ifodalaysiz (It might rain. I may go to Samarkand), will bilan farqini bilasiz va maybe / may be ni adashtirmaysiz.","words":[{"en":"maybe","uz":"balki","ipa":"ˈmeɪbi"},{"en":"chance","uz":"imkoniyat, ehtimol","ipa":"tʃɑːns"},{"en":"hope","uz":"umid qilmoq","ipa":"həʊp"},{"en":"forecast","uz":"(ob-havo) bashorati","ipa":"ˈfɔːkɑːst"},{"en":"storm","uz":"bo'ron","ipa":"stɔːm"},{"en":"cancel","uz":"bekor qilmoq","ipa":"ˈkænsl"},{"en":"delay","uz":"kechikish; kechiktirmoq","ipa":"dɪˈleɪ"},{"en":"traffic jam","uz":"tirbandlik","ipa":"ˈtræfɪk dʒæm"},{"en":"not sure","uz":"ishonchi komil emas","ipa":"nɒt ʃɔː"},{"en":"enough","uz":"yetarli","ipa":"ɪˈnʌf"}],"summary":["may / might + V1 = ehtimol, ishonch past: It might rain. I may go. Hamma egalar bilan bir xil, to va -s yo'q.","Inkor: may not / might not (mayn't yo'q). Savol uchun: Do you think it will…?","Aniq narsa — will / won't, noaniq — may / might.","Maybe gap boshida (Maybe he is late), may be fe'l sifatida (He may be late). May I…? — xushmuomala ruxsat so'rash."]},{"id":"u13-l6","slug":"first-conditional","title":"First conditional","titleUz":"Birinchi shart gap: if + Present, will","goal":"If + Present Simple, … will + V1 qolipi bilan kelajakdagi real shart va natija haqida gapirasiz (If it rains, we'll stay at home), va'da, ogohlantirish hamda maslahat berasiz va unless ni (ixtiyoriy) tushunasiz.","words":[{"en":"pass (an exam)","uz":"(imtihondan) o'tmoq","ipa":"pɑːs"},{"en":"fail","uz":"yiqilmoq; o'ta olmamoq","ipa":"feɪl"},{"en":"miss","uz":"o'tkazib yubormoq (transport)","ipa":"mɪs"},{"en":"catch","uz":"ulgurmoq; tutmoq (transport)","ipa":"kætʃ"},{"en":"borrow","uz":"qarzga olmoq","ipa":"ˈbɒrəʊ"},{"en":"lend","uz":"qarzga bermoq","ipa":"lend"},{"en":"in time","uz":"o'z vaqtida (ulgurib)","ipa":"ɪn taɪm"},{"en":"warn","uz":"ogohlantirmoq","ipa":"wɔːn"},{"en":"wake up","uz":"uyg'onmoq","ipa":"weɪk ʌp"},{"en":"hurry up","uz":"shoshilmoq","ipa":"ˈhʌri ʌp"}],"summary":["If + Present Simple, will + V1 — kelajakdagi real shart va natija: If it rains, we'll stay home.","If-qismda will yo'q: If it rains ✅, If it will rain ❌. Inkor: don't / doesn't.","If-qism boshida bo'lsa — vergul; oxirida bo'lsa — vergulsiz. Natijada can, may, might yoki buyruq ham kelishi mumkin.","Unless = if … not: Unless you hurry, you'll be late. Unless dan keyin inkor kerak emas."]},{"id":"u13-l7","slug":"making-plans","title":"Making plans","titleUz":"Reja tuzish: taklif, qabul va rad etish","goal":"Do'stlaringizga taklif qilasiz (Would you like to come…? Why don't we…?), taklifni qabul qilasiz yoki xushmuomalalik bilan rad etasiz (I'd love to, but…) hamda vaqt va joyni kelishib olasiz.","words":[{"en":"invite","uz":"taklif qilmoq (mehmonga)","ipa":"ɪnˈvaɪt"},{"en":"invitation","uz":"taklifnoma; taklif","ipa":"ˌɪnvɪˈteɪʃn"},{"en":"accept","uz":"qabul qilmoq","ipa":"əkˈsept"},{"en":"decline","uz":"rad etmoq (xushmuomala)","ipa":"dɪˈklaɪn"},{"en":"I'd love to","uz":"Xursand bo'lardim","ipa":"aɪd lʌv tuː"},{"en":"I'm afraid","uz":"Afsuski","ipa":"aɪm əˈfreɪd"},{"en":"another time","uz":"boshqa safar","ipa":"əˈnʌðə taɪm"},{"en":"look forward to","uz":"intizorlik bilan kutmoq","ipa":"lʊk ˈfɔːwəd tuː"},{"en":"meet up","uz":"uchrashmoq","ipa":"miːt ʌp"},{"en":"sounds great","uz":"zo'r bo'larkan","ipa":"saʊndz ɡreɪt"}],"summary":["Taklif: Would you like to + V1?, Why don't we + V1?, How about + V-ing?, Let's + V1.","Qabul: I'd love to! / That sounds great! / Good idea!","Rad etish: minnatdorchilik + I'd love to, but… / I'm afraid I can't + sabab + boshqa taklif.","Kelishuv: What time / Where shall we meet? va tasdiqlash: So we're meeting at seven."]},{"id":"u13-l8","slug":"unit-review-the-future","title":"Unit review: the future","titleUz":"Bosqich takrori: kelajak","goal":"Bosqichdagi barcha mavzuni takrorlaysiz: going to, will / won't, will yoki going to + shall, Present Continuous (reja), may / might, birinchi shart gap va taklif qilish / qabul qilish / rad etish. Kelajak haqida erkin va to'g'ri gapira olasiz.","words":[{"en":"expect","uz":"kutmoq, umid qilmoq","ipa":"ɪkˈspekt"},{"en":"prepare","uz":"tayyorlamoq; tayyorlanmoq","ipa":"prɪˈpeə"},{"en":"schedule","uz":"jadval, reja","ipa":"ˈʃedjuːl"},{"en":"deadline","uz":"oxirgi muddat","ipa":"ˈdedlaɪn"},{"en":"celebrate","uz":"nishonlamoq","ipa":"ˈselɪbreɪt"},{"en":"graduate","uz":"(universitetni) bitirmoq","ipa":"ˈɡrædʒueɪt"},{"en":"surprise","uz":"syurpriz; hayratga solmoq","ipa":"səˈpraɪz"},{"en":"arrive","uz":"yetib kelmoq","ipa":"əˈraɪv"},{"en":"apply for","uz":"(ishga) topshirmoq, murojaat qilmoq","ipa":"əˈplaɪ fɔː"},{"en":"get ready","uz":"tayyorlanmoq","ipa":"ɡet ˈredi"}],"summary":["going to + V1 — reja yoki dalil; will + V1 — shu zahoti qaror, va'da, fikr; Shall I / we…? — taklif.","Kelishilgan shaxsiy reja — Present Continuous (I'm meeting Laylo at six); jadval — Present Simple.","Ehtimol: may / might + V1 (It might rain); inkor: may not / might not.","Birinchi shart gap: If + Present Simple, will + V1; if-qismda will yo'q. Unless = if … not.","Taklif: Would you like to…? Why don't we…? How about…ing? Rad etish: I'd love to, but… / I'm afraid I can't."]},{"id":"u13-l9","slug":"making-weekend-plans-with-friends","title":"Making weekend plans with friends","titleUz":"Do'stlar bilan dam olish rejalarini tuzish","goal":"Do'stlaringiz bilan dam olish kunlari rejasini tuza olasiz: nima qilmoqchi ekaningizni aytasiz (going to), kelishilgan rejani aytasiz (I'm meeting…), taklif qilasiz va taklifni qabul qilasiz yoki rad etasiz.","words":[{"en":"hang out","uz":"vaqt o'tkazmoq, aylanib yurmoq","ipa":"hæŋ aʊt"},{"en":"stay in","uz":"uyda qolmoq","ipa":"steɪ ɪn"},{"en":"barbecue","uz":"barbekyu, ochiq havoda kabob","ipa":"ˈbɑː.bɪ.kjuː"},{"en":"lazy","uz":"dangasa","ipa":"ˈleɪ.zi"},{"en":"join","uz":"qo'shilmoq","ipa":"dʒɔɪn"},{"en":"match","uz":"o'yin, musobaqa","ipa":"mætʃ"}],"summary":["Niyat va reja: am / is / are + going to + V1 (I'm going to stay in).","Vaqti va joyi kelishilgan reja: Present Continuous (We're meeting at twelve).","Taklif: Why don't you join us? / Would you like to…? / How about going…?","Qabul: That sounds great! / I'd love to! Rad etish: I'd love to, but… Maybe another time?"]},{"id":"u13-l10","slug":"planning-a-trip-what-might-happen","title":"Planning a trip: what might happen?","titleUz":"Sayohatni rejalashtirish: nima bo'lishi mumkin?","goal":"Sayohatni rejalashtirganda nima bo'lishi mumkinligini ayta olasiz: will / won't (ishonch), may / might (ehtimol) va birinchi shart gap (If it rains, we'll…) bilan.","words":[{"en":"passport","uz":"pasport","ipa":"ˈpɑːs.pɔːt"},{"en":"luggage","uz":"yuk, bagaj","ipa":"ˈlʌɡ.ɪdʒ"},{"en":"souvenir","uz":"esdalik sovg'a","ipa":"ˌsuː.vəˈnɪər"},{"en":"sunscreen","uz":"quyoshdan himoya kremi","ipa":"ˈsʌn.skriːn"},{"en":"lost","uz":"yo'qolgan, adashgan","ipa":"lɒst"},{"en":"sightseeing","uz":"diqqatga sazovor joylarni ko'rish","ipa":"ˈsaɪtˌsiː.ɪŋ"}],"summary":["Ishonch: will / won't + V1. Ehtimol: may / might + V1 (It might rain).","Ehtimol emas: may not / might not (mayn't yo'q).","Birinchi shart gap: If + Present Simple, will + V1 (If it rains, we'll stay in).","If dan keyin will ishlatilmaydi."]},{"id":"u13-l11","slug":"plans-and-the-future-final-review","title":"Plans and the future: final review","titleUz":"Rejalar va kelajak: yakuniy takror","goal":"Bosqichni yakunlaysiz: going to, will / won't, will yoki going to, Present Continuous (reja), may / might, birinchi shart gap va reja tuzish iboralarini bir joyda takrorlab, kelajak haqida erkin gapirasiz.","words":[{"en":"goal","uz":"maqsad","ipa":"ɡəʊl"},{"en":"dream","uz":"orzu","ipa":"driːm"},{"en":"success","uz":"muvaffaqiyat","ipa":"səkˈses"},{"en":"someday","uz":"bir kun, kelajakda biror vaqt","ipa":"ˈsʌm.deɪ"},{"en":"come true","uz":"ro'yobga chiqmoq","ipa":"kʌm truː"},{"en":"change","uz":"o'zgartirmoq, o'zgarmoq","ipa":"tʃeɪndʒ"}],"summary":["Reja: going to + V1; kelishilgan reja: Present Continuous; shu zahoti qaror va va'da: will / won't.","Ehtimol: may / might + V1; ehtimol emas: may not / might not.","Birinchi shart gap: If + Present Simple, will + V1.","Taklif: Would you like to…? Why don't we…? How about…ing? Rad etish: I'd love to, but… Maybe another time?"]}]},{"id":"u14","n":14,"title":"Comparing things","titleUz":"Taqqoslash: qiyosiy va orttirma daraja, as … as, too / enough","description":"Qiyosiy va orttirma daraja, as ... as, too / enough, ravishlar va tasvirlash.","canDo":["Narsa va odamlarni solishtiraman","Eng yaxshi/yomonini (superlative) aytaman","too va enough ni to'g'ri ishlataman","Ikki shahar yoki odamni taqqoslab yozaman"],"lessons":[{"id":"u14-l1","slug":"comparatives","title":"Comparatives","titleUz":"Qiyosiy daraja: -er va more","goal":"Ikki narsani solishtirishni o'rganasiz: qisqa sifatlarga -er (taller, bigger, easier), uzun sifatlarga more (more expensive) qo'shasiz, good → better, bad → worse kabi noto'g'ri shakllarni bilasiz va than bilan to'g'ri gap tuzasiz. more bigger kabi xatolardan qochasiz.","words":[{"en":"expensive","uz":"qimmat","ipa":"ɪkˈspensɪv"},{"en":"cheap","uz":"arzon","ipa":"tʃiːp"},{"en":"comfortable","uz":"qulay","ipa":"ˈkʌmftəbl"},{"en":"popular","uz":"mashhur, ommabop","ipa":"ˈpɒpjələ"},{"en":"dangerous","uz":"xavfli","ipa":"ˈdeɪndʒərəs"},{"en":"noisy","uz":"shovqinli","ipa":"ˈnɔɪzi"},{"en":"modern","uz":"zamonaviy","ipa":"ˈmɒdn"},{"en":"healthy","uz":"sog'lom; foydali","ipa":"ˈhelθi"},{"en":"difficult","uz":"qiyin","ipa":"ˈdɪfɪkəlt"},{"en":"heavy","uz":"og'ir","ipa":"ˈhevi"}],"summary":["Qisqa sifat + -er (taller, cheaper); -e bilan tugasa -r (nicer); big → bigger; easy → easier.","Uzun sifat: more + sifat (more expensive, more comfortable).","Noto'g'ri shakllar: good → better, bad → worse, far → further.","Solishtirishda than ishlatiladi: taller than me. then — boshqa so'z (keyin).","Ikki marta qiyoslamang: ❌ more bigger. Kuchaytirish uchun: much / a lot / a bit + qiyosiy (❌ very bigger)."]},{"id":"u14-l2","slug":"superlatives","title":"Superlatives","titleUz":"Orttirma daraja: the -est, the most","goal":"Uch va undan ortiq narsa ichidan eng ... ekanini aytishni o'rganasiz: the tallest, the biggest, the most beautiful. the best, the worst kabi noto'g'ri shakllarni, one of the + -est + ko'plik qolipini va in / of ning farqini bilib olasiz. the ni tushirib qoldirish xatosidan qochasiz.","words":[{"en":"delicious","uz":"mazali","ipa":"dɪˈlɪʃəs"},{"en":"wonderful","uz":"ajoyib","ipa":"ˈwʌndəfl"},{"en":"terrible","uz":"dahshatli, juda yomon","ipa":"ˈterəbl"},{"en":"ancient","uz":"qadimiy","ipa":"ˈeɪnʃənt"},{"en":"famous","uz":"mashhur","ipa":"ˈfeɪməs"},{"en":"huge","uz":"ulkan","ipa":"hjuːdʒ"},{"en":"tiny","uz":"juda kichkina","ipa":"ˈtaɪni"},{"en":"exciting","uz":"hayajonli, qiziqarli","ipa":"ɪkˈsaɪtɪŋ"},{"en":"boring","uz":"zerikarli","ipa":"ˈbɔːrɪŋ"},{"en":"useful","uz":"foydali","ipa":"ˈjuːsfl"}],"summary":["Orttirma daraja uch va undan ortiq narsa ichidan \"eng ...\" ni bildiradi va doim the bilan keladi: the tallest, the most famous.","Qisqa sifat: the + -est (the biggest, the easiest). Uzun sifat: the most + sifat. ❌ the most big, ❌ the expensivest.","Noto'g'ri shakllar: good → the best, bad → the worst, far → the furthest.","Joy / guruh bilan in (in the world, in my class), ko'plik / vaqt bilan of (of the year, of my life).","one of the + orttirma + ko'plik ot: one of the oldest cities. ...the best ... I've ever ... — tajriba haqida."]},{"id":"u14-l3","slug":"as-as","title":"As ... as","titleUz":"as ... as va the same as","goal":"Ikki narsa teng ekanini aytasiz (as tall as), teng emas ekanini aytasiz (not as expensive as), the same as, different from, similar to va like ni to'g'ri ishlatasiz. same with, different with, as tall than kabi xatolardan qochasiz.","words":[{"en":"similar","uz":"o'xshash","ipa":"ˈsɪmələ"},{"en":"different","uz":"boshqacha, farqli","ipa":"ˈdɪfrənt"},{"en":"the same","uz":"bir xil","ipa":"ðə seɪm"},{"en":"alike","uz":"bir-biriga o'xshash","ipa":"əˈlaɪk"},{"en":"twin","uz":"egizak","ipa":"twɪn"},{"en":"opposite","uz":"teskari, qarama-qarshi","ipa":"ˈɒpəzɪt"},{"en":"in common","uz":"umumiy (narsa)","ipa":"ɪn ˈkɒmən"},{"en":"compare","uz":"solishtirmoq","ipa":"kəmˈpeə"},{"en":"difference","uz":"farq","ipa":"ˈdɪfrəns"},{"en":"equal","uz":"teng","ipa":"ˈiːkwəl"}],"summary":["as + sifat + as — tenglik: Aziz is as tall as Kamol. Sifat o'zgarmaydi: ❌ as taller as.","not as + sifat + as — \"...chalik emas\": Bukhara isn't as big as Tashkent. (= Tashkent is bigger.)","the same as, different from, similar to — ❌ same with, different with, similar with.","look like — o'xshamoq: You look like your mother. alike — The two sisters are alike.","Foydali iboralar: as soon as possible, as much as you like, twice as ... as."]},{"id":"u14-l4","slug":"too-and-enough","title":"Too and enough","titleUz":"Too va enough, too much / too many","goal":"too (me'yoridan ortiq, muammo) va enough (yetarli) so'zlarini to'g'ri o'rinda ishlatasiz: too hot, big enough, enough money, too much sugar, too many people, too tired to study. too much hot, enough big, too many money kabi xatolarni tuzatasiz.","words":[{"en":"spicy","uz":"achchiq (ziravorli)","ipa":"ˈspaɪsi"},{"en":"salty","uz":"sho'r","ipa":"ˈsɔːlti"},{"en":"tight","uz":"tor (kiyim)","ipa":"taɪt"},{"en":"loose","uz":"keng (kiyim)","ipa":"luːs"},{"en":"crowded","uz":"gavjum, odam ko'p","ipa":"ˈkraʊdɪd"},{"en":"afford","uz":"(puli) yetmoq, ega bo'la olmoq","ipa":"əˈfɔːd"},{"en":"plenty of","uz":"yetarli darajada ko'p","ipa":"ˈplenti əv"},{"en":"enough","uz":"yetarli","ipa":"ɪˈnʌf"},{"en":"exhausted","uz":"juda charchagan","ipa":"ɪɡˈzɔːstɪd"},{"en":"cramped","uz":"tor, siqiq (joy)","ipa":"kræmpt"}],"summary":["too + sifat — me'yoridan ortiq, muammo: too hot, too small. very esa shunchaki \"juda\" (muammo yo'q).","sifat + enough (big enough), lekin enough + ot (enough money). ❌ enough big.","too much + sanalmaydigan ot (sugar, time, traffic); too many + sanaladigan ko'plik ot (people, cars). ❌ too much hot.","too / enough + to + fe'l: too tired to study, old enough to drive. too young = not old enough."]},{"id":"u14-l5","slug":"adverbs-of-manner","title":"Adverbs of manner","titleUz":"Ravish: quickly, well, hard","goal":"Fe'l qanday bajarilishini ravish bilan aytasiz: quickly, carefully, badly. good (sifat) va well (ravish) farqini bilasiz, hard, fast, late, early kabi shakli o'zgarmaydigan ravishlarni, hardly va lately ning boshqa ma'nosini eslab qolasiz va ravishning qiyosiy darajasini tuzasiz (faster, harder, more carefully).","words":[{"en":"quickly","uz":"tez, tezda","ipa":"ˈkwɪkli"},{"en":"slowly","uz":"sekin","ipa":"ˈsləʊli"},{"en":"carefully","uz":"ehtiyotkorlik bilan, diqqat bilan","ipa":"ˈkeəfəli"},{"en":"badly","uz":"yomon","ipa":"ˈbædli"},{"en":"loudly","uz":"baland ovozda","ipa":"ˈlaʊdli"},{"en":"quietly","uz":"jimgina, past ovozda","ipa":"ˈkwaɪətli"},{"en":"easily","uz":"oson, osongina","ipa":"ˈiːzɪli"},{"en":"happily","uz":"xursandlik bilan","ipa":"ˈhæpɪli"},{"en":"hard","uz":"qattiq, jiddiy (ravish)","ipa":"hɑːd"},{"en":"early","uz":"erta","ipa":"ˈɜːli"}],"summary":["Ravish fe'lning qanday bajarilishini bildiradi: odatda sifat + -ly (slowly, carefully); -y → -ily (happily, easily).","good — sifat, well — ravish: She is a good singer. She sings well. ❌ speaks good.","hard, fast, late, early — sifat va ravish bir xil. hardly = deyarli ... emas, lately = yaqinda.","Tartib: fe'l + to'ldiruvchi + ravish: He speaks English well. ❌ speaks well English. be / look / taste / feel dan keyin sifat.","Qiyosiy: faster, harder, better, worse; -ly ravishlar uchun more: more slowly, more carefully."]},{"id":"u14-l6","slug":"describing-people","title":"Describing people","titleUz":"Odamlarni tasvirlash: tashqi ko'rinish va xarakter","goal":"Odamning tashqi ko'rinishi (tall, slim, curly hair, blue eyes) va xarakteri (friendly, shy, generous) ni tasvirlaysiz. is / has / looks like, What does he look like? va What is he like? farqini bilasiz va sifatlarni to'g'ri tartibda qo'yasiz (a nice young man).","words":[{"en":"slim","uz":"ozg'in, nozik tanli","ipa":"slɪm"},{"en":"curly","uz":"jingalak","ipa":"ˈkɜːli"},{"en":"bald","uz":"kal","ipa":"bɔːld"},{"en":"middle-aged","uz":"o'rta yoshli","ipa":"ˌmɪdl ˈeɪdʒd"},{"en":"good-looking","uz":"chiroyli, xushsurat","ipa":"ˌɡʊd ˈlʊkɪŋ"},{"en":"generous","uz":"saxovatli","ipa":"ˈdʒenərəs"},{"en":"shy","uz":"uyatchan","ipa":"ʃaɪ"},{"en":"lazy","uz":"dangasa","ipa":"ˈleɪzi"},{"en":"polite","uz":"odobli, xushmuomala","ipa":"pəˈlaɪt"},{"en":"honest","uz":"halol, rostgo'y","ipa":"ˈɒnɪst"}],"summary":["Bo'y, tana, yosh uchun be: He is tall and slim. Soch, ko'z, soqol uchun have: She has long curly hair. ❌ She is long hair.","What does he look like? — tashqi ko'rinish. What is he like? — xarakter. What does he like? — qiziqishlari.","look + sifat (You look tired), look like + ot (He looks like his father).","Sifatlar tartibi: fikr → o'lcham → yosh → rang → kelib chiqish → ot: a lovely young woman. Tavsif uchun with: a man with a beard.","Xarakter sifatlari: friendly, shy, generous, lazy, honest, polite, funny."]},{"id":"u14-l7","slug":"comparing-places","title":"Comparing places","titleUz":"Shaharlarni solishtirish: o'qish va yozish","goal":"Ikki shahar yoki joyni solishtirib o'qiysiz va yozasiz. but, however, while, whereas, both ... and, on the other hand kabi bog'lovchilarni ishlatasiz, shahar haqida gapirish uchun kerakli so'zlarni (traffic, climate, public transport, cost of living) bilib olasiz va 8–10 gapli kichik taqqoslash matnini yozasiz.","words":[{"en":"traffic","uz":"tirbandlik (transport oqimi)","ipa":"ˈtræfɪk"},{"en":"climate","uz":"iqlim","ipa":"ˈklaɪmət"},{"en":"public transport","uz":"jamoat transporti","ipa":"ˌpʌblɪk ˈtrænspɔːt"},{"en":"neighbourhood","uz":"mahalla, atrof","ipa":"ˈneɪbəhʊd"},{"en":"cost of living","uz":"yashash xarajatlari","ipa":"ˌkɒst əv ˈlɪvɪŋ"},{"en":"nightlife","uz":"tungi hayot","ipa":"ˈnaɪtlaɪf"},{"en":"suburb","uz":"shahar chekkasi","ipa":"ˈsʌbɜːb"},{"en":"sights","uz":"diqqatga sazovor joylar","ipa":"saɪts"},{"en":"safe","uz":"xavfsiz","ipa":"seɪf"},{"en":"lively","uz":"jonli, quvnoq","ipa":"ˈlaɪvli"}],"summary":["Farqni ko'rsatish: but, while / whereas (gap ichida), However, va On the other hand, (yangi gapda, vergul bilan). O'xshashlik: both ... and, too, also.","Miqdor: more + ot; sanaladigan ot uchun fewer, sanalmaydigan uchun less: fewer cars, less traffic.","Taqqoslash matni: kirish (ikki joy), asosiy qism (2–3 mavzu), xulosa (In my opinion... / I prefer...).","Xatolar: ❌ more bigger from, ❌ Both of cities, ❌ The people is. To'g'ri: bigger than, Both cities, The people are."]},{"id":"u14-l8","slug":"unit-review-comparing","title":"Unit review: comparing","titleUz":"Bosqich takrori: taqqoslash","goal":"Butun bosqichni takrorlaysiz: qiyosiy va orttirma daraja, as ... as, too / enough, ravishlar, odamlarni tasvirlash va shaharlarni solishtirish. Aralash mashqlar orqali xatolaringizni topasiz va taqqoslash haqida erkin gapirishga tayyor bo'lasiz.","words":[{"en":"both","uz":"ikkalasi ham","ipa":"bəʊθ"},{"en":"whereas","uz":"holbuki, esa","ipa":"weərˈæz"},{"en":"however","uz":"biroq","ipa":"haʊˈevə"},{"en":"prefer","uz":"afzal ko'rmoq","ipa":"prɪˈfɜː"},{"en":"especially","uz":"ayniqsa","ipa":"ɪˈspeʃəli"},{"en":"although","uz":"garchi","ipa":"ɔːlˈðəʊ"},{"en":"instead","uz":"o'rniga","ipa":"ɪnˈsted"},{"en":"choose","uz":"tanlamoq","ipa":"tʃuːz"},{"en":"advantage","uz":"afzallik","ipa":"ədˈvɑːntɪdʒ"},{"en":"disadvantage","uz":"kamchilik","ipa":"ˌdɪsədˈvɑːntɪdʒ"}],"summary":["Qiyosiy: -er / more + than; orttirma: the -est / the most; good → better → the best, bad → worse → the worst.","as ... as (teng), not as ... as (kam), the same as, different from, similar to, look like.","too + sifat (muammo), sifat + enough, enough + ot, too much / too many.","Ravish: -ly, well (≠ good), hard / fast / early / late; qiyosiy: faster, more carefully. Tartib: fe'l + to'ldiruvchi + ravish.","Odamlarni tasvirlash: is tall, has curly hair, looks tired, What is he like? Shaharlarni solishtirish: while, whereas, however, both."]},{"id":"u14-l9","slug":"choosing-a-phone-comparing-products","title":"Choosing a phone: comparing products","titleUz":"Telefon tanlash: mahsulotlarni solishtirish","goal":"Do'konda ikki telefonni (yoki boshqa mahsulotni) solishtirishni o'rganasiz: qiyosiy va orttirma daraja, as ... as va too / enough yordamida narx, ekran, batareya va sifat haqida gapirasiz va tanlovingizni tushuntirasiz.","words":[{"en":"battery","uz":"batareya","ipa":"ˈbætəri"},{"en":"screen","uz":"ekran","ipa":"skriːn"},{"en":"brand","uz":"brend, marka","ipa":"brænd"},{"en":"charger","uz":"zaryadlagich","ipa":"ˈtʃɑːdʒə"},{"en":"discount","uz":"chegirma","ipa":"ˈdɪskaʊnt"},{"en":"lightweight","uz":"yengil (vazni kam)","ipa":"ˈlaɪtweɪt"}],"summary":["Ikki mahsulot: qiyosiy + than (The Nova is bigger than the Zed). Uch va ko'p: the + orttirma (the cheapest).","as ... as teng, not as ... as kamroq: The Zed isn't as good as the Nova.","too + sifat — muammo (too small); sifat + enough — yetarli (big enough).","Yangi so'zlar: battery, screen, brand, charger, discount, lightweight."]},{"id":"u14-l10","slug":"two-flats-to-rent-which-is-better","title":"Two flats to rent: which is better?","titleUz":"Ikki ijara uyi: qaysi biri yaxshi?","goal":"Ijaraga olinadigan ikki uyni narx, o'lcham va joylashuv bo'yicha solishtirasiz va nega bittasini tanlaganingizni inglizcha tushuntira olasiz: than, the most, as ... as, too, enough, both, however.","words":[{"en":"rent","uz":"ijara (haqi); ijaraga olmoq","ipa":"rent"},{"en":"landlord","uz":"uy egasi","ipa":"ˈlændlɔːd"},{"en":"bedroom","uz":"yotoqxona","ipa":"ˈbedruːm"},{"en":"balcony","uz":"balkon","ipa":"ˈbælkəni"},{"en":"furnished","uz":"mebelli","ipa":"ˈfɜːnɪʃt"},{"en":"bills","uz":"kommunal to'lovlar, hisoblar","ipa":"bɪlz"}],"summary":["Uylarni solishtirish: cheaper, more expensive, closer, bigger + than; uchtadan biri: the cheapest / the biggest.","too muammoni bildiradi (too far), enough sifatdan keyin keladi (big enough). too ... enough birga ishlatilmaydi.","Both + ko'plik: Both flats are nice. Qarama-qarshilik uchun: but, however.","Yangi so'zlar: rent, landlord, bedroom, balcony, furnished, bills."]},{"id":"u14-l11","slug":"comparing-things-final-review","title":"Comparing things: final review","titleUz":"Taqqoslash: yakuniy takror","goal":"Bosqichni yakuniy takrorlaysiz: qiyosiy va orttirma daraja, as ... as / the same as, too / enough, ravishlar va odamlar hamda joylarni tasvirlash. Aralash mashqlar sizni taqqoslash haqida ishonchli gapirishga tayyorlaydi.","words":[{"en":"quality","uz":"sifat (sifatlilik)","ipa":"ˈkwɒləti"},{"en":"size","uz":"o'lcham","ipa":"saɪz"},{"en":"speed","uz":"tezlik","ipa":"spiːd"},{"en":"weight","uz":"og'irlik, vazn","ipa":"weɪt"},{"en":"cost","uz":"turmoq (narxi); narx","ipa":"kɒst"},{"en":"confident","uz":"o'ziga ishongan","ipa":"ˈkɒnfɪdənt"}],"summary":["Qiyosiy (-er / more + than) ikki narsa uchun; orttirma (the -est / the most) uch va undan ko'p uchun. good → better → the best.","as ... as, not as ... as, the same as, different from.","too + sifat (muammo), sifat + enough (yetarli).","Ravish: slowly, carefully, well, hard, fast. Tasvir: is tall, has curly hair, looks like, What is he like?","Yangi so'zlar: quality, size, speed, weight, cost, confident."]}]},{"id":"u15","n":15,"title":"Rules, advice and requests","titleUz":"Qoidalar, maslahat va iltimoslar: must, should, can / could","description":"Must, have to, should, can / could, muloyim iltimoslar, yo'l ko'rsatish va shifokorda.","canDo":["Majburiyat va maslahatni (must, have to, should) ayta olaman","Odobli iltimos va takliflar bildiraman","Yo'l ko'rsataman va shifokorda nima bezovta qilishini aytaman","Belgilar va qoidalarni tushunaman"],"lessons":[{"id":"u15-l1","slug":"must-and-have-to","title":"Must and have to","titleUz":"Must, have to, mustn't, don't have to","goal":"Majburiyatni must va have to bilan ifodalaysiz, ularning farqini bilasiz, eng muhimi — mustn't (\"mumkin emas\") bilan don't have to (\"shart emas\") ni adashtirmaysiz va I must to go, he musts kabi xatolardan qochasiz.","words":[{"en":"rule","uz":"qoida","ipa":"ruːl"},{"en":"obey","uz":"bo'ysunmoq, rioya qilmoq","ipa":"əˈbeɪ"},{"en":"necessary","uz":"zarur, kerakli","ipa":"ˈnesəsəri"},{"en":"forbidden","uz":"taqiqlangan","ipa":"fəˈbɪdn"},{"en":"compulsory","uz":"majburiy","ipa":"kəmˈpʌlsəri"},{"en":"deadline","uz":"oxirgi muddat","ipa":"ˈdedlaɪn"},{"en":"uniform","uz":"forma (kiyim)","ipa":"ˈjuːnɪfɔːm"},{"en":"fine","uz":"jarima","ipa":"faɪn"},{"en":"seat belt","uz":"xavfsizlik kamari","ipa":"ˈsiːt belt"},{"en":"on time","uz":"o'z vaqtida","ipa":"ɒn taɪm"}],"summary":["must va have to — majburiyat. must dan keyin to yo'q, -s yo'q: He must go. have to: He has to go.","mustn't = taqiq (You mustn't smoke here). don't have to = shart emas (You don't have to come).","must ning o'tgan va kelasi zamoni yo'q: had to, will have to.","have to da savol va inkor do / does / did bilan: Do I have to…? She doesn't have to…"]},{"id":"u15-l2","slug":"should-and-shouldnt","title":"Should and shouldn't","titleUz":"Should / shouldn't: maslahat berish","goal":"should va shouldn't bilan maslahat berasiz va maslahat so'raysiz (What should I do?), I think you should… va If I were you, I'd… kabi tabiiy iboralarni ishlatasiz hamda should to go, an advice kabi xatolardan qochasiz.","words":[{"en":"advice","uz":"maslahat","ipa":"ədˈvaɪs"},{"en":"suggest","uz":"taklif qilmoq","ipa":"səˈdʒest"},{"en":"recommend","uz":"tavsiya qilmoq","ipa":"ˌrekəˈmend"},{"en":"sensible","uz":"oqilona, aqlli","ipa":"ˈsensəbl"},{"en":"stressed","uz":"stressda, asabiy","ipa":"strest"},{"en":"relax","uz":"dam olmoq, tinchlanmoq","ipa":"rɪˈlæks"},{"en":"habit","uz":"odat","ipa":"ˈhæbɪt"},{"en":"give up","uz":"voz kechmoq, tashlamoq","ipa":"ɡɪv ʌp"},{"en":"take a break","uz":"tanaffus qilmoq","ipa":"teɪk ə breɪk"},{"en":"enough","uz":"yetarli","ipa":"ɪˈnʌf"}],"summary":["should + V1 = maslahat: You should rest. shouldn't = \"…masligi kerak\": You shouldn't worry.","Savol: Should I…? / What should I do? — to, -s va do/does kerak emas.","Maslahat iboralari: I think you should…, I don't think you should…, If I were you, I'd…","advice — sanalmaydi: some advice, a piece of advice (an advice ❌, advices ❌)."]},{"id":"u15-l3","slug":"can-could-be-able-to","title":"Can, could, be able to","titleUz":"Can, could, be able to: qobiliyat va ruxsat","goal":"Qobiliyatni hozir, o'tmishda va kelajakda to'g'ri ifodalaysiz (can, could, was able to, will be able to), ruxsat so'raysiz (Can I…? Could I…?) va I will can, I can to swim kabi xatolardan qochasiz.","words":[{"en":"ability","uz":"qobiliyat","ipa":"əˈbɪləti"},{"en":"skill","uz":"malaka, ko'nikma","ipa":"skɪl"},{"en":"talent","uz":"iste'dod","ipa":"ˈtælənt"},{"en":"manage to","uz":"uddalamoq, ulgurmoq","ipa":"ˈmænɪdʒ tuː"},{"en":"permission","uz":"ruxsat","ipa":"pəˈmɪʃn"},{"en":"allowed","uz":"ruxsat etilgan","ipa":"əˈlaʊd"},{"en":"possible","uz":"mumkin, imkoni bor","ipa":"ˈpɒsəbl"},{"en":"impossible","uz":"imkonsiz","ipa":"ɪmˈpɒsəbl"},{"en":"be good at","uz":"…da yaxshi bo'lmoq","ipa":"bi ɡʊd æt"},{"en":"by myself","uz":"o'zim, yolg'iz o'zim","ipa":"baɪ maɪˈself"}],"summary":["can — hozirgi qobiliyat va ruxsat; could — o'tmishdagi umumiy qobiliyat va muloyim iltimos (Could I…?).","Bitta aniq voqea, uddalagan (musbat) → was / were able to yoki managed to: I was able to catch the bus.","Kelajak va Present Perfect uchun be able to: I will be able to…, I haven't been able to… (will can ❌).","Hamma modal fe'llardan keyin to yo'q va -s yo'q: I can swim (I can to swim ❌)."]},{"id":"u15-l4","slug":"polite-requests-and-offers","title":"Polite requests and offers","titleUz":"Muloyim iltimos va taklif: Could you…? Would you like…?","goal":"Iltimosni muloyim aytasiz (Could you…? Can I…? Would you…?), takliflar berasiz (Would you like…? Shall I…? I'll…), ularga to'g'ri javob qaytarasiz va Give me water! kabi qo'pol eshitiladigan gaplardan qochasiz.","words":[{"en":"request","uz":"iltimos, so'rov","ipa":"rɪˈkwest"},{"en":"offer","uz":"taklif qilmoq; taklif","ipa":"ˈɒfə"},{"en":"polite","uz":"muloyim, odobli","ipa":"pəˈlaɪt"},{"en":"favour","uz":"yaxshilik, xizmat","ipa":"ˈfeɪvə"},{"en":"borrow","uz":"so'rab olmoq","ipa":"ˈbɒrəʊ"},{"en":"lend","uz":"so'rab bermoq, qarzga bermoq","ipa":"lend"},{"en":"pass","uz":"uzatmoq","ipa":"pɑːs"},{"en":"accept","uz":"qabul qilmoq","ipa":"əkˈsept"},{"en":"decline","uz":"(muloyimlik bilan) rad etmoq","ipa":"dɪˈklaɪn"},{"en":"certainly","uz":"albatta","ipa":"ˈsɜːtnli"}],"summary":["Buyruq (Give me…) qo'pol eshitiladi. Muloyim: Could you…? va I'd like…; I want… ishlatmang.","Iltimos: Can / Could / Would you + V1? Ruxsat: Can / Could / May I + V1?","Taklif: Would you like + ot / to + fe'l?, Shall I + V1?, I'll + V1. (Do you like…? taklif emas!)","borrow = men olaman; lend = men beraman. Rad etganda ham muloyim bo'ling: Sorry, I can't… / No, thanks."]},{"id":"u15-l5","slug":"giving-directions","title":"Giving directions","titleUz":"Yo'l ko'rsatish va tushuntirish","goal":"Yo'lni so'raysiz (How do I get to…? Is there a … near here?), yo'l ko'rsatasiz (turn left, go straight on, take the second turning), joylashuvni aytasiz (opposite, next to, between) va xaritadagi yo'nalishni inglizcha tushuntirasiz.","words":[{"en":"straight","uz":"to'g'ri (yo'nalish)","ipa":"streɪt"},{"en":"corner","uz":"burchak, ko'cha burchagi","ipa":"ˈkɔːnə"},{"en":"traffic lights","uz":"svetofor","ipa":"ˈtræfɪk laɪts"},{"en":"roundabout","uz":"aylana (yo'l)","ipa":"ˈraʊndəbaʊt"},{"en":"cross","uz":"kesib o'tmoq","ipa":"krɒs"},{"en":"bridge","uz":"ko'prik","ipa":"brɪdʒ"},{"en":"opposite","uz":"qarshisida","ipa":"ˈɒpəzɪt"},{"en":"between","uz":"o'rtasida","ipa":"bɪˈtwiːn"},{"en":"go past","uz":"yonidan o'tib ketmoq","ipa":"ɡəʊ pɑːst"},{"en":"turning","uz":"burilish (ko'cha)","ipa":"ˈtɜːnɪŋ"}],"summary":["Yo'lni so'rash: Excuse me, how do I get to…?, Is there a … near here?, Is it far?","Yo'nalish: Go straight on. Turn left / right. Take the second turning. Cross the road. Go past…","Joylashuv: next to, opposite, between … and …, behind, in front of, on the corner.","On the left / right (in emas). Yo'l tushuntirishda buyruq shakli qo'pol emas, tabiiy."]},{"id":"u15-l6","slug":"at-the-doctors","title":"At the doctor's","titleUz":"Shifokorda: kasallik va maslahat","goal":"Shifokorga yoki dorixonaga murojaat qilasiz: o'z holatingizni (I've got a headache, My back hurts, I feel dizzy) tushuntirasiz, What's the matter? kabi savollarga javob berasiz va should / shouldn't bilan oddiy kundalik maslahatlarni tushunasiz.","words":[{"en":"symptom","uz":"belgi (kasallik belgisi)","ipa":"ˈsɪmptəm"},{"en":"headache","uz":"bosh og'rig'i","ipa":"ˈhedeɪk"},{"en":"sore throat","uz":"tomoq og'rig'i","ipa":"sɔː θrəʊt"},{"en":"cough","uz":"yo'tal","ipa":"kɒf"},{"en":"temperature","uz":"isitma, harorat","ipa":"ˈtemprətʃə"},{"en":"appointment","uz":"qabulga yozilish, uchrashuv","ipa":"əˈpɔɪntmənt"},{"en":"ill","uz":"kasal","ipa":"ɪl"},{"en":"hurt","uz":"og'rimoq; lat yedirmoq","ipa":"hɜːt"},{"en":"pharmacy","uz":"dorixona","ipa":"ˈfɑːməsi"},{"en":"rest","uz":"dam; dam olmoq","ipa":"rest"}],"summary":["Savollar: What's the matter? Where does it hurt? When did it start?","Belgilar: I've got a headache / a cold / a cough / a sore throat. Og'riq: My back hurts. (I have headache ❌ — artikl kerak.)","Kundalik maslahat: You should rest / drink plenty of water / see a doctor. You shouldn't go to work.","I feel ill / bad (feel myself ❌). Qabul: I'd like to make an appointment. Jiddiy belgi bo'lsa — darhol shifokorga boring."]},{"id":"u15-l7","slug":"rules-and-signs","title":"Rules and signs","titleUz":"Qoidalar va belgilar: need to / needn't","goal":"need to (kerak) va don't need to / needn't (kerak emas) ni to'g'ri ishlatasiz, maktab, ish va yo'ldagi qoidalarni must / mustn't / have to bilan aytasiz hamda ingliz tilidagi eng keng tarqalgan belgi va yozuvlarni (No parking, Keep off the grass, Out of order) tushunasiz.","words":[{"en":"sign","uz":"belgi, yozuv","ipa":"saɪn"},{"en":"warning","uz":"ogohlantirish","ipa":"ˈwɔːnɪŋ"},{"en":"entrance","uz":"kirish joyi","ipa":"ˈentrəns"},{"en":"exit","uz":"chiqish joyi","ipa":"ˈeksɪt"},{"en":"queue","uz":"navbat","ipa":"kjuː"},{"en":"pedestrian","uz":"piyoda","ipa":"pəˈdestriən"},{"en":"speed limit","uz":"tezlik chegarasi","ipa":"ˈspiːd ˌlɪmɪt"},{"en":"out of order","uz":"ishlamaydi, buzilgan","ipa":"aʊt əv ˈɔːdə"},{"en":"give way","uz":"yo'l bermoq","ipa":"ɡɪv weɪ"},{"en":"keep off","uz":"yaqinlashmaslik, bosmaslik","ipa":"kiːp ɒf"}],"summary":["need to + V1 = kerak (She needs to go). Inkor va savol: don't / doesn't need to, Do I need to…?","Shart emas: don't need to, needn't (to yo'q!), don't have to. Taqiq: mustn't.","Qoidalar: must, mustn't, have to (Students must wear a uniform. You mustn't run.).","Belgilar: No parking, No smoking, Keep off the grass, Out of order, Give way, Exit — qisqa, ko'pincha taqiq."]},{"id":"u15-l8","slug":"unit-review-modal-verbs","title":"Unit review: modal verbs","titleUz":"Bosqich takrori: modal fe'llar","goal":"Bosqichning barcha mavzularini takrorlaysiz: must / have to / mustn't / don't have to, should, can / could / be able to, muloyim iltimos va takliflar, yo'l ko'rsatish, shifokorda va belgilar (need to / needn't). Modal fe'llarni to'g'ri shaklda ishlatib, 8–10 gaplik mini-hikoya tuza olasiz.","words":[{"en":"obligation","uz":"majburiyat","ipa":"ˌɒblɪˈɡeɪʃn"},{"en":"regulation","uz":"qoida, nizom","ipa":"ˌreɡjuˈleɪʃn"},{"en":"essential","uz":"juda zarur","ipa":"ɪˈsenʃl"},{"en":"instructions","uz":"yo'riqnoma","ipa":"ɪnˈstrʌkʃnz"},{"en":"emergency","uz":"favqulodda holat","ipa":"ɪˈmɜːdʒənsi"},{"en":"rude","uz":"qo'pol, odobsiz","ipa":"ruːd"},{"en":"careful","uz":"ehtiyotkor","ipa":"ˈkeəfl"},{"en":"helpful","uz":"foydali; yordam beradigan","ipa":"ˈhelpfl"},{"en":"remind","uz":"eslatmoq","ipa":"rɪˈmaɪnd"},{"en":"ahead","uz":"oldinda; oldinga","ipa":"əˈhed"}],"summary":["must / have to — majburiyat, mustn't — taqiq, don't have to / don't need to / needn't — shart emas.","should — maslahat; can / could / was able to / will be able to — qobiliyat va ruxsat.","Muloyim iltimos: Could you…? Can I…?; taklif: Would you like…? Shall I…? I'll…","Yo'l ko'rsatish: go straight on, turn left, opposite, next to, between. Shifokorda: I've got a…, My… hurts, You should…","Eng ko'p xatolar: must to, he musts, should to, will can, an advice, I have headache."]},{"id":"u15-l9","slug":"a-friend-has-a-problem-giving-advice","title":"A friend has a problem: giving advice","titleUz":"Do'stning muammosi: maslahat berish","goal":"Do'stingiz muammosini aytganda unga should / shouldn't va Why don't you…? bilan muloyim maslahat bera olasiz va maslahat so'ray olasiz.","words":[{"en":"problem","uz":"muammo","ipa":"ˈprɒb.ləm"},{"en":"worried","uz":"xavotirli","ipa":"ˈwʌr.id"},{"en":"solution","uz":"yechim","ipa":"səˈluː.ʃn"},{"en":"decide","uz":"qaror qilmoq","ipa":"dɪˈsaɪd"},{"en":"mistake","uz":"xato","ipa":"mɪˈsteɪk"},{"en":"lonely","uz":"yolg'iz, o'zini yolg'iz his qilgan","ipa":"ˈləʊn.li"}],"summary":["Maslahat: You should + V1; qilmaslik haqida: You shouldn't + V1. To va -s yo'q.","Do'stona taklif: Why don't you + V1? — bu sabab so'rash emas.","Maslahat so'rash: What should I do?","advice sanalmaydi: some advice, a piece of advice."]},{"id":"u15-l10","slug":"rules-at-university-and-at-work","title":"Rules at university and at work","titleUz":"Universitet va ishdagi qoidalar","goal":"Universitet va ishdagi qoidalarni must / mustn't, have to / don't have to, need to / needn't va can / can't bilan tushuntira olasiz.","words":[{"en":"lecture","uz":"ma'ruza","ipa":"ˈlek.tʃər"},{"en":"attend","uz":"qatnashmoq","ipa":"əˈtend"},{"en":"library","uz":"kutubxona","ipa":"ˈlaɪ.brər.i"},{"en":"staff","uz":"xodimlar","ipa":"stɑːf"},{"en":"absent","uz":"yo'q, qatnashmagan","ipa":"ˈæb.sənt"},{"en":"assignment","uz":"topshiriq","ipa":"əˈsaɪn.mənt"}],"summary":["must / have to — majburiyat; mustn't — taqiq (qilmang!).","don't have to / don't need to / needn't — shart emas. needn't dan keyin to yo'q.","can — ruxsat bor; can't — ruxsat yo'q: You can't park here.","Savol: Do I have to…? Do you need to…? (Does she have to…?)"]},{"id":"u15-l11","slug":"rules-advice-and-requests-final-review","title":"Rules, advice and requests: final review","titleUz":"Qoidalar, maslahat va iltimoslar: yakuniy takror","goal":"Bosqichdagi hamma narsani takrorlaysiz: must / have to, should, can / could / be able to, muloyim iltimos va takliflar, yo'l ko'rsatish, shifokorda va belgilar. Bir kunlik vaziyatda to'g'ri ibora tanlay olasiz.","words":[{"en":"reception","uz":"qabulxona, registratura","ipa":"rɪˈsep.ʃn"},{"en":"prescription","uz":"retsept","ipa":"prɪˈskrɪp.ʃn"},{"en":"pavement","uz":"trotuar","ipa":"ˈpeɪv.mənt"},{"en":"switch off","uz":"o'chirmoq","ipa":"swɪtʃ ɒf"},{"en":"quiet","uz":"tinch, jim","ipa":"ˈkwaɪ.ət"},{"en":"receipt","uz":"chek","ipa":"rɪˈsiːt"}],"summary":["must / have to — majburiyat, mustn't — taqiq, don't have to / needn't — shart emas.","should — maslahat; can / could / be able to — qobiliyat va ruxsat.","Muloyim iltimos: Could you…? Can I…?; taklif: Would you like…? Shall I…?","Yo'l: How do I get to…? Turn left. It's next to… Shifokorda: I've got a…, My… hurts.","Modal fe'ldan keyin 1-shakl: must go, should rest, needn't wait."]}]},{"id":"u16","n":16,"title":"Experiences and the world around us","titleUz":"Tajriba va dunyo: Present Perfect, who / which, majhul nisbat","description":"Present Perfect va Past Simple, for / since, who / which / that, majhul nisbat, frazali fe'llar va xat yozish.","canDo":["Present Perfect va Past Simple ni to'g'ri tanlayman","for va since bilan davomiylikni ayta olaman","who / which / that bilan gapni murakkablashtiraman","Rasmiy va norasmiy email yozaman"],"lessons":[{"id":"u16-l1","slug":"present-perfect-or-past-simple","title":"Present Perfect or Past Simple?","titleUz":"Present Perfect yoki Past Simple?","goal":"Present Perfect (I've been to Khiva) va Past Simple (I went to Khiva last year) farqini tushunasiz, ever, never, just, already, yet so'zlarini to'g'ri joyga qo'yasiz va I have seen him yesterday kabi mashhur xatodan qochasiz.","words":[{"en":"experience","uz":"tajriba","ipa":"ɪkˈspɪə.ri.əns"},{"en":"adventure","uz":"sarguzasht","ipa":"ədˈven.tʃər"},{"en":"abroad","uz":"chet elda, chet elga","ipa":"əˈbrɔːd"},{"en":"recently","uz":"yaqinda, so'nggi paytlarda","ipa":"ˈriː.sənt.li"},{"en":"so far","uz":"hozirgacha, shu paytgacha","ipa":"səʊ fɑː"},{"en":"once","uz":"bir marta","ipa":"wʌns"},{"en":"twice","uz":"ikki marta","ipa":"twaɪs"},{"en":"journey","uz":"yo'l, safar","ipa":"ˈdʒɜː.ni"},{"en":"souvenir","uz":"esdalik sovg'a","ipa":"ˌsuː.vəˈnɪər"},{"en":"lucky","uz":"omadli","ipa":"ˈlʌk.i"}],"summary":["Present Perfect (have / has + V3): tajriba, yangilik, hozirga aloqasi bor ish — vaqt aytilmaydi.","Past Simple: aniq tugagan vaqt — yesterday, last week, in 2020, two days ago. When bilan savol ham Past Simple.","ever, never, just, already, yet — Present Perfect so'zlari: Have you ever…? I've never… She's just… We've already… Not yet.","Xato: ~~I have seen him yesterday~~. To'g'risi: I saw him yesterday.","Suhbat: Have you ever been to…? — Yes, I have. I went there last…"]},{"id":"u16-l2","slug":"for-and-since","title":"For and since","titleUz":"For va since: how long?","goal":"How long have you lived here? savoliga for (for ten years) va since (since 2015) bilan javob berasiz va I live here since 2020 degan mashhur xatoni qilmaysiz.","words":[{"en":"move house","uz":"ko'chib o'tmoq","ipa":"muːv haʊs"},{"en":"neighbour","uz":"qo'shni","ipa":"ˈneɪ.bər"},{"en":"colleague","uz":"hamkasb","ipa":"ˈkɒl.iːɡ"},{"en":"member","uz":"a'zo","ipa":"ˈmem.bər"},{"en":"grow up","uz":"katta bo'lmoq, ulg'ayib voyaga yetmoq","ipa":"ɡrəʊ ʌp"},{"en":"own","uz":"egalik qilmoq","ipa":"əʊn"},{"en":"friendship","uz":"do'stlik","ipa":"ˈfrend.ʃɪp"},{"en":"for ages","uz":"juda uzoq vaqt, anchadan beri","ipa":"fɔːr ˈeɪ.dʒɪz"},{"en":"club","uz":"klub","ipa":"klʌb"},{"en":"since then","uz":"o'shandan beri","ipa":"sɪns ðen"}],"summary":["Davom etayotgan holat uchun: How long have you lived here? (Present Perfect), hozirgi zamon emas.","for + muddat (two years, ten minutes, ages); since + boshlanish nuqtasi (2019, Monday, I was ten).","Xatolar: I live here since 2020 ❌ → I have lived here since 2020 ✅. since two years ❌ → for two years.","ago Present Perfect bilan ishlatilmaydi: I moved here two years ago yoki I've lived here for two years.","Past Simple + for = tugagan davr: I lived in Bukhara for two years (endi yashamayman)."]},{"id":"u16-l3","slug":"relative-clauses","title":"Relative clauses","titleUz":"Who, which, that, where: ta'riflash","goal":"who, which, that, where yordamida gapni bog'laysiz (The man who lives next door is a doctor), narsa va odamlarni ta'riflaysiz va A dentist is a person who… kabi ta'rif berasiz. The book what I read xatosidan qochasiz.","words":[{"en":"dentist","uz":"tish shifokori","ipa":"ˈden.tɪst"},{"en":"tourist","uz":"sayyoh","ipa":"ˈtʊə.rɪst"},{"en":"mechanic","uz":"avtomexanik, mexanik","ipa":"məˈkæn.ɪk"},{"en":"bakery","uz":"novvoyxona, non do'koni","ipa":"ˈbeɪ.kər.i"},{"en":"pharmacy","uz":"dorixona","ipa":"ˈfɑː.mə.si"},{"en":"stadium","uz":"stadion","ipa":"ˈsteɪ.di.əm"},{"en":"tool","uz":"asbob, qurol","ipa":"tuːl"},{"en":"kettle","uz":"choynak (elektr)","ipa":"ˈket.əl"},{"en":"cousin","uz":"amakivachcha, xolavachcha","ipa":"ˈkʌz.ən"},{"en":"guest","uz":"mehmon","ipa":"ɡest"}],"summary":["who — odamlar, which — narsalar, that — odam yoki narsa, where — joylar.","Defining gapda vergul yo'q: The man who lives next door is a dentist. Ot oldin, tushuntirish keyin keladi.","Xatolar: ~~the book what I read~~ → the book (that) I read; ~~the man who he lives~~ → the man who lives.","To'ldiruvchi bo'lsa that / which ni tushirish mumkin: The film (that) we saw was long.","Ta'rif: A … is a person who / a thing that / a place where …"]},{"id":"u16-l4","slug":"the-passive","title":"The passive","titleUz":"Majhul nisbat: is made, was built","goal":"Present Simple va Past Simple majhul nisbatini tuzasiz (Cars are made in factories. The cake was baked by my mother), by ni faqat kerak bo'lganda qo'shasiz va I born, was happened kabi xatolardan qochasiz.","words":[{"en":"factory","uz":"zavod, fabrika","ipa":"ˈfæk.tər.i"},{"en":"produce","uz":"ishlab chiqarmoq","ipa":"prəˈdjuːs"},{"en":"build – built – built","uz":"qurmoq","ipa":"bɪld – bɪlt – bɪlt"},{"en":"invent","uz":"ixtiro qilmoq","ipa":"ɪnˈvent"},{"en":"repair","uz":"ta'mirlamoq","ipa":"rɪˈpeər"},{"en":"steal – stole – stolen","uz":"o'g'irlamoq","ipa":"stiːl – stəʊl – ˈstəʊ.lən"},{"en":"invite","uz":"taklif qilmoq","ipa":"ɪnˈvaɪt"},{"en":"deliver","uz":"yetkazib bermoq","ipa":"dɪˈlɪv.ər"},{"en":"damage","uz":"shikast yetkazmoq, zarar bermoq","ipa":"ˈdæm.ɪdʒ"},{"en":"discover","uz":"kashf qilmoq, topmoq","ipa":"dɪˈskʌv.ər"}],"summary":["Passive = be + V3. Present: Cars are made in factories. Past: The window was broken.","Savol va inkorda faqat be o'zgaradi: Is plov cooked here? The window wasn't broken. do / did kerak emas.","by + kim faqat ish bajaruvchi muhim bo'lsa: The cake was baked by my mother. Aks holda yozmang.","Xatolar: Cars made… (be yo'q), was broke (V2), was happened (o'timsiz fe'l), I born (to'g'risi: I was born)."]},{"id":"u16-l5","slug":"phrasal-verbs","title":"Phrasal verbs","titleUz":"Frazali fe'llar: get up, look for, turn on","goal":"10 ta eng ko'p ishlatiladigan frazali fe'lni (get up, turn on/off, look for, put on, take off, give up, find out, come back, wake up, sit down) o'rganasiz va ulardan ajraladiganlari (turn it on) bilan ajralmaydiganlarini (look for it) farqlaysiz.","words":[{"en":"get up","uz":"o'rnidan turmoq","ipa":"ɡet ʌp"},{"en":"turn on / turn off","uz":"yoqmoq / o'chirmoq","ipa":"tɜːn ɒn / tɜːn ɒf"},{"en":"look for","uz":"qidirmoq","ipa":"lʊk fɔː"},{"en":"put on","uz":"kiymoq","ipa":"pʊt ɒn"},{"en":"take off","uz":"yechmoq","ipa":"teɪk ɒf"},{"en":"give up","uz":"taslim bo'lmoq, tashlamoq","ipa":"ɡɪv ʌp"},{"en":"find out","uz":"bilib olmoq, aniqlamoq","ipa":"faɪnd aʊt"},{"en":"come back","uz":"qaytib kelmoq","ipa":"kʌm bæk"},{"en":"wake up","uz":"uyg'onmoq","ipa":"weɪk ʌp"},{"en":"sit down","uz":"o'tirmoq","ipa":"sɪt daʊn"}],"summary":["Frazali fe'l = fe'l + kichik so'z; ma'nosi o'zgaradi: look → look for, give → give up.","To'ldiruvchisiz: wake up, get up, sit down, come back. To'ldiruvchili: turn on/off, put on, take off, look for, give up, find out.","Ajraladigan fe'llarda olmosh o'rtada: turn it on, put them on, take it off. ❌ turn on it.","Ajralmaydigan: look for it, find out the answer.","wake up (uyg'onmoq) ≠ get up (o'rnidan turmoq); put on (kiymoq) ≠ wear (kiyib yurmoq)."]},{"id":"u16-l6","slug":"question-tags","title":"Question tags","titleUz":"Tasdiq savollari: isn't it? don't you?","goal":"Gap oxiriga to'g'ri question tag qo'shasiz (It's cold, isn't it? You like plov, don't you?), short answer (Yes, I do. No, I can't.) bilan javob berasiz va har gapga isn't it? qo'shish xatosidan qochasiz.","words":[{"en":"probably","uz":"ehtimol, katta ehtimol bilan","ipa":"ˈprɒb.ə.bli"},{"en":"definitely","uz":"shubhasiz, albatta","ipa":"ˈdef.ɪ.nət.li"},{"en":"obviously","uz":"ravshanki, shubhasiz","ipa":"ˈɒb.vi.əs.li"},{"en":"exactly","uz":"aynan, aniq","ipa":"ɪɡˈzækt.li"},{"en":"actually","uz":"aslida, haqiqatan","ipa":"ˈæk.tʃu.ə.li"},{"en":"perhaps","uz":"balki","ipa":"pəˈhæps"},{"en":"certainly","uz":"albatta, shubhasiz","ipa":"ˈsɜː.tən.li"},{"en":"anyway","uz":"baribir, har holda","ipa":"ˈen.i.weɪ"},{"en":"honestly","uz":"rostini aytsam","ipa":"ˈɒn.ɪst.li"},{"en":"apparently","uz":"ko'rinishidan, aytishlaricha","ipa":"əˈpær.ənt.li"}],"summary":["Darak gap (+) → inkor tag (−): She likes tea, doesn't she? Inkor gap (−) → darak tag (+): He can't swim, can he?","Tag gapdagi yordamchi fe'lni takrorlaydi; yo'q bo'lsa do / does / did. Tagda ot emas, olmosh (he, she, they, there).","Alohida: I'm late, aren't I? Let's go, shall we? Open the window, will you?","Qisqa javob: Yes / No + olmosh + yordamchi fe'l. Yes/No haqiqatga qarab aytiladi: You don't like coffee, do you? — Yes, I do.","isn't it? ni har gapga qo'shmang: tag gapga moslashadi."]},{"id":"u16-l7","slug":"writing-an-email","title":"Writing an email","titleUz":"Elektron xat yozish: do'stga va rasmiy","goal":"Elektron xatning tuzilishini bilasiz (mavzu, salomlashish, asosiy qism, xayrlashuv), do'stingizga norasmiy, notanish odamga esa muloyim rasmiy xat yozasiz (I am writing to ask… Could you please…? Yours sincerely) va ikkala uslubni aralashtirmaysiz.","words":[{"en":"subject","uz":"mavzu (xatning)","ipa":"ˈsʌbdʒɪkt"},{"en":"greeting","uz":"salomlashish","ipa":"ˈɡriːtɪŋ"},{"en":"sincerely","uz":"hurmat bilan (xat oxirida)","ipa":"sɪnˈsɪəli"},{"en":"apologise","uz":"uzr so'ramoq","ipa":"əˈpɒlədʒaɪz"},{"en":"confirm","uz":"tasdiqlamoq","ipa":"kənˈfɜːm"},{"en":"request","uz":"iltimos, so'rov","ipa":"rɪˈkwest"},{"en":"available","uz":"bo'sh, mavjud","ipa":"əˈveɪləbl"},{"en":"keep in touch","uz":"aloqada bo'lmoq","ipa":"kiːp ɪn tʌtʃ"},{"en":"look forward to","uz":"intizorlik bilan kutmoq","ipa":"lʊk ˈfɔːwəd tuː"},{"en":"message","uz":"xabar","ipa":"ˈmesɪdʒ"}],"summary":["Xat tuzilishi: mavzu → salomlashish → asosiy qism → yakun → xayrlashuv.","Norasmiy: Hi, Thanks for your email, Write soon, Best wishes — qisqartmalar mumkin.","Rasmiy: Dear Mr / Ms…, I am writing to…, Could you please…?, I look forward to hearing from you, Yours sincerely / faithfully.","Ismi ma'lum → sincerely; ismi noma'lum (Sir or Madam) → faithfully.","Uslublarni aralashtirmang va rasmiy xatda buyruq o'rniga Could you please…? ishlating."]},{"id":"u16-l8","slug":"unit-review-experiences","title":"Unit review: experiences","titleUz":"Bosqich takrori: tajriba va dunyo","goal":"Bosqichni mustahkamlaysiz: Present Perfect va Past Simple, for / since, who / which / that / where, majhul nisbat, frazali fe'llar, question tag va xat yozish — hammasini bitta matn va aralash mashqlarda ishlatasiz.","words":[{"en":"article","uz":"maqola","ipa":"ˈɑːtɪkl"},{"en":"century","uz":"asr","ipa":"ˈsentʃəri"},{"en":"invention","uz":"ixtiro","ipa":"ɪnˈvenʃn"},{"en":"popular","uz":"mashhur, ommabop","ipa":"ˈpɒpjələ"},{"en":"traditional","uz":"an'anaviy","ipa":"trəˈdɪʃənl"},{"en":"modern","uz":"zamonaviy","ipa":"ˈmɒdn"},{"en":"local","uz":"mahalliy","ipa":"ˈləʊkl"},{"en":"nearby","uz":"yaqin atrofda","ipa":"ˌnɪəˈbaɪ"},{"en":"wonder","uz":"hayratlanarli narsa; hayron bo'lmoq","ipa":"ˈwʌndə"},{"en":"similar","uz":"o'xshash","ipa":"ˈsɪmələ"}],"summary":["Present Perfect — tajriba va natija (vaqtsiz); Past Simple — aniq tugagan vaqt.","for + muddat, since + boshlanish; ago faqat Past Simple bilan.","who / which / that / where otdan keyin tushuntirish beradi; what ishlatilmaydi.","Passive: be + V3; frazali fe'llarda olmosh o'rtada (turn it on).","Question tag gapdagi yordamchi fe'lga qarab o'zgaradi; xat uslubi bir xil bo'lsin."]},{"id":"u16-l9","slug":"travel-experiences-have-you-ever","title":"Travel experiences: have you ever…?","titleUz":"Sayohat tajribasi: Have you ever…?","goal":"Sayohat haqida suhbatda Have you ever…? deb so'raysiz, Yes, I have / No, I haven't deb javob berasiz, keyin esa Past Simple bilan tafsilot (qachon, qayerda) aytasiz. Shuningdek, for va since bilan qancha vaqtdan beri yashayotganingizni aytasiz.","words":[{"en":"passport","uz":"pasport","ipa":"ˈpɑːspɔːt"},{"en":"flight","uz":"parvoz, reys","ipa":"flaɪt"},{"en":"luggage","uz":"yuk, bagaj","ipa":"ˈlʌɡɪdʒ"},{"en":"tour","uz":"ekskursiya, sayohat","ipa":"tʊə"},{"en":"view","uz":"manzara, ko'rinish","ipa":"vjuː"},{"en":"beach","uz":"plyaj, qirg'oq","ipa":"biːtʃ"}],"summary":["Tajribani so'rash: Have you ever + V3? Javob: Yes, I have. / No, I haven't.","Hech qachon bo'lmagan ish: I have never + V3.","Tafsilot (qachon, qayerda) so'ralsa yoki aniq vaqt bor bo'lsa — Past Simple.","Davom etayotgan holat: for + muddat, since + boshlanish nuqtasi."]},{"id":"u16-l10","slug":"explaining-what-something-is","title":"Explaining what something is","titleUz":"Narsa nima ekanini tushuntirish","goal":"Inglizcha so'zni bilmasangiz ham, uni who / which / that / where bilan ta'riflab tushuntira olasiz (It's a thing that…, It's a place where…) va majhul nisbat bilan qayerda, nimadan yasalganini aytasiz (It is made of…).","words":[{"en":"describe","uz":"ta'riflamoq","ipa":"dɪˈskraɪb"},{"en":"device","uz":"qurilma, asbob","ipa":"dɪˈvaɪs"},{"en":"container","uz":"idish, quti","ipa":"kənˈteɪnə"},{"en":"machine","uz":"mashina, apparat","ipa":"məˈʃiːn"},{"en":"material","uz":"material, xomashyo","ipa":"məˈtɪəriəl"},{"en":"useful","uz":"foydali","ipa":"ˈjuːsfl"}],"summary":["Odam → who (yoki that); narsa → that / which; joy → where. what bunday ishlatilmaydi.","So'zni bilmasangiz tushuntiring: It's a thing that…, It's a person who…, It's a place where…","Majhul nisbat: is / are / was / were + V3 (is made of wood, was built in 1990)."]},{"id":"u16-l11","slug":"experiences-and-the-world-final-review","title":"Experiences and the world: final review","titleUz":"Tajriba va dunyo: yakuniy takror","goal":"Bosqichning hammasini bir joyda takrorlaysiz: Present Perfect va Past Simple, for / since, who / which / that / where, majhul nisbat, frazali fe'llar, question tag va do'stga xat yozish — va ularni qisqa xat va savollarda ishlatasiz.","words":[{"en":"festival","uz":"festival, bayram","ipa":"ˈfestɪvl"},{"en":"tradition","uz":"an'ana","ipa":"trəˈdɪʃn"},{"en":"culture","uz":"madaniyat","ipa":"ˈkʌltʃə"},{"en":"celebrate","uz":"nishonlamoq","ipa":"ˈselɪbreɪt"},{"en":"guidebook","uz":"yo'l ko'rsatkich kitob","ipa":"ˈɡaɪdbʊk"},{"en":"attraction","uz":"diqqatga sazovor joy","ipa":"əˈtrækʃn"}],"summary":["Tajriba — Present Perfect; aniq vaqt (yesterday, ago, in 2020) — Past Simple.","for + muddat, since + boshlanish nuqtasi.","who (odam), which / that (narsa), where (joy); passive: be + V3.","Frazali fe'lda olmosh o'rtada (turn it off); question tag qarama-qarshi bo'ladi.","Do'stga xat norasmiy: Hi, … Best wishes; rasmiy xat: Dear …, Yours sincerely."]}]},{"id":"u17","n":17,"title":"Work, money and everyday life","titleUz":"Ish, pul va kundalik hayot: suhbatlar va yozish","description":"Fe'l qoliplari, kasblar, pul va xaridlar, texnologiya, sayohat, restoran va A2 yakuniy takrori.","canDo":["Ish suhbatida o'zimni tanishtiraman","Do'konda, mehmonxonada va restoranda muammosiz muomala qilaman","Qisqa CV va xabar yozaman","Texnologiya haqida gapiraman"],"lessons":[{"id":"u17-l1","slug":"like-doing-or-want-to-do","title":"Like doing or want to do?","titleUz":"Fe'l qolipi: like doing, want to do","goal":"Ikki fe'l ketma-ket kelganda -ing yoki to + V1 ni to'g'ri tanlaysiz: enjoy swimming, want to go, would like to ask. Shuningdek Let's…, Why don't we…?, How about…? bilan taklif qilishni o'rganasiz va I like swim, I want go, enjoy to kabi xatolardan qutulasiz.","words":[{"en":"enjoy","uz":"zavqlanmoq, yoqtirmoq","ipa":"ɪnˈdʒɔɪ"},{"en":"hate","uz":"yomon ko'rmoq","ipa":"heɪt"},{"en":"hope","uz":"umid qilmoq","ipa":"həʊp"},{"en":"decide","uz":"qaror qilmoq","ipa":"dɪˈsaɪd"},{"en":"plan","uz":"rejalashtirmoq","ipa":"plæn"},{"en":"prefer","uz":"afzal ko'rmoq","ipa":"prɪˈfɜː"},{"en":"finish","uz":"tugatmoq","ipa":"ˈfɪnɪʃ"},{"en":"practise","uz":"mashq qilmoq","ipa":"ˈpræktɪs"},{"en":"refuse","uz":"rad etmoq, ko'nmaslik","ipa":"rɪˈfjuːz"},{"en":"promise","uz":"va'da bermoq","ipa":"ˈprɒmɪs"}],"summary":["enjoy, finish, stop, practise + -ing: I enjoy swimming. Hech qachon enjoy to swim emas.","want, need, hope, decide, plan, promise + to + V1: I want to go. \"to\" ni tushirib qoldirmang.","like, love, hate, prefer + -ing — umumiy yoqtirish; would like to + V1 — hozirgi yoki yaqin istak va muloyim iltimos.","Taklif: Let's / Why don't we / Shall we + V1, How about + -ing."]},{"id":"u17-l2","slug":"jobs-and-interviews","title":"Jobs and interviews","titleUz":"Kasblar va ish suhbati","goal":"Kasblar nomini artikl bilan to'g'ri aytasiz (I'm an engineer), work as / for / in farqini bilasiz, I've worked here for five years kabi tajribangiz haqida gapirasiz va ish suhbatida o'zingizni tanishtirish, kuchli tomonlaringizni aytish hamda oddiy savollarga javob berishni o'rganasiz.","words":[{"en":"apply","uz":"ishga murojaat qilmoq","ipa":"əˈplaɪ"},{"en":"interview","uz":"ish suhbati","ipa":"ˈɪntəvjuː"},{"en":"experience","uz":"tajriba","ipa":"ɪkˈspɪəriəns"},{"en":"salary","uz":"oylik maosh","ipa":"ˈsæləri"},{"en":"colleague","uz":"hamkasb","ipa":"ˈkɒliːɡ"},{"en":"manager","uz":"menejer, boshliq","ipa":"ˈmænɪdʒə"},{"en":"skill","uz":"ko'nikma","ipa":"skɪl"},{"en":"part-time","uz":"yarim kunlik","ipa":"ˌpɑːt ˈtaɪm"},{"en":"full-time","uz":"to'liq kunlik","ipa":"ˌfʊl ˈtaɪm"},{"en":"reliable","uz":"ishonchli","ipa":"rɪˈlaɪəbl"}],"summary":["Kasb oldidan a / an: I'm a nurse, She's an engineer. Ko'plikda artikl yo'q.","work as (lavozim), work for (kompaniya), work in / at (joy).","Hozirgacha davom etayotgan ish: have / has + V3 + for / since: I've worked here for 3 years.","Kuchli tomonlar: I'm + sifat, I'm good at + -ing, I can + V1.","Suhbatda muloyim va aniq bo'ling: I'd like to…, Thank you for your time."]},{"id":"u17-l3","slug":"money-and-shopping","title":"Money and shopping","titleUz":"Pul va xaridlar: narx, chegirma, qaytarish","goal":"Do'konda va bozorda narxni so'raysiz (How much is it? How much are these?), narxlarni to'g'ri aytasiz, chegirma so'raysiz, naqd yoki karta bilan to'laysiz, tovarni qaytarasiz va muammo bo'lsa muloyim shikoyat qilasiz. How much costs? kabi xatolardan qochasiz.","words":[{"en":"price","uz":"narx","ipa":"praɪs"},{"en":"discount","uz":"chegirma","ipa":"ˈdɪskaʊnt"},{"en":"receipt","uz":"chek","ipa":"rɪˈsiːt"},{"en":"change","uz":"qaytim; maydalangan pul","ipa":"tʃeɪndʒ"},{"en":"refund","uz":"pulni qaytarish","ipa":"ˈriːfʌnd"},{"en":"cash","uz":"naqd pul","ipa":"kæʃ"},{"en":"bargain","uz":"arzon va foydali xarid","ipa":"ˈbɑːɡɪn"},{"en":"cheap","uz":"arzon","ipa":"tʃiːp"},{"en":"expensive","uz":"qimmat","ipa":"ɪkˈspensɪv"},{"en":"afford","uz":"imkoni bo'lmoq (pul jihatdan)","ipa":"əˈfɔːd"}],"summary":["Narx so'rash: How much is / are…? yoki How much does / do… cost? — hech qachon How much costs? emas.","Narxlar: forty-five thousand so'm — thousand / hundred / million son bilan -s olmaydi.","To'lov: pay by card / in cash, Keep the change, Could I have a receipt?","Qaytarish: I bought this yesterday, but it doesn't work. Could I have a refund / exchange it?","Shikoyatda muloyim bo'ling: Excuse me, I'm sorry, but…, Could you…?"]},{"id":"u17-l4","slug":"technology","title":"Technology","titleUz":"Texnologiya va internet","goal":"Telefon, kompyuter va internet haqidagi kundalik so'zlarni bilasiz (battery, screen, password, download, log in), texnik muammoni tushuntirasiz, qadam-baqadam ko'rsatma berasiz (First… Then… Don't forget to…), qisqa onlayn xabarlar yozasiz va telefon suhbatini olib borasiz (Who's calling? Hold on. I'll call you back.).","words":[{"en":"battery","uz":"batareya","ipa":"ˈbætəri"},{"en":"screen","uz":"ekran","ipa":"skriːn"},{"en":"password","uz":"parol","ipa":"ˈpɑːswɜːd"},{"en":"charger","uz":"zaryadlovchi","ipa":"ˈtʃɑːdʒə"},{"en":"download","uz":"yuklab olmoq","ipa":"ˌdaʊnˈləʊd"},{"en":"website","uz":"veb-sayt","ipa":"ˈwebsaɪt"},{"en":"online","uz":"onlayn, internetda","ipa":"ˌɒnˈlaɪn"},{"en":"update","uz":"yangilamoq","ipa":"ˌʌpˈdeɪt"},{"en":"log in","uz":"tizimga kirmoq","ipa":"lɒɡ ɪn"},{"en":"delete","uz":"o'chirib tashlamoq","ipa":"dɪˈliːt"}],"summary":["Asosiy so'zlar: battery, screen, charger, password, download, log in, update, delete.","Frazali fe'llarda olmosh o'rtada: turn it off, plug it in; ot bilan ikkala tartib mumkin.","Ko'rsatma: buyruq (V1) + first, then, next, finally; inkorda Don't + V1.","try + -ing — sinab ko'rmoq (Try restarting it); qisqartmalar (BTW, ASAP, thx) faqat norasmiy yozuvda.","Telefonda: Can I speak to…? Who's calling? This is… Hold on. I'll call you back."]},{"id":"u17-l5","slug":"travel-and-hotels","title":"Travel and hotels","titleUz":"Sayohat va mehmonxona","goal":"Mehmonxonada xona bron qilasiz, check-in / check-out qilasiz, kerakli narsalarni muloyim so'raysiz (Could I have…? Is there…?), vokzal va aeroportda chipta olasiz, perron va reysni so'raysiz hamda luggage kabi sanalmaydigan so'zlarni to'g'ri ishlatasiz.","words":[{"en":"reservation","uz":"bron qilish","ipa":"ˌrezəˈveɪʃn"},{"en":"luggage","uz":"yuk, bagaj","ipa":"ˈlʌɡɪdʒ"},{"en":"boarding pass","uz":"bort talonchasi","ipa":"ˈbɔːdɪŋ pɑːs"},{"en":"platform","uz":"perron","ipa":"ˈplætfɔːm"},{"en":"delay","uz":"kechikish; kechiktirmoq","ipa":"dɪˈleɪ"},{"en":"return ticket","uz":"borib-kelish chiptasi","ipa":"rɪˈtɜːn ˈtɪkɪt"},{"en":"check in","uz":"ro'yxatdan o'tmoq","ipa":"tʃek ɪn"},{"en":"check out","uz":"hisob-kitob qilib chiqib ketmoq","ipa":"tʃek aʊt"},{"en":"available","uz":"bo'sh, mavjud","ipa":"əˈveɪləbl"},{"en":"included","uz":"narxga kiritilgan","ipa":"ɪnˈkluːdɪd"}],"summary":["Bron: I'd like to book a… room for… nights. Savol: Is breakfast included? Do you have any rooms available?","Muloyim iltimos: Could I have…? / Could you…?; borligini so'rash: Is there… / Are there any…?","Jadval — Present Simple: What time does the train leave? (does + V1).","luggage, baggage — sanalmaydigan ot: My luggage is heavy, hech qachon luggages.","Aeroport ketma-ketligi: check-in → boarding pass → passport control → gate."]},{"id":"u17-l6","slug":"restaurants-and-food","title":"Restaurants and food","titleUz":"Restoran va ovqat buyurtma qilish","goal":"Restoran va choyxonada buyurtma berasiz (I'll have… / Could I have…?), menyuni tushunasiz, allergiya va ehtiyojlaringizni aytasiz, hisob so'raysiz va sanaladigan hamda sanalmaydigan ovqat nomlarini (some, any, much, many, a bowl of) to'g'ri ishlatasiz.","words":[{"en":"menu","uz":"menyu","ipa":"ˈmenjuː"},{"en":"starter","uz":"gazak, birinchi bo'lim","ipa":"ˈstɑːtə"},{"en":"dessert","uz":"shirinlik","ipa":"dɪˈzɜːt"},{"en":"bill","uz":"hisob (restoranda)","ipa":"bɪl"},{"en":"tip","uz":"choy puli","ipa":"tɪp"},{"en":"allergic","uz":"allergiyasi bor","ipa":"əˈlɜːdʒɪk"},{"en":"vegetarian","uz":"vegetarian","ipa":"ˌvedʒəˈteəriən"},{"en":"spicy","uz":"achchiq, ziravorli","ipa":"ˈspaɪsi"},{"en":"recommend","uz":"tavsiya qilmoq","ipa":"ˌrekəˈmend"},{"en":"delicious","uz":"mazali","ipa":"dɪˈlɪʃəs"}],"summary":["Buyurtma: I'll have… / Could I have…? / I'd like…, please. — I want emas.","Ogohlantirish: I'm allergic to…, I'm a vegetarian, without onions, Is there any … in it?","Sanalmaydigan ovqatlar: some / any / much + o'lchov: a cup of tea, a bowl of soup, a piece of bread.","Taklifda some (Would you like some tea?), inkor va savolda any.","Hisob: Could we have the bill, please? Is service included? Maqtash: It was delicious!"]},{"id":"u17-l7","slug":"writing-cv-and-short-messages","title":"Writing: CV and short messages","titleUz":"Rezyume va qisqa xat yozish","goal":"Inglizcha CV (rezyume) tuzasiz, ish uchun qisqa cover message yozasiz (I am writing to apply for…), shuningdek qisqa xabar, eslatma va taklifnomalar yozib, ularga muloyim javob berasiz (I'd love to come. Sorry, I can't.). Rasmiy va norasmiy uslubni farqlaysiz.","words":[{"en":"qualification","uz":"malaka, diplom","ipa":"ˌkwɒlɪfɪˈkeɪʃn"},{"en":"reference","uz":"tavsiyanoma","ipa":"ˈrefrəns"},{"en":"responsible","uz":"mas'ul","ipa":"rɪˈspɒnsəbl"},{"en":"manage","uz":"boshqarmoq","ipa":"ˈmænɪdʒ"},{"en":"organise","uz":"tashkil qilmoq","ipa":"ˈɔːɡənaɪz"},{"en":"attach","uz":"biriktirmoq","ipa":"əˈtætʃ"},{"en":"invitation","uz":"taklifnoma","ipa":"ˌɪnvɪˈteɪʃn"},{"en":"reply","uz":"javob bermoq; javob","ipa":"rɪˈplaɪ"},{"en":"regards","uz":"hurmat bilan (xat oxirida)","ipa":"rɪˈɡɑːdz"},{"en":"deadline","uz":"oxirgi muddat","ipa":"ˈdedlaɪn"}],"summary":["CV bo'limlari: Personal details, Profile, Work experience, Education, Skills, References — eng yangi ish birinchi.","CV da qisqa iboralar: Organised events. Responsible for managing… ; \"I\" siz.","Cover message: Dear… / I am writing to apply for… / I have attached my CV. / I look forward to hearing from you. / Yours sincerely.","Taklifnoma: Would you like to come to…? Please reply by… Javob: I'd love to! / Sorry, I can't. I have to…","Norasmiy va rasmiy uslubni aralashtirmang: Hi… See you! va Dear… Best regards."]},{"id":"u17-l8","slug":"a2-final-review","title":"A2 final review","titleUz":"A2 yakuniy takrori: hamma zamonlar va modal fe'llar","goal":"Pre-Intermediate darajasini yakunlaysiz: o'tgan zamon (Past Simple, Past Continuous, used to), kelajak (going to, will, might, if), taqqoslash, modal fe'llar (must, should, can, could), Present Perfect, passive va fe'l qoliplari — hammasini bitta matn va aralash mashqlarda qo'llaysiz.","words":[{"en":"improve","uz":"yaxshilanmoq, yaxshilamoq","ipa":"ɪmˈpruːv"},{"en":"progress","uz":"taraqqiyot, o'sish","ipa":"ˈprəʊɡres"},{"en":"achieve","uz":"erishmoq","ipa":"əˈtʃiːv"},{"en":"confidence","uz":"o'ziga ishonch","ipa":"ˈkɒnfɪdəns"},{"en":"fluent","uz":"ravon","ipa":"ˈfluːənt"},{"en":"vocabulary","uz":"lug'at boyligi","ipa":"vəˈkæbjələri"},{"en":"mistake","uz":"xato","ipa":"mɪˈsteɪk"},{"en":"memorise","uz":"yodlamoq","ipa":"ˈmeməraɪz"},{"en":"keep going","uz":"davom etmoq, to'xtamaslik","ipa":"kiːp ˈɡəʊɪŋ"},{"en":"nervous","uz":"hayajonlangan, asabiy","ipa":"ˈnɜːvəs"}],"summary":["Past Simple (tugagan), Past Continuous (jarayon), used to (eski odat), Present Perfect (tajriba, natija, for / since).","Kelajak: going to (reja), will (qaror), Present Continuous (kelishilgan), might (ehtimol), if + Present, will.","Taqqoslash: -er / more … than, the -est / the most, as … as, too / enough.","Modal fe'llar: must, mustn't, don't have to, should, can, could; muloyim iltimos — Could you…? Would you like…?","Passive (be + V3), who / which / that / where, fe'l qoliplari (enjoy -ing, want to)."]},{"id":"u17-l9","slug":"returning-an-item-to-a-shop","title":"Returning an item to a shop","titleUz":"Do'konga narsani qaytarish","goal":"Do'konga borib, narsani qaytarish yoki almashtirishni muloyim so'raysiz: nima bo'lganini tushuntirasiz (It's too small. It doesn't work.), chekni ko'rsatasiz va refund yoki exchange so'raysiz. Kerak bo'lsa, shikoyatni qo'pol emas, muloyim aytasiz.","words":[{"en":"faulty","uz":"nuqsonli, ishlamaydigan","ipa":"ˈfɔːlti"},{"en":"damaged","uz":"shikastlangan","ipa":"ˈdæmɪdʒd"},{"en":"complaint","uz":"shikoyat","ipa":"kəmˈpleɪnt"},{"en":"size","uz":"o'lcham","ipa":"saɪz"},{"en":"fit","uz":"mos kelmoq (o'lcham)","ipa":"fɪt"},{"en":"exchange","uz":"almashtirmoq","ipa":"ɪksˈtʃeɪndʒ"}],"summary":["Qaytarishda 3 qadam: muammoni ayting → chekni ko'rsating → muloyim so'rang.","Foydali iboralar: I'd like to return this. Could I have a refund? Can I exchange it for…?","Muammo: it's too small, it doesn't work, it's damaged, it's faulty.","Muloyim bo'ling: Excuse me, I'm sorry, but…, Could you…, please?"]},{"id":"u17-l10","slug":"booking-a-table-by-phone","title":"Booking a table by phone","titleUz":"Telefonda stol band qilish","goal":"Restoranga telefon qilib stol band qilasiz: sana, vaqt va odamlar sonini aytasiz, o'rin haqida (by the window, outside, quiet) muloyim iltimos qilasiz va bronni tasdiqlaysiz.","words":[{"en":"book","uz":"band qilmoq","ipa":"bʊk"},{"en":"reserve","uz":"oldindan band qilmoq","ipa":"rɪˈzɜːv"},{"en":"quiet","uz":"tinch","ipa":"ˈkwaɪət"},{"en":"corner","uz":"burchak","ipa":"ˈkɔːnə"},{"en":"terrace","uz":"terrasa, ochiq maydoncha","ipa":"ˈterəs"},{"en":"confirm","uz":"tasdiqlamoq","ipa":"kənˈfɜːm"}],"summary":["Bron qilish: I'd like to book a table for four on Friday at eight.","Predloglar: on + kun, at + soat, for + odamlar soni.","Iltimoslar: Could we have a table by the window / in a quiet corner / outside?","Oxirida bronni tasdiqlang: So that's a table for…"]},{"id":"u17-l11","slug":"pre-intermediate-final-review","title":"Pre-Intermediate: final review","titleUz":"Pre-Intermediate: yakuniy takror","goal":"Butun Pre-Intermediate darajani qisqa takrorlaysiz: o'tgan zamon, kelajak, taqqoslash, modal fe'llar, Present Perfect, passive, relative clauses va kundalik vaziyatlar. Qaysi mavzu kuchli, qaysi biri takrorni talab qilishini bilib olasiz.","words":[{"en":"revise","uz":"takrorlamoq","ipa":"rɪˈvaɪz"},{"en":"level","uz":"daraja","ipa":"ˈlevl"},{"en":"grammar","uz":"grammatika","ipa":"ˈɡræmə"},{"en":"pronunciation","uz":"talaffuz","ipa":"prəˌnʌnsiˈeɪʃn"},{"en":"exam","uz":"imtihon","ipa":"ɪɡˈzæm"},{"en":"certificate","uz":"sertifikat","ipa":"səˈtɪfɪkət"}],"summary":["O'tgan zamon: Past Simple (V2), Past Continuous (was/were + -ing), used to.","Kelajak: going to (reja), will (qaror), if + Present, will + V1.","Taqqoslash va modal fe'llar: cheaper than, the cheapest; must, should, could.","Present Perfect, passive, relative clauses: have + V3, was + V3, who / which / that.","Kundalik gaplarda muloyim bo'ling: Could I…, please? I'd like to…"]}]}]}];
